  FT["PH-H8790"] = {"id":"PH-H8790","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10337_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Samal市","en":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in the Island Garden City of Samal, Province of Davao Del Norte Into a Regular LTO District Office, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in the Island Garden City of Samal, Province of Davao Del Norte Into a Regular LTO District Office, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật chuyển đổi Văn phòng mở rộng Land Transportation Office thành Văn phòng Khu vực Regular LTO tại Thành phố Vườn Đảo Samal, Tỉnh Davao Del Norte, và phân bổ kinh phí cho mục đích này, và cho các mục đích khác","th":"พระราชบัญญัติเปลี่ยนสถานะสำนักงานขยาย Land Transportation Office เป็น สำนักงานเขต Regular LTO ในเมืองสวนเกาะ Samal จังหวัด Davao Del Norte และจัดสรรเงินทุนสำหรับการนี้ และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah status Kantor Perluasan Land Transportation Office menjadi Kantor Distrik Regular LTO di Kota Taman Pulau Samal, Provinsi Davao Del Norte, dan mengalokasikan dana untuk itu, dan untuk tujuan lain","ms":"Akta menukar status Pejabat Lanjutan Land Transportation Office kepada Pejabat Daerah Regular LTO di Bandar Taman Pulau Samal, Wilayah Davao Del Norte, dan memperuntukkan dana untuk itu, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10337","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10337_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8790-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) Extension Office located in the Island Garden City of Samal, Province of Davao del Norte is hereby converted into a regular LTO District Office."}},{"id":"PH-H8790-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation and Communications shall issue rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H8790-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the LTO District Office in the Island Garden City of Samal, Province of Davao del Norte, the initial funding of which shall be charged against the current year’s appropriations of the Island Garden City of Samal LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H8790-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8791"] = {"id":"PH-H8791","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10338_2012.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Dasmariñ 市","en":"An Act Converting the Extension Office of the Land Transportation Office (LTO) in the City of Dasmariñas, Cavite Into a Regular District Office to Be Known as the LTO District Office of Dasmariñas City, Cavite, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Converting the Extension Office of the Land Transportation Office (LTO) in the City of Dasmariñas, Cavite Into a Regular District Office to Be Known as the LTO District Office of Dasmariñas City, Cavite, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật chuyển đổi Văn phòng mở rộng Land Transportation Office thành Văn phòng Khu vực LTO Dasmariñas City, Cavite tại Thành phố Dasmariñas, và phân bổ kinh phí cho mục đích này, và cho các mục đích khác","th":"พระราชบัญญัติเปลี่ยนสถานะสำนักงานขยาย Land Transportation Office เป็น สำนักงานเขต LTO Dasmariñas City, Cavite ในเมือง Dasmariñas และจัดสรรเงินทุนสำหรับการนี้ และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah status Kantor Perluasan Land Transportation Office menjadi Kantor Distrik LTO Dasmariñas City, Cavite di Kota Dasmariñas, dan mengalokasikan dana untuk itu, dan untuk tujuan lain","ms":"Akta menukar status Pejabat Lanjutan Land Transportation Office kepada Pejabat Daerah LTO Dasmariñas City, Cavite di Bandar Dasmariñas, dan memperuntukkan dana untuk itu, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10338","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10338_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8791-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Extension Office of the Land Transportation Office (LTO) in the City of Dasmariñas, Cavite is hereby converted into a regular District Office to be known as the LTO District Office of Dasmariñas City, Cavite."}},{"id":"PH-H8791-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the LTO District Office in Dasmariñas City, Cavite, the initial funding of which shall be charged against the current year’s appropriations of the Dasmariñas City LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H8791-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8792"] = {"id":"PH-H8792","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10339_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"司法重组法 1980","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Five (5) Additional Branches of the Regional Trial Court to Be Stationed At the City of Calamba and the Municipalities of Los Baños and Cabuyao, All in the Province of Laguna, Amending for the Purpose Section 14, Paragraph (E) of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10339","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10339_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8792-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Five (5) additional Regional Trial Court branches in the Fourth Judicial Region are hereby created with three (3) seats at the City of Calamba and one (1) seat each in the municipalities of Los Baños and Cabuyao, all in the Province of Laguna.\nThe Supreme Court shall assign the branch number of the newly-created branches of the Regional Trial Court in the Fourth Judicial Region."}},{"id":"PH-H8792-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of the five (5) additional branches of the Regional Trial Court to be stationed at the City of Calamba and the municipalities of Los Baños and Cabuyao, all in the Province of Laguna, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8792-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Supreme Court shall issue the necessary rules and regulations for the effective implementation of this Act and if warranted, the realignment of seats of existing branches and their territorial jurisdiction."}},{"id":"PH-H8792-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 14(e) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8792-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Judiciary Reorganization Act of 1980","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8793"] = {"id":"PH-H8793","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10340_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Bogo市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Five (5) Additional Branches of the Regional Trial Court to Be Stationed At the City of Bogo, Province of Cebu, Amending for the Purpose Section 14, Paragraph (H) of Batas Pambansa Blg. 129, as Amended, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10340","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10340_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8793-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created five (5) additional Regional Trial Court branches in the Seventh Judicial Region with seats at the City of Bogo, Province of Cebu.\nThe Supreme Court shall assign the branch number of the newly-created branches of the Regional Trial Court in the Seventh Judicial Region."}},{"id":"PH-H8793-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of five (5) additional branches of the Regional Trial Court in the Province of Cebu to be stationed at the City of Bogo, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8793-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(h) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8793-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8794"] = {"id":"PH-H8794","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10341_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Valenzuela市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Four (4) Additional Branches of the Regional Trial Court and Three (3) Additional Branches of the Metropolitan Trial Court to Be Stationed At the City of Valenzuela, Metro Manila., Amending for the Purpose Section 14(D) and Section 27 of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10341","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10341_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8794-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Four (4) additional Regional Trial Court branches and three (3) additional Metropolitan Trial Court branches are hereby created in the National Capital Judicial Region with seats at the City of Valenzuela, Metro Manila.\nThe Supreme Court shall assign the branch number of the newly-created branches of the Regional Trial Court and the Metropolitan Trial Court in the National Capital Judicial Region."}},{"id":"PH-H8794-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of four (4) additional branches of the Regional Trial Court and three (3) additional branches of the Metropolitan Trial Court to be stationed at the City of Valenzuela, Metro Manila, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8794-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(d) and Section 27 of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8794-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8795"] = {"id":"PH-H8795","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10342_2012.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将授予 Quest 广播公司（原 SBS Radio Network，Inc.）在菲律宾建设、安装、设立、运营和维护无线电广播站的特许经营权续展的法案","en":"An Act Renewing the Franchise Granted to Quest Broadcasting, Inc. (Formerly SBS Radio Network, Inc.) a Franchise to Construct, Install, Establish, Operate and Maintain Radio Broadcasting Stations in the Philippines","orig":"An Act Renewing the Franchise Granted to Quest Broadcasting, Inc. (Formerly SBS Radio Network, Inc.) a Franchise to Construct, Install, Establish, Operate and Maintain Radio Broadcasting Stations in the Philippines","vi":"Đạo luật gia hạn đặc quyền đã cấp cho Quest Broadcasting, Inc.","th":"พระราชบัญญัติต่ออายุสัมปทานที่ให้แก่ Quest Broadcasting, Inc.","id":"Undang-Undang memperpanjang konsesi yang diberikan kepada Quest Broadcasting, Inc.","ms":"Akta melanjutkan konsesi yang diberikan kepada Quest Broadcasting, Inc."},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10342","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10342_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8795-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Quest Broadcasting. Inc. (formerly SBS Radio Network, Inc.), hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations in the Philippines, where frequencies and/or channels are still available for radio broadcasting, through microwave, satellite or whatever means, including the use of any new technologies in radio systems, with the corresponding technological auxiliaries and facilities, special broadcast and other program and distribution services and relay stations."}},{"id":"PH-H8795-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or availability thereof."}},{"id":"PH-H8795-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission (NTC) the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H8795-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all tames sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obscene and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H8795-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H8795-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to comply with any of the following conditions:\n(a) Commence operations within one (1) year from the approval of its operating permit by the NTC;\n(b) Operate continuously for two (2) years: and\n(c) Commence operations within three (3) years from the effectivity of this Act."}},{"id":"PH-H8795-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H8795-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bond. – The grantee shall file a bond with the NTC in the amount that the NTC shall determine to guarantee compliance with and fulfillment of the conditions under which this franchise is granted. If after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the same, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H8795-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast, from its stations: Provided, That the grantee, during any broadcast shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H8795-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H8795-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Nontransferability of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or m parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. The conditions, terms, restrictions and limitations set by this Act shall be imposed on any person or entity to which this franchise is sold, transferred or assigned."}},{"id":"PH-H8795-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer at least, thirty per centum (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the time it has achieved the status of a national broadcasting network. A \"national broadcasting network\" is hereby defined as one that operates three (3) or more radio and/or television stations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H8795-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption or immunity granted under existing franchise, or which may hereafter be granted for radio and/or television broadcasting, shall ipso facto become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H8795-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law, which Congress may hereafter enact."}},{"id":"PH-H8795-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H8795-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other o revisions not affected thereby shall remain valid."}},{"id":"PH-H8795-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H8795-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication, upon the initiative of the grantee, in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to Quest Broadcasting, Inc. (Formerly SBS Radio Network, Inc.) a Franchise to Construct, Install, Establish, Operate and Maintain Radio Broadcasting Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8796"] = {"id":"PH-H8796","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10343_2012.html","fetchedAt":"2026-10-06","articleCount":23,"structureMode":"ARTICLE","title":{"zh":"将授予 Philippine Global Communications，Inc. 的特许经营权再续展二十五年，为此修订第 4617 号共和国法及其相关条款的法案","en":"An Act Renewing the Franchise Granted to Philippine Global Communications, Inc. (Formerly RCA Communications, Inc.) for Another Twenty-Five (25) Years, Amending for the Purpose Republic Act No. 4617","orig":"An Act Renewing the Franchise Granted to Philippine Global Communications, Inc. (Formerly RCA Communications, Inc.) for Another Twenty-Five (25) Years, Amending for the Purpose Republic Act No. 4617","vi":"Đạo luật gia hạn thêm 25 năm đặc quyền đã cấp cho Philippine Global Communications, Inc.","th":"พระราชบัญญัติต่ออายุสัมปทานที่ให้แก่ Philippine Global Communications, Inc. อีก 25 ปี","id":"Undang-Undang memperpanjang selama 25 tahun lagi konsesi yang diberikan kepada Philippine Global Communications, Inc.","ms":"Akta melanjutkan selama 25 tahun lagi konsesi yang diberikan kepada Philippine Global Communications, Inc."},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10343","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 23 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10343_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8796-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, there is hereby granted to Philippine Global Communications, Inc. (formerly RCA Communications, Inc.), hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, throughout the Philippines and between the Philippines and other countries and territories, wire and/or wireless telecommunications systems including, but not limited to, mobile, cellular, paging, fiber optics, multi-channel multi-point distribution system (MMDS), local multi-point distribution system (LMDS), satellite transmit and receive systems, switches and their value-added services such as, but not limited to, transmission of voice, data, facsimile, control signs, audio and video, information services bureau and all other telecommunications systems technologies as are at present available or will be made available through technological advances or innovations in the future; and/or construct, acquire, lease and operate or manage transmitting and receiving stations, lines, cables or systems as are convenient or essential to efficiently carry out the purpose of this franchise."}},{"id":"PH-H8796-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee’s services and/or availability thereof."}},{"id":"PH-H8796-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission (NTC). – The grantee shall secure from the NTC, hereinafter referred to as the Commission, a certificate of public convenience and necessity or the appropriate permits and licenses for the construction, installation and operation of its telecommunications systems/facilities. In issuing the certificate, the Commission shall have the power to impose such conditions relative to the construction, operation, maintenance or service level of the telecommunications system. The Commission shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without having been authorized by the Commission. Such certificate shall state the areas covered and date the grantee shall commence the service. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses."}},{"id":"PH-H8796-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. – For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks or bridges of said province, cities and/or municipalities: Provided, however, That a public place, highway, street, lane, alley, avenue; sidewalk or bridge disturbed, altered or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said grantee, its successors or assigns, in accordance with the standards set by the DPWH or the LGU concerned. Should the grantee, its successors or assigns, after the ten (10)-day nonce from the said authority, fail, refuse or neglect to repair or replace any part, of public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed or disturbed by the said grantee, its successors or assigns, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition at double expense to be charged against the grantee, its successors or assigns."}},{"id":"PH-H8796-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. – The grantee shall conform to the ethics of honest enterprise and not use its stations/facilities for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service in any city and/or municipality in the Philippines where it has an approved certificate of public convenience and necessity for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the Commission, the grantee shall not be obliged to furnish such service unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunications apparatus necessary for such services and in such case, the Commission may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems and equipment to keep abreast, with the advances in science and technology."}},{"id":"PH-H8796-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. – The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether fiat rates or measured rates or variation thereof, shall be subject to the approval of the Commission or its legal successor. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H8796-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations, transmitters, faculties or equipment of the grantee, to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations, transmitters, facilities or equipment during the period when they shall be so operated.\nThe radio spectrum is a finite resource that is pan of the national patrimony and the use thereof is a privilege conferred upon the grantee by the Stats and may be withdrawn anytime after due process."}},{"id":"PH-H8796-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years from the date of effectivity of this Act, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously within two (2) years."}},{"id":"PH-H8796-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H8796-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Bond. – The grantee shall file a bond with the NTC in the amount that it shall determine to guarantee the compliance with and fulfillment of the conditions under which this franchise is granted. If, after three (3) years from the date of the approval of its permit by the Commission, the grantee shall have fulfilled the conditions, the bond shall be cancelled by the Commission. Otherwise, the bond shall be forfeited in favor of the government and the franchise ipso facto revoked."}},{"id":"PH-H8796-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Right of Interconnection. – The grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review and modification of the Commission."}},{"id":"PH-H8796-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Gross Receipts. – The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit (COA) and the National Treasury a copy of such account not later than the thirty-first (31st) day of January of each year for the preceding twelve (12) months."}},{"id":"PH-H8796-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Books and Accounts. – The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the COA and its duly-authorized representatives. It shall be the duty of the grantee to submit to the COA two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H8796-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Warranty in Favor of the National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H8796-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sale, Lease, Transfer, Usufruct or Assignment of Franchise. – The grantee shall not sell, lease, transfer, grant the usufruct of, or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, or merge with any other corporation or entity, or shall transfer the controlling interest of the grantee, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any sale, lease, transfer, grant of usufruct or assignment of franchise or the rights or privileges acquired within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H8796-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Dispersal of Ownership. – In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty per centum (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H8796-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Reportorial Requirement. – The grantee shall submit, an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of the succeeding year."}},{"id":"PH-H8796-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Penalty Clause. – Any grantee who tails to submit the annual report to Congress shall be fined Five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from said delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. The collected funds shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H8796-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under other existing franchise, or which may hereafter be granted, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of telecommunications franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H8796-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H8796-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H8796-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Publication. – This Act shall be published, through the initiative of the grantee, fifteen (15) days after this Act is signed by the President of the Philippines or has lapsed into law."}},{"id":"PH-H8796-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to Philippine Global Communications, Inc. (Formerly RCA Communications, Inc.) for Another Twenty-Five (25) Years, Amending for the Purpose Republic Act No. 4617","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8797"] = {"id":"PH-H8797","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10344_2012.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"处罚未经授权取走、窃取、保管或篡改政府减灾与备灾设备、配件及类似设施行为的法案","en":"An Act Penalizing the Unauthorized Taking, Stealing, Keeping or Tampering of Government Risk Reduction and Preparedness Equipment, Accessories and Similar Facilities","orig":"An Act Penalizing the Unauthorized Taking, Stealing, Keeping or Tampering of Government Risk Reduction and Preparedness Equipment, Accessories and Similar Facilities"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 10344","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10344_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8797-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \"Risk Reduction and Preparedness Equipment Protection Act\"."}},{"id":"PH-H8797-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is the policy of the State to protect the right of the people to a balanced and healthful ecology in accord with the rhythm and harmony of nature. The State shall continue the policy to create, develop, maintain and improve conditions under which man and nature can thrive in productive and enjoyable harmony with each other. Towards this end, all government agencies are mandated to institute measures to ensure the safety of its citizens and their properties through the installation of data and information gathering devices and the network of national and local authorities to disseminate risk reduction warning and advice."}},{"id":"PH-H8797-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"List of Government Risk Reduction and Preparedness Equipment and Other Vital Facility Items. – The Department of Science and Technology (DOST) shall, in coordination with the Philippine Atmospheric, Geophysical and Astronomical Services Administration (PAGASA), the Philippine Institute of Volcanology and Seismology (PHIVOLCS) and the National Disaster Risk Reduction and Management Council (NDRRMC), provide a list of all government risk reduction and preparedness equipment, accessories and other vital facility items such as, but not limited to, radars, weather forecasting equipment, flood monitoring instruments, seismographs, tsunami warning systems and automated weather systems.\nThe complete list of government risk reduction and preparedness equipment, accessories and other vital facility items shall be provided jointly by the DOST and the NDRRMC to government agencies engaged in disaster preparedness. The list shall be regularly updated.\nFor purposes of this Act, \"government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof refer to pieces of equipment or devices, or parts thereof that gather, store, archive or monitor meteorological and seismological data and information which are analyzed and used to warn the public about weather conditions, earthquake, volcanic or tsunami activities and similar natural calamities."}},{"id":"PH-H8797-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Prohibited Acts. – The government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof shall, at all times, be protected and it shall be unlawful for any person to commit any of the following acts:\n(a) Steal, or take, or possess any of the equipment, or any part thereof;\n(b) Sell or buy stolen equipment or any part thereof;\n(c) Tamper, dismantle, or disassemble equipment or any part thereof;\n(d) Attempt to commit any of the abovementioned prohibited acts; and\n(e) Benefit from the proceeds or fruits of any of the abovementioned prohibited acts knowing that the proceeds or fruits are derived from the commission of said prohibited acts."}},{"id":"PH-H8797-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Prima Facie Evidence. – The possession or custody of any government risk reduction and preparedness equipment, accessories and other vital facility items, or any part thereof, as defined in Section 3 hereof, by any person, natural or juridical, without proper authority shall be prima facie evidence that such instrument, part or accessory, is the fruit of the offense defined in Section 4 hereof and therefore such equipment, instrument, accessory, or other vital facility items, or parts thereof may be immediately confiscated from the person in possession, control or custody thereof."}},{"id":"PH-H8797-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Penalties. – The following penalties are hereby imposed:\n(a) The penalty of imprisonment of not less than twelve (12) years but not more than fifteen (15) years or a fine of not less than One million pesos (P1,000,000.00) but not more than Three million pesos (P3,000,000.00), or both imprisonment and fine at the discretion of the court shall be imposed upon any person found guilty of stealing or unauthorized taking or possession without authority or selling or buying with intent to gain of any stolen government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof;\n(b) The penalty of imprisonment of not less than six (6) years but not more than ten (10) years or a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000.000.00), or both imprisonment and fine at the discretion of the court shall be imposed upon any person found guilty of unauthorized tampering, dismantling or disassembling of government risk reduction and preparedness equipment. accessories and other vital facility items, or parts thereof;\n(c) The penalty of imprisonment of not less than six (6) years but not more than eight (8) years or a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00), or both imprisonment and fine at the discretion of the court shall be imposed upon any person who attempts to commit any of the prohibited acts provided in Section 4 of this Act; and\n(d) The penalty of imprisonment of not less than two (2) years but not more than seven (7) years or a fine of not less than Two hundred thousand pesos (PP00,000.00) but not more than Five hundred thousand pesos (P500,000.00), or both imprisonment and fine at the discretion of the court shall be imposed upon any person found guilty of unlawfully benefiting from the proceeds or fruits of any of the prohibited acts enumerated in Section 4 of this Act knowing that such proceeds or fruits are derived from the commission of said prohibited acts.\nPayment of the full cost of repair or replacement of the government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof, which is the object of the crime shall likewise be imposed upon any person who shall commit any of the prohibited acts described in Section 4 of this Act."}},{"id":"PH-H8797-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Penalty for Government Officers or Employees. – Any government officer or employee who shall assist in the commission of any of the prohibited acts enumerated in Section 4 of this Act shall suffer the same penalty imposed upon the person who committed the prohibited act. In addition, after due notice and hearing, they shall be administratively dismissed from the service and all their benefits from the government, shall be forfeited. They shall likewise be perpetually disqualified from holding any public office.\nThe prosecution or conviction under this Act shall not bar the filing of any case for the violation of Republic Act No. 3019, as amended, otherwise known as the \"Anti-Graft and Corrupt Practices Act\"; Republic Act No. 6713. otherwise known as the \"Code of Conduct and Ethical Standards for Public Officials and Employees\"; Republic Act No. 7080, entitled \"An Act Denning and Penalizing the Crime of Plunder\"; and other laws."}},{"id":"PH-H8797-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Non-Applicability on the Provisions of Theft of the Revised Penal Code. – The prosecution under this Act shall bar any prosecution arising from the same Act under Articles 308, 309, 310 and 311 of the Revised Penal Code."}},{"id":"PH-H8797-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Education and Information. – At least once a year, the DOST and the NDRRMC shall, in coordination with the local government units (LGUs) and nongovernment organizations (NGOs) or people’s organizations (POs), disseminate information and conduct continuing education on the provisions of this Act through the media and other lawful means available. The dissemination of information and continuing education on the provisions of this Act shall commence within sixty (60) days from the approval of its implementing rules and regulations.\nSuch information dissemination and continuing education shall:\n(a) Aim to develop public awareness of: (1) the ill effects of unlawful taking or stealing, tampering and buying and selling of stolen government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof; and (2) the community-based solutions to prevent the occurrence of such offense; and\n(b) Encourage the public, NGOs and POs to safeguard and protect these government risk reduction and preparedness equipment, accessories and other vital facility items, or parts thereof, within their areas of jurisdiction."}},{"id":"PH-H8797-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Implementing Rules and Regulations. – Within ninety (90) days from the effectivity of this Act, the Secretary of Science and Technology shall in coordination with the NDRRMC, issue the implementing rules and regulations for the effective implementation of this Act."}},{"id":"PH-H8797-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability Clause. – If any part or provision of this Act shall be declared invalid or unconstitutional, the remaining provisions or parts not affected shall remain in full force and effect."}},{"id":"PH-H8797-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause. – All other laws, presidential decrees, executive orders, rules and regulations or parts thereof which are inconsistent with any provision of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8797-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Penalizing the Unauthorized Taking, Stealing, Keeping or Tampering of Government Risk Reduction and Preparedness Equipment, Accessories and Similar Facilities","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8798"] = {"id":"PH-H8798","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10345_2012.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将Quirino纪念医疗中心床位由350张增至500张，为此修订第8313号共和国法并为此拨款及为其他目的","en":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center From Three Hundred Fifty (350) to Five Hundred (500) Beds, Amending for the Purpose Republic Act No. 8313, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center From Three Hundred Fifty (350) to Five Hundred (500) Beds, Amending for the Purpose Republic Act No. 8313, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật tăng sức chứa giường bệnh của Trung tâm Y tế Tưởng niệm Quirino từ 350 lên 500 giường, và phân bổ kinh phí","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของศูนย์การแพทย์อนุสรณ์ Quirino จาก 350 เป็น 500 เตียง และจัดสรรงบประมาณ","id":"Undang-Undang meningkatkan kapasitas tempat tidur Pusat Medis Memorial Quirino dari 350 menjadi 500 tempat tidur, dan mengalokasikan dana","ms":"Akta meningkatkan kapasiti katil Pusat Perubatan Memorial Quirino daripada 350 kepada 500 katil, serta memperuntukkan dana"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10345","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10345_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8798-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 2 of Republic Act No. 8313 is hereby amended to read as follows:\n\"SEC. 2. The bed capacity of the Quirino Memorial Medical Center is hereby increased from three hundred fifty (350) to five hundred (500).\""}},{"id":"PH-H8798-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 5 of the same Act is hereby amended to read as follows:\n\"SEC. 5. The Secretary of Health shall immediately include in the Department’s programs the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act.\""}},{"id":"PH-H8798-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 6 of the same Act is hereby amended to read as follows:\n\"SEC. 6. This Act shall take effect fifteen (15) days after its publication in any newspaper of general circulation.\""}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center From Three Hundred Fifty (350) to Five Hundred (500) Beds, Amending for the Purpose Republic Act No. 8313, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8799"] = {"id":"PH-H8799","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10346_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将设于北拉瑙Tubod的陆运署（LTO）延伸办公室改设为陆运署正式区办公室，并为此拨款及为其他目的法案","en":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in Tubod, Lanao Del Norte Into a Regular LTO District Office, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in Tubod, Lanao Del Norte Into a Regular LTO District Office, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật chuyển đổi Văn phòng mở rộng Land Transportation Office thành Regular LTO District Office, và phân bổ kinh phí cho mục đích này, và cho các mục đích khác","th":"พระราชบัญญัติเปลี่ยนสถานะสำนักงานขยาย Land Transportation Office เป็น Regular LTO District Office และจัดสรรเงินทุนสำหรับการนี้ และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Kantor Perluasan Land Transportation Office menjadi Regular LTO District Office, dan mengalokasikan dana untuk itu, dan untuk tujuan lain","ms":"Akta menukar status Pejabat Lanjutan Land Transportation Office kepada Regular LTO District Office, dan memperuntukkan dana untuk itu, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10346","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10346_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8799-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) Extension Office located in Tubod, Lanao del Norte is hereby converted into a regular LTO District Office."}},{"id":"PH-H8799-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation and Communications shall issue such rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H8799-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the LTO District Office in Tubod, Lanao del Norte, the initial funding of which shall be charged against the current year’s appropriations of the Tubod LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H8799-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in Tubod, Lanao Del Norte Into a Regular LTO District Office, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8800"] = {"id":"PH-H8800","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10347_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Luna市","en":"An Act Converting the Extension Office of the Land Transportation Office (LTO) in Quirino, Municipality of Luna, Apayao Into a Regular LTO District Office and Appropriating Funds Therefor","orig":"An Act Converting the Extension Office of the Land Transportation Office (LTO) in Quirino, Municipality of Luna, Apayao Into a Regular LTO District Office and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Văn phòng mở rộng Land Transportation Office thành Văn phòng Khu vực Regular LTO tại Đô thị Luna, Tỉnh Apayao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติเปลี่ยนสถานะสำนักงานขยาย Land Transportation Office เป็น สำนักงานเขต Regular LTO ในเทศบาล Luna จังหวัด Apayao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang mengubah status Kantor Perluasan Land Transportation Office menjadi Kantor Distrik Regular LTO di Kotamadya Luna, Provinsi Apayao, dan mengalokasikan dana untuk itu","ms":"Akta menukar status Pejabat Lanjutan Land Transportation Office kepada Pejabat Daerah Regular LTO di Perbandaran Luna, Wilayah Apayao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10347","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-04","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10347_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8800-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Apayao Extension Office of the Land Transportation Office (LTO) located in Quirino, Municipality of Luna, Apayao is hereby converted into a regular LTO District Office."}},{"id":"PH-H8800-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the LTO District Office in Quirino, Municipality of Luna, Apayao, the initial funding of which shall be charged against the current year’s appropriations of the Apayao LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H8800-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Transportation and Communications shall promulgate the necessary rules and regulations for the implementation of this Act."}},{"id":"PH-H8800-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) national newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8801"] = {"id":"PH-H8801","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10348_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"1980年司法重组法","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Two (2) Branches of the Regional Trial Court in the Province of Cebu to Be Stationed At the Cities of Naga and Carcar, Amending for the Purpose Section 14, Paragraph (H) of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\". as Amended, and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10348","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-06","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10348_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8801-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Two (2) Regional Trial Court branches with one (1) seat each at the cities of Naga and Carcar, all in the Province of Cebu, are hereby created in the Seventh Judicial Region.\nThe Supreme Court shall assign the branch number of the newly-created Regional Trial Court branches in the Seventh Judicial Region."}},{"id":"PH-H8801-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of the two (2) Regional Trial Court: branches to be stationed at the cities of Naga and Carcar, all in the Province of Cebu, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8801-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(h) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8801-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Judiciary Reorganization Act of 1980","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8802"] = {"id":"PH-H8802","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10349_2012.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"对第 7898 号共和国法的修改","en":"An Act Amending Republic Act No. 7898, Establishing the Revised AFP Modernization Program and for Other Purposes","orig":"An Act Amending Republic Act No. 7898, Establishing the Revised AFP Modernization Program and for Other Purposes","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 7898, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 7898 และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Undang-Undang Republik No. 7898, dan untuk tujuan lain","ms":"Akta meminda Akta Republik No. 7898, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10349","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-11","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10349_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 14 条，缺 7、8、9、10）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8802-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 4(b), (d) and (e) of Republic Act No. 7898, otherwise known as the \"AFP Modernization Act\", is hereby amended to read as follows:\n\"SEC. 4. Components of the Revised AFP Modernization Program. – The Revised AFP Modernization Program shall consist of the following components:\n\"(a) x x x \"(b) Capability, materiel, and technology development – The AFP Modernization Program entails the development and employment of certain capabilities that can address the assessed threats: Provided, That the acquisition of air force, navy and army equipment and materiel of such types and quantities shall be made in accordance with the need to develop AFP capabilities pursuant, to its modernization objectives: Provided, further, That the acquisition of new equipment and weapons systems shall be synchronized with the phase-out of uneconomical and obsolete major equipment and weapons systems in the AFP inventory: Provided, even further, That no major equipment and weapons system shall be purchased if the same are not being used by the armed forces in the country of origin or used by the armed forces of at least two countries: Provided, furthermore, That only offers from suppliers who are themselves the manufacturers shall be entertained: Provided, finally, That no supply contract shall be entered into unless such contract provides for, in clear and unambiguous terms, an after-sales services and the availability of spare parts.\n\"(c) x x x \"(d) Human resource development – The human resource development component of the Revised AFP Modernization Program shall have the following objectives:\n\"(1) x x x \"(2) To develop and transform the AFP into a multi-mission oriented force capable of effectively addressing internal and external security threats;\n\"(3) x x x \"(4) x x x \"(5) x x x \"(6) x x x \"(e) Doctrines development – The Department of National Defense and the AFP shall be responsible for the generation, evaluation, consolidation and formalization of doctrines; the conduct of periodic review and validation of doctrines through field application, testing and exercises; and the dissemination of approved doctrines at all levels of command.\n\"The Secretary of National Defense shall formulate guidelines to implement this section in accordance with the objectives of the modernization program enumerated in the preceding section.\""}},{"id":"PH-H8802-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 6 of the same Act is hereby amended to read as follows:\n\"SEC. 6. Period of Implementation. – The Revised AFP Modernization Program under this Act, shall be implemented over a period of fifteen (15) years effective upon the date of the approval of this Act: Provided, however, That payments for amortization of outstanding multi-year contract, obligations incurred under the Revised AFP Modernization Act may extend beyond tins period.\""}},{"id":"PH-H8802-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 7 of the same Act is hereby amended to read as follows:\n\"SEC. 7. Submission of the Revised AFP Modernization Program. – (a) Within sixty (60) days from the effectivity of this Act, the President, upon the recommendation of the Secretaries of National Defense and Budget and Management, shall submit the Revised AFP Modernization Program as provided for in this Act to Congress. The Program shall indicate or show inter alia:\n\"(1) The size and shape of the AFP in terms of personnel, equipment, and facilities during the various phases of the modernization program;\n\"(2) The modernization projects under it, including the major weapon and non-weapon equipment and technology acquisitions sought by the respective services and units of the AFP, any major infrastructure construction or improvement to be made and the particular objective(s) and component(s) under Sections 3 and 4, respectively, of this Act to which such intended acquisition, construction or improvements belongs; and \"(3) The priorities, schedules as well as estimated average cost of each modernization project or upgrading to be undertaken: Provided, That in the implementation of the AFP Modernization Program, the acquisition of equipment or upgrading to be undertaken shall be devoted towards the development of the AFP with shifting capability to meet internal and external threats.\n\"(b) The Revised AFP Modernization Program, as submitted to Congress shall be the basis for subsequent executive and legislative actions to implement the Revised AFP Modernization Program from year to year until its complete and full realization.\""}},{"id":"PH-H8802-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 8 of the same Act is hereby amended to read as follows:\n\"SEC. 8. Appropriations for the Revised AFP Modernization Program. – The annual appropriations for the Revised AFP Modernization Program shall include the amounts necessary to support the funding requirements for all modernization projects submitted to Congress under the preceding section.\n\"The funds to be appropriated by Congress under this Act shall be treated as a distinct and separate budget item from the regular appropriation for the Department of National Defense (DND) and the AFP and shall be administered by the Secretary of National Defense.\n\"The Revised AFP Modernization Program shall be based on an amount of at least Seventy-five billion pesos (P75,000,000,000.00) for the first five (5) years.\""}},{"id":"PH-H8802-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 9(b) and (c) of the same Act are hereby amended to read as follows:\n\"SEC. 9. Multi-year Contracts and Other Contractual Arrangements. – (a) x x x \"(b) For multi-year contracts, Congress shall, upon issuance of a multi-year obligational authority by the Department of Budget and Management (DBM), make the corresponding appropriation for the ensuing fiscal years: Provided, That the DND and the DBM shall issue the implementing guidelines to ensure consistency with the Revised AFP Modernization Program and existing guidelines in the contracting of multi-year projects.\n\"(c) The Secretary of National Defense shall submit to Congress, through the Chairpersons of the Senate Committees on National Defense and Security and Finance and the Chairpersons of the House Committees on National Defense and Security and Appropriations, copies of these multi-year contracts and other agreements/arrangements to enable Congress to appropriate hinds.\""}},{"id":"PH-H8802-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 11 of the same Act is hereby amended to read as follows:\n\"SEC. 11. The Revised AFP Modernization Act Trust Fund. – There is hereby created a trust fund, to be known as the Revised AFP Modernization Act Trust Fund. Said trust fund, which shall be used exclusively for the AFP modernization program, including all necessary expenses to implement the procurement of equipment such as expenses for pre-selection and post-qualification stages, but not to include salaries and allowances, shall be funded out of the following:\n\"(a) Appropriations for the Revised AFP Modernization Program;\n\"(b) The proceeds from the sale of military reservations, as may be authorized by Congress, pursuant to the provisions of existing laws and regulations governing sales of government properties, including such immovable and other facilities as may be found therein, not otherwise covered by the Bases Conversion and Development Authority, as provided for in Republic Act No. 7227, as amended;\n\"(c) The proceeds from the lease or joint development of military reservations, as may be authorized by the President, pursuant to the provisions of existing laws and regulations governing lease or joint development of government properties, including such immovables and other facilities as may be found therein, not specifically enumerated under Republic Act No. 7227, as amended;\n\"(d) Shares of the AFP from the proceeds of the sale of military camps provided for under Republic Act No. 7227, as amended, and at least fifty percent (50%) of the proceeds, net of direct expenses authorized to be deducted from such proceeds from the lease and/or joint venture agreements and such other dispositions pertaining to the same camps in accordance with applicable and/or existing orders, rules, regulations and issuances.\n\"The DND or the AFP may assign to the Bases Conversion and Development Authority or designate it as disposition entity for the sale, lease or joint development of military reservations or portions thereof or facilities and immovables located therein not otherwise covered under Republic Act No. 7227, as amended, subject to the parameters set by the DND or the AFP and applicable laws, rules, regulations and other related issuances;\n\"(e) The proceeds derived from public-private partnerships entered into by the DND or the AFP, as may be authorized by the President, pursuant to the provisions of existing laws and regulations;\n\"(f) Proceeds from the sale of the products of the Government Arsenal and/or, in case of joint venture, all incomes earned from the equity share of the Government Arsenal from the joint venture;\n\"(g) The proceeds from the disposal of excess and/or uneconomically repairable equipment and other movable assets of the AFP and the Government Arsenal;\n\"(h) Funds from budgetary surplus, if any, as may be authorized by Congress subject to the provisions of Section 8 of this Act;\n\"(i) Donations coming from local and foreign sources, specifically earmarked to be used for the Revised AFP Modernization Program; and \"(j) All interest income of the trust fund.\n\"Funds from the foregoing sources, regardless of income source, shall be directly deposited to a special account in the general fund created specifically for the Revised AFP Modernization importation of the same by the APP shall likewise be exempt from the value-added tax and customs duties.\n\"SEC. 18. Congressional Oversight Committee. – There is hereby created a Congressional Oversight Committee to monitor and oversee the implementation of the provisions of this Act. The Committee shall be composed of six (6) members from the Senate and six (6) members from the House of Representatives with the Chairpersons of the Committees on National Defense and Security of both Houses as Joint Chairpersons. The five (5) other members from each Chamber shall be designated by the Senate President and the Speaker of the House of Representatives, respectively. The Minority shall have at least two (2) representatives from both Chambers.\n\"SEC. 19. Sunset Review. – As the need arises or within five (5) years after its effectivity, the Congressional Oversight Committee shall conduct a sunset review of this Act. The term ‘sunset review’ shall mean a systematic evaluation of the accomplishments and impact of this Act, as well as the performance and organizational structure of its implementing agencies, for purposes of determining remedial legislation.\""}},{"id":"PH-H8802-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"All sections of the same Act are hereby amended and renumbered accordingly."}},{"id":"PH-H8802-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause. – All laws, executive orders, rules and regulations inconsistent with or contrary to this Act are hereby deemed accordingly repealed or amended."}},{"id":"PH-H8802-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. – If, for any reason, any section or provision of this Act is declared unconstitutional or invalid, the other sections or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H8802-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of national circulation."}}],"pack":"ph-p125"};
  FT["PH-H8803"] = {"id":"PH-H8803","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10350_2012.html","fetchedAt":"2026-10-06","articleCount":41,"structureMode":"ARTICLE","title":{"zh":"规制现代化执业室内设计","en":"An Act Regulating the Practice of Interior Design in the Philippines","orig":"An Act to Regulate and Modernize the Practice of the Interior Design in the Philippines, Repealing for the Purpose Republic Act Numbered 8534, Otherwise Known as \"An Act Regulating the Practice of Interior Design in the Philippines\", Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật Quy định và Hiện đại hóa Hành nghề Thiết kế Nội thất","th":"พระราชบัญญัติกำกับและปรับปรุงการประกอบวิชาชีพการออกแบบภายในให้ทันสมัย","id":"Undang-Undang Pengaturan dan Modernisasi Praktik Desain Interior","ms":"Akta Pengawalseliaan dan Pemodenan Amalan Reka Bentuk Dalaman"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10350","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-17","completenessNote":"全文，共 41 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10350_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 42 条，缺 12）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8803-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \"Philippine Interior Design Act of 2012″."}},{"id":"PH-H8803-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy. – The State recognizes the important role of the interior design profession in nation building. Towards this end, the State shall promote the sustained development of professional interior designers, whose technical competencies have been determined by honest and credible licensure examinations and whose standards of professional service and practice are internationally recognized and considered globally competitive, brought about by regulatory measures and human resource programs and activities that foster their professional growth and advancement."}},{"id":"PH-H8803-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. –This Act provides for and shall govern:\n(a) The examination, registration and licensure of professional interior designers;\n(b) The supervision, control and regulation of the practice of interior design;\n(c) The development of the professional competence of interior designers through continuing professional education; and\n(d) The integration of the interior design profession."}},{"id":"PH-H8803-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. – For purposes of this Act, the following terms are hereby defined:\n(a) Interior design refers to the science and art of planning, specifying, selecting and organizing the surface finishes and materials including furniture, furnishings and fixtures and other interior design elements for the purpose of the interior space allocations to suit, enhance and meet the intended function, movement and character for which the interior of the building is designed.\n(b) Professional interior designer refers to a natural person who holds a valid certificate of registration and a valid professional identification card issued by the Board and the Commission pursuant to this Act.\n(c) Commission refers to the Professional Regulation Commission."}},{"id":"PH-H8803-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Scope of the Professional Practice of Interior Design. –The practice of interior design is the act of planning, designing, specifying, supervising and providing general administration and responsible direction to the functional, orderly and aesthetic arrangement and enhancement of interior spaces. It shall include, but not be limited to, the following activities:\n(a) Consultation, advice, direction, evaluation, budgetary estimates and appraisals;\n(b) Schematic interior design development, design development, execution of professional contract documents and programming of construction phases;\n(c) Preparation of interior design plans, design drawings, interior construction details, and technical specifications;\n(d) Interior construction administration, supervision, coordination of alteration, preservation or restoration of interior spaces; and\n(e) All other works, projects and activities that require the professional competence of the interior designer, including teaching of interior design subjects.\nThe Board, subject to approval by the Commission, may revise, exclude from, or add to, the above enumerated acts or activities as the need arises to conform to the latest trends and developments in the practice of interior design.\nTHE PROFESSIONAL REGULATORY BOARD\nOF INTERIOR DESIGN"}},{"id":"PH-H8803-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Creation and Composition of the Board of Interior Design. – There is hereby created a Professional Regulatory Board of Interior Design, hereinafter referred to as the Board, under the administrative control and supervision of the Professional Regulation Commission (PRC), hereinafter referred to as the Commission, to be composed of a Chairman and two (2) members to be appointed by the President of the Philippines from a list of two (2) recommendees for each position submitted by the Commission, who in turn will be drawn from a list of three (3) to five (5) nominees for each position recommended by the duly Accredited and Integrated Professional Organization (AIPO) of Interior Designers. The new Board shall be created within six (6) months from the effectivity of this Act."}},{"id":"PH-H8803-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Qualifications of the Chairman and Members. – The Chairman and members of the Board shall, at the time of their appointment, possess the following qualifications:\n(a) Must be a citizen and resident of the Philippines;\n(b) Must be a degree holder of Bachelor of Science in Interior Design (BSID), Bachelor of Interior Design (BID) or Bachelor of Fine Arts (BFA), major in Interior Design, or an equivalent degree conferred by a school, academy, college or university in the Philippines or abroad that is recognized and/or accredited by the Philippine government;\n(c) Must be a registered interior designer with a valid certificate of registration and professional identification card and an active practitioner of interior design for not less than ten (10) years prior to appointment;\n(d) Must not be a member of the faculty of any school, where a regular course in Interior Design is being taught, or have pecuniary interest in, or administrative supervision over any such institution of learning;\n(e) Must not be connected with a review center or with any group giving review classes or lectures in preparation for the licensure examination;\n(f) Must be a member in good standing of the duly accredited professional organization of interior designers but not an incumbent trustee or officer thereof; and\n(g) Has never been convicted of a crime involving moral turpitude, or a civil and/or criminal offense."}},{"id":"PH-H8803-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Term of Office. – The members of the Board shall hold office for a term of three (3) years from the date of appointment or until their successors shall have been appointed and qualified. They may be reappointed for another term of three (3) years immediately upon the expiration of their term: Provided, That no member shall hold office for more than six (6) years in his position as a Chairman or as a member of the Board.\nOf the members to be appointed for the new Board under this Act: one (1) member shall hold office as Chairman for three (3) years; one (1) member for two (2) years; and one (1) member for one (1) year. Each member of the Board shall take the proper oath prior to assumption of duty."}},{"id":"PH-H8803-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Compensation of the Board Members. –The Chairman and members of the Board shall receive compensation and allowances comparable to the compensation and allowances received by existing regulatory boards under the Commission as provided for in the General Appropriations Act."}},{"id":"PH-H8803-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Functions, Duties and Responsibilities of the Board. –The Board shall exercise the following specific powers, functions, duties and responsibilities:\n(a) Adopt, promulgate and administer the rides and regulations necessary for carrying out the provisions of this Act;\n(b) Supervise and regulate the registration, licensure and practice of the professional interior designers in the Philippines;\n(c) Administer oaths in connection with the administration of this Act;\n(d) Issue, suspend, revoke or reinstate the certificate of registration or professional license for the practice of the interior design profession;\n(e) Adopt an official seal of the Board;\n(f) Monitor the conditions affecting the practice of interior design and adopt such measures as may be deemed proper for the enhancement of the profession and/or the maintenance of high professional, ethical and technical standards;\n(g) Ensure, in coordination with the Commission on Higher Education (CHED), that all other educational institutions offering interior design comply with the policies, standards and requirements of the course prescribed by the CHED in the areas of curriculum, faculty, library and facilities;\n(h) Prescribe and adopt a Code of Ethics and/or Code of Professional Standards for the practice of the interior design profession;\n(i) Hear and try administrative cases involving violations of this Act, its implementing rules and regulations (IRR), the Code of Professional Standards for the practice of the interior design profession and, for this purpose, to issue subpoena and subpoena duces tecum to secure the appearance of witnesses and the production of documents in connection therewith;\n(j) Prescribe guidelines for the Continuing Professional Education (CPE) program for interior designers in coordination with the accredited professional organization of interior designers;\n(k) Prepare, adopt and issue the Table of Specifications (TOS) and syllabi of the subjects for examination in the professional licensure examination for interior designers. Determine and prepare the questions for the examination, which shall strictly be within the scope of the syllabi of the subjects of examination; and\n(l) Discharge such other duties and functions as may be deemed necessary for the enhancement of the interior design profession and the upgrading, development and growth of interior design education in the Philippines."}},{"id":"PH-H8803-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Grounds for Removal or Suspension of Board Chairman/Member. – The President of the Philippines, upon the recommendation of the Commission, after giving the Chairman or the member of the Board an opportunity to defend himself/herself in an administrative investigation conducted by the Commission, may remove or suspend him/her on any of the following grounds:\n(a) Gross neglect, incompetence or dishonesty in the discharge of his/her duty;\n(b) Commission of the prohibited acts and/or violation of the provisions or commissions of the offenses and/or grounds for disciplinary action provided in this Act and in the Revised Penal Code, the Anti-Graft and Corrupt Practices Act, and other related laws;\n(c) Manipulation or rigging of the licensure examination for interior designers, tampering with the results, disclosure of secret and confidential information relating to the examination prior to the conduct thereof or manipulation/ padding/shaving of grades and similar acts; and\n(d) Conviction of an offense involving moral turpitude.\nThe Commission, in the conduct of the investigation, shall be guided by Section 7(s) of Republic Act No. 8981, otherwise known as \"The PRC Modernization Act of 2000″, the rules on administrative investigation and the applicable provisions of the Revised Rules of Court.\nSection12. Administrative Supervision of the Board, Custodian of its Records, Secretariat and Support Services. –The Board shall be under the administrative supervision of the Commission. All records of the Board, including applications for examination, administrative and other investigative cases conducted by the Board shall be under the custody of the Commission. The Commission shall designate the secretary of the Board and shall provide the secretariat and other support services to implement the provisions of this Act."}},{"id":"PH-H8803-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Annual Report. –The Board shall, at the close of each calendar year, submit an annual report to the President of the Philippines, through the Commission, giving a detailed account of its proceedings and accomplishments during the year and making recommendations for the adoption of measures that will upgrade and improve the conditions affecting the practice of interior design.\nEXAMINATION, REGISTRATION, CERTIFICATION\nAND LICENSURE"}},{"id":"PH-H8803-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Passing of Licensure Examination Requirement. – Except as otherwise specifically allowed under this Act, applicants for registration for the practice of interior design shall be required to pass a professional licensure examination as provided for in this Act in such places and on such dates as the Commission may designate in accordance with the provisions of Section 7(d) of Republic Act No. 8981."}},{"id":"PH-H8803-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications of Applicants. –An applicant for the licensure examination for interior designers shall satisfactorily prove that he/she possesses the following qualifications:\n(a) Citizen of the Philippines or a foreign citizen whose country/state has a policy reciprocity with the Philippines in the practice of interior design;\n(b) Of good moral character;\n(c) A holder of any of the following:\n(i) A degree in interior design obtained from a reputable institution of learning in the Philippines recognized by the government and affiliated with a school/college/university duly recognized or accredited by the CHED;\n(ii) A degree in interior design obtained from a reputable institution of learning in a foreign country/state: Provided, That the same is certified by the CHED as equivalent to a Bachelor of Science in Interior Design obtained in the Philippines; and\n(iii) Not convicted of an offense involving moral turpitude by a court of competent jurisdiction."}},{"id":"PH-H8803-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Subjects for Licensure Examination. – The examination for interior design shall basically cover the following subjects:\n(a) Interior Design;\n(b) Furniture Design and Construction;\n(c) Materials of Design and Decoration;\n(d) History of Arts and Interior Design;\n(e) Interior Construction and Utilities;\n(f) Color Theory; and\n(g) Professional Practice and Ethics.\nSubject to the approval of the Commission, the said subjects, their TOS and their syllabi may be amended by the Board in coordination with the CHED, so as to conform to technological changes brought about by continuing trends in the profession, in coordination with the accredited professional organization of interior design educators."}},{"id":"PH-H8803-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rating in the Licensure Examination. – To be qualified as having passed the Board examination for interior designers, a candidate must obtain a weighted general average of seventy percent (70%)."}},{"id":"PH-H8803-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Report of Ratings. –The Board shall submit to the Commission the ratings obtained by each candidate within twenty (20) days after the examination unless extended by the Commission for just cause. Upon the release of the results of the examination, the Board shall send by mail the rating received by each examinee at his given address using the mailing envelope submitted during the examination."}},{"id":"PH-H8803-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Oath. – All successful candidates in the examination shall be required to take an oath of profession before the Board or any government official authorized by the Commission to administer oaths prior to entering the practice of the interior design profession."}},{"id":"PH-H8803-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of Certificate of Registration and Professional Identification Card. –A certificate of registration shall be issued to applicants who pass the examination for interior designers subject to payment of registration fees.\nThe certificate of registration as professional interior designer shall bear the signatures of the Chairperson of the Commission and the Board members, stamped with the official seal, indicating that the person named therein is entitled to practice the profession with all the privileges appurtenant thereto. This certificate shall remain in full force and effect until withdrawn, suspended or revoked, in accordance with this Act.\nA certificate of registration bearing the registration number, date of issuance and expiry date, duly signed by the Chairman of the Board, shall likewise be issued to every registrant who has paid the required fees. This license will serve as evidence that the licensee can lawfully practice his/her profession.\nA professional identification card, whether new or for renewal, shall be released by the PRC upon compliance with the requirements for the application or renewal of identification card and upon presentation of the updated receipt of payment of annual membership dues of the accredited professional organization of interior designers and proof of completion of the CPE requirements.\nOnce registered, the interior designer may use \"IDr.\" as his/her official appendage title."}},{"id":"PH-H8803-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Refusal to Register. – The Board shall not register any successful applicant for registration who has been:\n(a) Convicted of an offense involving moral turpitude by a court of competent jurisdiction;\n(b) Who has been found guilty of immoral or dishonorable conduct by the Board;\n(c) Adjudged guilty for violation of the General Instructions to Examinees by the Board; and/or\n(d) Declared of unsound mind by a court of competent jurisdiction.\nIn refusing such registration, the Board shall give the applicant a written statement setting forth the reasons therefore and shall file a copy thereof in its records."}},{"id":"PH-H8803-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Revocation or Suspension of the Certificate of Registration and Cancellation of Temporary/Special Permit. – The Board shall have the power, upon notice and hearing, to revoke or suspend the certificate of registration of a registered and licensed interior designer or to cancel a temporary/special permit granted to foreign interior designer, for violation of any grounds or causes in Section 21 of this Act, except (c) thereof and any of the following grounds:\n(a) Violation of any provision of this Act, its IRR, the Code of Ethics, the Code of Good Governance, the Code of Professional Standards for the practice of interior design as well as the policy measures promulgated by the Board and/or the Commission;\n(b) Perpetration and/or use of fraud in obtaining his/her certificate of registration, professional identification card or temporary/special permit;\n(c) Gross incompetence, negligence or ignorance resulting to death, injury or damage;\n(d) Refusal to join or to remain a member in good standing of the AIPO for interior designers;\n(e) Neglect or failure to pay the annual registration fees for five (5) consecutive years;\n(f) Knowingly aiding or abetting the illegal practice of a nonregistered and licensed person by allowing him/her to use his/her certificate of registration and/or professional identification card and/or his/her temporary/special permit;\n(g) Illegally practicing the profession during his/her suspension from the practice thereof;\n(h) Addiction to a drug or alcohol abuse, impairing his/her ability to practice his/her profession or being declared of unsound mind by a court of competent jurisdiction; and\n(i) Noncompliance with the CPE requirements, unless he/she is exempted therefrom, for the renewal of his/her professional identification card.\nThe Board shall periodically evaluate the aforementioned grounds and amend, modify, revise, exclude and/or add new ones as the circumstances and the developments in the profession may require, subject to approval of the Commission.\nAny person, firm or association may file charge/s in accordance with the provision of this section against any registered interior designer or the Board may motu proprio investigate violation of any of the abovementioned causes. Affidavit embodying the complaint shall be filed together with the affidavits of witnesses and other documentary evidence with the Board though the Legal and Investigation Office. Any motu proprio action of the Board to conduct an investigation shall be embodied in a formal charge to be signed by at least majority of the members of the Board. The rules on administrative investigation issued by the Commission shall govern the hearing or investigation subject to applicable provisions of this Act, Republic Act No. 8981 and the Revised Rules of Court."}},{"id":"PH-H8803-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reissuance of Revoked Certificate of Registration, Replacement of Lost or Damaged Certificate of Registration, Professional Identification Card or Temporary/ Special Permit. –The Board may, upon petition on meritorious grounds, reinstate or reissue a revoked certificate of registration after two (2) years from the date of effectivity of the period for revocation. The date of effectivity of the period of revocation shall be reckoned from the date of receipt by the respondent of the final order or resolution revoking his/her registration or the date of the surrender by the respondent of his/her certificate of registration and professional identification card, if it is still valid.\nThe Board may not require the holder thereof to take another licensure examination. The petitioner shall prove to the Board that the ground or grounds for the revocation of his/her certificate of registration no longer exists. For the grant of his/her petition, the Board shall issue a Board Resolution subject to approval by the Commission.\nA duplicate copy of lost certificate of registration, professional identification card or temporary/special permit may be reissued in accordance with rules thereon and upon payment of the prescribed fee therefor."}},{"id":"PH-H8803-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Nonpayment of the Annual Registration Fees. –The Board shall suspend a registered interior designer from the practice of his/her profession for nonpayment of the annual registration fees for five (5) consecutive years from his/her last or previous year of payment. The resumption of his/her practice shall take place only upon payment of the delinquent fees plus surcharges and interest and in accordance with the rules of the Commission. The running of the five (5)-year period may be interrupted upon written notice of the discontinuance of his/her practice and surrender of his/her certificate of registration and professional identification Card to the Board and/or the Commission."}},{"id":"PH-H8803-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Vested Rights. – All practicing interior-designers who are registered at the time of the passage of this Act shall automatically be registered and issued certificates of registration, subject to existing rules and regulations.\nPRACTICE OF INTERIOR DESIGN"}},{"id":"PH-H8803-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Lawful Practitioners of Interior Design. – The following persons shall be authorized to practice the interior design profession:\n(a) Natural persons who are:\n(1) Duly registered and licensed as interior designers and holders of valid certificates of registration and valid professional identification cards issued by the Board and the Commission pursuant to this Act; and\n(2) Holders of valid temporary/special permits issued by the Board and the Commission to foreign licensed interior designers pursuant to this Act.(a) Natural persons who are:\n(b) Juridical persons:\n(1) Single proprietorship owned by a registered and licensed interior designer;\n(2) General professional partnership duly registered with the Securities and Exchange Commission (SEC) as professional partnership pursuant to the Civil Code and composed of partners who are all duly registered and licensed interior designers; and\n(3) Corporation whose chief executive officer (CEO) and other key officers are all registered and licensed interior designers may be duly registered with the SEC as engaged in the practice of interior design."}},{"id":"PH-H8803-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Issuance and Use of Seal. – A duly registered interior designer shall sign and affix the seal as approved and provided by the Board on all plans, specifications and contract documents prepared by him/her and/or under his/her direct supervision during the validity of his/her certificate of registration.\nOfficers and/or employees of the government, chartered cities, provinces, municipalities now or hereafter charged with the enforcement of the laws, ordinances or regulations relating to the construction or alteration of the interiors of buildings shall accept only those interior plans, specifications and contract documents which have been prepared by or under the supervision of a duly licensed interior designer and signed and sealed by him/her and submitted in full accord with the provisions of this Act.\nViolation of the foregoing shall be ground for administrative and/or criminal action."}},{"id":"PH-H8803-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Proprietary Rights. –An interior designer shall enjoy proprietary rights over all drawings and specifications and other contract documents prepared by him/her resulting from his/her professional labor and duly signed, stamped or sealed by him/her, as instruments of service, as well as over the original concepts and designs contained and/or included therein. No person may engage in any activity prejudicial to the proprietary rights of the interior designer, including the reproduction of the contract work or substantial portion thereof, making any alteration, distortion, mutilation, or other modification of, or any derogatory action in relation to, the contract work and the detailed works contained therein, without the written consent of the interior designer unless the said contract work is a commissioned piece of work duly paid for by the person or party who/which commissioned the same in which case the said person or party shall have the right to alter, revise and/or modify the drawing, specification, design, concept and/or contract works."}},{"id":"PH-H8803-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Foreign Reciprocity. – No foreign interior designer shall be issued a certificate of registration to practice the interior design profession or be entitled to any of the rights and privileges under this Act unless the country of which he/she is a subject or citizen has a policy which permits Filipino interior designers to practice within its territorial limits on the same basis as the subjects or citizens of such foreign state or country."}},{"id":"PH-H8803-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Practice Through Temporary/Special Permit. – (a) Foreigners intending to work in the Philippines to perform professional services as interior designers or consultants whether employed through official foreign-funded or foreign-assisted projects initiated by the government, or engaged by private Filipino or foreign contractors and/or firms shall first secure a temporary/special permit from the Commission through the Board specifically authorizing him/ her to practice on the special project or commission named therein: Provided, That:\n(1) He/She is legally and professionally qualified and registered to practice interior design in his/her own country; and\n(2) His/Her expertise is unique and useful to the Philippines, resulting in the transfer of information and technology, the establishment of international standards in design, and the sharing of other specialized skills.\n(b) The foreign interior designer shall be required to work in every case with a duly licensed Filipino counterpart who has been in continuous practice of interior design for at least ten (10) years and whose competence and integrity have been established by the Board on the basis of uniform standards contained in their IRR.\n(c) The foreign and Filipino interior designers working jointly on a special project shall divide the professional fees and other charges from said project equitably, according to their participation in or professional services rendered to the project. Similarly, all documentation expenses, taxes and other liabilities incurred on the shared project shall also be borne equitably by both foreign and Filipino interior designers.\n(d) Foreigners working jointly with Filipino interior designers shall sign contracts, designs and other credits together with his/her Filipino counterpart. Both foreign and Filipino interior designers shall at all times be acknowledged in all marketing and promotional materials and reportorial compliance for the project, whether prepared and/or submitted locally or abroad. All residual earnings shall also be equitably shared between foreign and local interior designers.\n(e) Foreign design firms or individuals practicing in the Philippines before the promulgation of this Act are required to comply with the requirements established by the Board in its IRR within the timetable it stipulates therein.\n(f) Any violation of these requirements or other illegal practices undertaken by either foreign design firms or their Filipino counterparts shall be punishable by law and/or the IRR issued by the Board."}},{"id":"PH-H8803-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Indication of Numbers: Certificate of Registration, Professional Tax Receipt and AIPO Membership. – The interior designer shall be required to indicate his/her certificate of registration number and date of issuance, the expiry of his/her current professional identification card, the professional tax receipt number and its date of issuance, and his/her AIPO membership number and date with official receipt number and date of membership payment (annual/lifetime) on all the documents he/she signs, uses or issues in connection with the practice of his/her interior design profession."}},{"id":"PH-H8803-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Roster of Interior Designers. – The Board shall prepare and maintain a roster of the names, residence and/or office address of all registered interior designers which shall be updated annually in cooperation with the AIPO, indicating therein the status of the certificate of registration, professional identification card and AIPO membership, whether valid, delinquent, suspended or surrendered or terminated due to death or other reasons. The said roster shall be conspicuously posted within the premises of the Commission and the information therefrom made available to the public upon inquiry or request."}},{"id":"PH-H8803-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Integration of the Interior Designers. – The interior designers shall be integrated into one (1) national organization of interior designers that is duly registered with the SEC. The Board, subject to approval by the Commission, shall accredit the said organization as the one and only AIPO of interior designers. All interior designers whose names appear in the Registry Book of Interior Designers shall ipso facto or automatically become members thereof and shall receive therefrom all the benefits and privileges due to members upon payment of AIPO membership fees and dues.\nMembership in other organizations of interior designers shall not be barred.\nFINAL PROVISIONS"}},{"id":"PH-H8803-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Penal Clause. – The following acts shall be punished by a fine of not less than Three hundred thousand pesos (Php300,000.00) but not more than One million pesos (Php1,000,000.00) or imprisonment of not less than six (6) months but not more than three (3) years, or both fine and imprisonment, at the discretion of the court.\n(a) Local Practitioner. –\n(1) Practicing interior design, rendering work and consultations or rendering equivalent services as interior designer as defined in this Act or using the title \"Interior Designer\", \"Interior Design Consultant\", \"Interior Design Stylist\", or \"Interior Design\" or the official appendage title \"IDr.\" in any signage, calling card, advertisement or any other mode of publicity without a valid certificate of registration and/or a valid professional identification card or a valid temporary/special permit;\n(2) Using or attempting to use the seal, certificate of registration and/or professional identification card of a registered interior designer or temporary/special permit issued to foreign professional;\n(3) Abetting the illegal practice of interior design by an unregistered or unauthorized person; and\n(4) Impersonating a registered interior designer or a holder of a temporary/special permit.\n(b) Foreign Practitioner/Firm. – The responsible officers of a foreign interior design firm and/or a foreigner who shall be found guilty of illegally practicing the interior design profession shall be penalized with a fine equivalent to thirty percent (30%) of their gross fees in addition to payment of back taxes due to the Philippine government, if any, and imprisonment of not less than six (6) months but not more than three (3) years, or both fine and imprisonment, as well as permanent ban from practice in the Philippines, at the discretion of the court.\n(c) Violation of any provision of this Act or the IRR thereof."}},{"id":"PH-H8803-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Civil Liability. – The interior designer shall assume full responsibility for the contract work within one (1) year from the final acceptance by the client and may be held responsible for any damage or destruction of the works except those occasioned by force majeure. Tire interior designer shall be fully responsible for the safety, protection, security and convenience of his clients/user, personnel, third parties, and the public at large, as well as the works, equipment installation and the like to be affected by his work.\nThe liability period for defects in the projects shall be one (1) year from final acceptance by the client. During this period, the interior designer shall undertake the repair works, at his/her own expense, of any damage to the projects arising from his/her design and/or specifications, within forty-five (45) days from the time the client has issued a notification of the need to undertake repair. In case of failure or refusal to comply with this mandate, the client may undertake such repair works and shall be entitled to full reimbursement of expenses incurred therein upon demand.\nThe failure of the responsible interior designer with the preceding paragraph shall be a ground for administrative disciplinary action for which he/she can be held liable for suspension or any appropriate penalty as may be determined by the Board."}},{"id":"PH-H8803-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Enforcement. – The Commission shall implement the concerned provisions of this Act, enforce the IRR as adopted by the Board, conduct investigations on complaints including violations of the Code of Conduct of the profession and prosecute the same when so warranted."}},{"id":"PH-H8803-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Appropriations. – The Chairperson of the Commission shall immediately include in the Commission’s program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8803-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Transitory Provisions. – The incumbent Chairman and members of the Board shall, in an interim capacity, continue to function as such until the Chairman and members of the new Board created under this Act shall have been appointed, constituted and/or organized pursuant thereto."}},{"id":"PH-H8803-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Implementing Rules and Regulations. – The Board, with the approval of the Commission, shall adopt and promulgate such IRR it may deem appropriate within ninety (90) days from its constitution. The same shall take effect after fifteen (15) days from its publication in the Official Gazette or in two (2) newspapers of general circulation in the country."}},{"id":"PH-H8803-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Separability Clause. – If any clause, provision, paragraph or part hereof shall be declared unconstitutional or invalid, the same shall not affect, invalidate or impair any other part hereof, and shall be merely confined to the clause, provision, paragraph or part directly involved in the controversy in which such judgment has been rendered."}},{"id":"PH-H8803-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Repealing Clause. – Republic Act No. 8534 is hereby repealed. All other laws, decrees, executive orders and administrative issuances or parts thereof which are inconsistent with the provisions of this Act are hereby modified, superseded and/or repealed accordingly."}},{"id":"PH-H8803-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days following its publication in the Official Gazette or m at least two (2) newspapers of general circulation in the country."}}],"pack":"ph-p125"};
  FT["PH-H8804"] = {"id":"PH-H8804","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10351_2012.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"通过修订第 8424 号共和国法（即 1997 年国家国内税收法典）第 141 至 145 条及第 8、131、288 条，重组烟酒产品消费税并为其他目的法案","en":"An Act Restructuring the Excise Tax on Alcohol and Tobacco Products by Amending Sections 141, 142, 143, 144, 145, 8, 131 and 288 of Republic Act No. 8424. Otherwise Known as the National Internal Revenue Code of 1997, as Amended by Republic Act No. 9334, and for Other Purposes","orig":"An Act Restructuring the Excise Tax on Alcohol and Tobacco Products by Amending Sections 141, 142, 143, 144, 145, 8, 131 and 288 of Republic Act No. 8424. Otherwise Known as the National Internal Revenue Code of 1997, as Amended by Republic Act No. 9334, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 10351","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-19","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10351_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8804-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 141 of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"Section 141. Distilled Spirits. – On distilled spirits, subject to the provisions of Section 133 of this Code, an excise tax shall be levied, assessed and collected based on the following schedules:\n\"(a) Effective on January 1, 2013 \"(1) An ad valorem tax equivalent to fifteen percent (15%) of the net retail price (excluding the excise tax and the value-added tax) per proof; and \"(2) In addition to the ad valorem tax herein imposed, a specific tax of Twenty pesos (P20.00) per proof liter.\n\"(b) Effective on January 1, 2015 \"(1) An ad valorem tax equivalent to twenty percent (20%) of the net retail price (excluding the excise tax and the value-added tax) per proof; and \"(2) In addition to the ad valorem tax herein imposed, a specific tax of Twenty pesos (P20.00) per proof liter.\n\"(c) In addition to the ad valorem tax herein imposed, the specific tax rate of Twenty pesos (P20.00) imposed under this Section shall be increased by four percent (4%) every year thereafter effective on January 1, 2016, through revenue regulations issued by the Secretary of Finance.\n\"Medicinal preparations, flavoring extracts, and all other preparations, except toilet preparations, of which, excluding water, distilled spirits form the chief ingredient, shall be subject to the same tax as such chief ingredient.\n\"This tax shall be proportionally increased for any strength of the spirits taxed over proof spirits, and the tax shall attach to this substance as soon as it is in existence as such, whether it be subsequently separated as pure or impure spirits, or transformed into any other substance either in the process of original production or by any subsequent process.\n\" ‘Spirits or distilled spirits’ is the substance known as ethyl alcohol, ethanol or spirits of wine, including all dilutions, purifications and mixtures thereof, from whatever source, by whatever process produced, and shall include whisky, brandy, rum, gin and vodka, and other similar products or mixtures.\n\" ‘Proof spirits’ is liquor containing one-half (1/2) of its volume of alcohol of a specific gravity of seven thousand nine hundred and thirty-nine ten thousandths (0.7939) at fifteen degrees centigrade (15°C). A ‘proof liter’ means a liter of proof spirits.\n\" ‘Net retail price’ shall mean the price at which the distilled spirits is sold on retail in at least five (5) major supermarkets in Metro Manila, excluding the amount intended to cover the applicable excise tax and the value-added tax. For distilled spirits which are marketed outside Metro Manila, the ‘net retail price’ shall mean the price at which the distilled spirits is sold in at least five (5) major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"Major supermarkets, as contemplated under this Act, shall be those with the highest annual gross sales in Metro Manila or the region, as the case may be, as determined by the National Statistics Office, and shall exclude retail outlets or kiosks, convenience or sari-sari stores, and others of a similar nature: Provided, That no two (2) supermarkets in the list to be surveyed are affiliated and/or branches of each other: Provided, finally, That in case a particular distilled spirit is not sold in major supermarkets, the price survey can be conducted in retail outlets where said distilled spirit is sold in Metro Manila or the region, as the case may be, upon the determination of the Commissioner of Internal Revenue.\n\"The net retail price shall be determined by the Bureau of Internal Revenue (B1R) through a price survey under oath.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Understatement of the suggested net retail price by as much as fifteen percent (15%) of the actual net retail price shall render the manufacturer or importer liable for additional excise tax equivalent to the tax due and difference between the understated suggested net retail price and the actual net retail price.\n\"Distilled spirits introduced in the domestic market after the effectivity of this Act shall be initially taxed according to their suggested net retail prices.\n\" ‘Suggested net retail price’ shall mean the net retail price at which locally manufactured or imported distilled spirits are intended by the manufacturer or importer to be sold on retail in major supermarkets or retail outlets in Metro Manila for those marketed nationwide, and in other regions, for those with regional markets. At the end of three (3) months from the product launch, the Bureau of Internal Revenue shall validate the suggested net retail price of the new brand against the net retail price as defined herein and initially determine the correct tax on a newly introduced distilled spirits. After the end of nine (9) months from such validation, , the Bureau of Internal Revenue shall revalidate the initially validated net retail price against the net retail price as of the time of revalidation in order to finally determine the correct tax on a newly introduced distilled spirits.\n\"All distilled spirits existing in the market at the time of the effectivity of this Act shall be taxed according to the tax rates provided above based on the latest price survey of the distilled spirits conducted by the Bureau of Internal Revenue.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Manufacturers and importers of distilled spirits shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every third month thereafter, submit to the Commissioner a sworn statement of the volume of sales for each particular brand of distilled spirits sold at his establishment for the three-month period immediately preceding.\n\"Any manufacturer or importer who, in violation of this Section, misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall, upon final findings by the Commissioner that the violation was committed, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of distilled spirits.\n\"Any corporation, association or partnership liable for any of the acts or omissions in violation of this Section shall be fined treble the amount of deficiency taxes, surcharges and interest which may be assessed pursuant to this Section.\n\"Any person liable for any of the acts or omissions prohibited under this Section shall be criminally liable and penalized under Section 254 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence, without further proceedings for deportation.\""}},{"id":"PH-H8804-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 142 of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"Section 142. Wines. – On wines, there shall be collected per liter of volume capacity effective on January 1, 2013, the following excise taxes:\n\"(a) Sparkling wines/champagnes regardless of proof, if the net retail price per bottle of seven hundred fifty milliliter (750 ml.) volume capacity (excluding the excise tax and the value-added tax) is:\n\"(1) Five hundred pesos (P500.00) or less -Two hundred fifty pesos (P250.00); and \"(2) More than Five hundred pesos (P500.00) – Seven hundred pesos (P700.00).\n\"(b) Still wines and carbonated wines containing fourteen percent (14%) of alcohol by volume or less, Thirty pesos (P30.00); and \"(c) Still wines and carbonated wines containing more than fourteen percent (14%) but not more than twenty-five percent (25%) of alcohol by volume, Sixty pesos (P60.00).\n\"The rates of tax imposed under this Section shall be increased by four percent (4%) every year thereafter effective on January 1, 2014, through revenue regulations issued by the Secretary of Finance.\n\"Fortified wines containing more than twenty-five percent (25%) of alcohol by volume shall be taxed as distilled spirits. ‘Fortified wines’ shall mean natural wines to which distilled spirits are added to increase their alcohol strength.\n\" ‘Net retail price’ shall mean the price at which sparkling wine/champagne is sold on retail in at least five (5) major supermarkets in Metro Manila, excluding the amount intended to cover the applicable excise tax and the value-added tax. For sparkling wines/champagnes which are marketed outside Metro Manila, the ‘net retail price’ shall mean the price at which the wine is sold in at least five (5) major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"Major supermarkets, as contemplated under this Act, shall be those with the highest annual gross sales in Metro Manila or the region, as the case may be, as determined by the National Statistics Office, and shall exclude retail outlets or kiosks, convenience or sari-sari stores, and others of a similar nature: Provided, That no two (2) supermarkets in the list to be surveyed are affiliated and/or branches of each other: Provided, finally, That in case a particular sparkling wine/champagne is not sold in major supermarkets, the price survey can be conducted in retail outlets where said sparkling wine/champagne is sold in Metro Manila or the region, as the case may be, upon the determination of the Commissioner of Internal Revenue.\n\"The net retail price shall be determined by the Bureau of Internal Revenue through a price survey under oath.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Understatement of the suggested net retail price by as much as fifteen percent (15%) of the actual net retail price shall render the manufacturer or importer liable for additional excise tax equivalent to the tax due and difference between the understated suggested net retail price and the actual net retail price.\n\"Sparkling wines/champagnes introduced in the domestic market after the effectivity of this Act shall be initially tax classified according to their suggested net retail prices.\n\" ‘Suggested net retail price’ shall mean the net retail price at which locally manufactured or imported sparkling wines/champagnes are intended by the manufacturer or importer to be sold on retail in major supermarkets or retail outlets in Metro Manila for those marketed nationwide, and in other regions, for those with regional markets. At the end of three (3) months from the product launch, the Bureau of Internal Revenue shall validate the suggested net retail price of the sparkling wine/champagne against the net retail price as defined herein and initially determine the correct tax bracket to which a newly introduced sparkling wine/champagne shall be classified. After the end of nine (9) months from such validation, the Bureau of Internal Revenue shall revalidate the initially validated net retail price against the net retail price as of the time of revalidation in order to finally determine the correct tax bracket to which a newly introduced sparkling wine/champagne shall be classified.\n\"The proper tax classification of sparkling wines/champagnes, whether registered before or after the effectivity of this Act, shall be determined every two (2) years from the date of effectivity of this Act.\n\"All sparkling wines/champagnes existing in the market at the time of the effectivity of this Act shall be classified according to the net retail prices and the tax rates provided above based on the latest price survey of the sparkling wines/champagnes conducted by the Bureau of Internal Revenue.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Manufacturers and importers of wines shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every month thereafter, submit to the Commissioner a sworn statement of the volume of sales for each particular brand of wines sold at his establishment for the three-month period immediately preceding.\n\"Any manufacturer or importer who, in violation of this Section, misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall, upon final findings by the Commissioner that the violation was committed be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of wines.\n\"Any corporation, association or partnership liable for any of the acts or omissions in violation of this Section shall be fined treble the amount of deficiency taxes, surcharges and interest which may be assessed pursuant to this Section.\n\"Any person liable for any of the acts or omissions prohibited under this Section shall be criminally liable and penalized under Section 254 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence, without further proceedings for deportation.\""}},{"id":"PH-H8804-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 143 of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"Section 143. Fermented Liquors. – There shall be levied, assessed and collected an excise tax on beer, lager beer, ale, porter and other fermented liquors except tuba, basi, tapuy and similar fermented liquors in accordance with the following schedule:\n\"Effective on January 1, 2013 \"(a) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is Fifty pesos and sixty centavos (P50.60) or less, the tax shall be Fifteen pesos (P15.00) per liter; and \"(b) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is more than Fifty pesos and sixty centavos (P50.60), the tax shall be Twenty pesos (P20.00) per liter.\n\"Effective on January 1, 2014 \"(a) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is Fifty pesos and sixty centavos (P50.60) or less, the tax shall be Seventeen pesos (P17.00) per liter; and \"(b) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is more than Fifty pesos and sixty centavos (P50.60), the tax shall be Twenty-one pesos (P21.00) per liter.\n\"Effective on January 1, 2015 \"(a) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is Fifty pesos and sixty centavos (P50.60) or less, the tax shall be Nineteen pesos (P19.00) per liter; and \"(b) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is more than Fifty pesos and sixty centavos (P50.60), the tax shall be Twenty-two pesos (P22.00) per liter.\n\"Effective on January 1, 2016 \"(a) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is Fifty pesos and sixty centavos (P50.60) or less, the tax shall be Twenty-one pesos (P21.00) per liter; and \"(b) If the net retail price (excluding the excise tax and the value-added tax) per liter of volume capacity is more than Fifty pesos and sixty centavos (P50.60), the tax shall be Twenty-three pesos (P23.00) per liter.\n\"Effective on January 1, 2017, the tax on all fermented liquors shall be Twenty-three pesos and fifty centavos (P23.50) per liter.\n\"The rates of tax imposed under this Section shall be increased by four percent (4%) every year thereafter effective on January 1, 2018, through revenue regulations issued by the Secretary of Finance. However, in case of fermented liquors affected by the ‘no downward reclassification’ provision prescribed under this Section, the four percent (4%) increase shah apply to their respective applicable tax rates.\n\"Fermented liquors which are brewed and sold at micro-breweries or small establishments such as pubs and restaurants shall be subject to the rate of Twenty-eight pesos (P28.00) per liter effective on January 1, 2013: Provided, That this rate shall be increased by four percent (4%) every year thereafter effective on January 1, 2014, through revenue regulations issued by the Secretary of Finance.\n\"Fermented liquors introduced in the domestic market after the effectivity of this Act shall be initially tax classified according to their suggested net retail prices.\n\" ‘Suggested net retail price’ shall mean the net retail price at which locally manufactured or imported fermented liquor are intended by the manufacturer or importer to be sold on retail in major supermarkets or retail outlets in Metro Manila for those marketed nationwide, and in other regions, for those with regional markets. At the end of three (3) months from the product launch, the Bureau of Internal Revenue shall validate the suggested net retail price of the newly introduced fermented liquor against the net retail price as defined herein and initially determine the correct tax bracket to which a newly introduced fermented liquor, as defined above, shall be classified. After the end of nine (9) months from such validation, the Bureau of Internal Revenue shall revalidate the initially validated net retail price against the net retail price as of the time of revalidation in order to finally determine the correct tax bracket which a newly introduced fermented liquor shall be classified.\n\" ‘Net retail price’ shall mean the price at which the fermented liquor is sold on retail in at least five (5) major supermarkets in Metro Manila (for brands of fermented liquor marketed nationally), excluding the amount intended to cover the applicable excise tax and the value-added tax. For brands which are marketed outside Metro Manila, the ‘net retail price’ shall mean the price at which the fermented liquor is sold in at least five (5) major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"Major supermarkets, as contemplated under this Act, shall be those with the highest annual gross sales in Metro Manila or the region, as the case may be, as determined by the National Statistics Office, and shall exclude retail outlets or kiosks, convenience or sari-sari stores, and others of a similar nature: Provided, That no two (2) supermarkets in the list to be surveyed are affiliated and/or branches of each other: Provided, finally, That in case a particular fermented liquor is not sold in major supermarkets, the price survey can be conducted in retail outlets where said fermented liquor is sold in Metro Manila or the region, as the case may be, upon the determination of the Commissioner of Internal Revenue.\n\"The net retail price shall be determined by the Bureau of Internal Revenue (BIR) through a price survey under oath.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Understatement of the suggested net retail price by as much as fifteen percent (15%) of the actual net retail price shall render the manufacturer or importer liable for additional excise tax equivalent to the tax due and difference between the understated suggested net retail price and the actual net retail price.\n\"Any downward reclassification of present categories, for tax purposes, of fermented liquors duly registered at the time of the effectivity of this Act which will reduce the tax imposed herein, or the payment thereof, shall be prohibited.\n\"The proper tax classification of fermented liquors, whether registered before or after the effectivity of this Act, shall be determined every two (2) years from the date of effectivity of this Act.\n\"All fermented liquors existing in the market at the time of the effectivity of this Act shall be classified according to the net retail prices and the tax rates provided above based on the latest price survey of the fermented liquors conducted by the Bureau of Internal Revenue.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"Every brewer or importer of fermented liquor shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every month thereafter, submit to the Commissioner a sworn statement of the volume of sales for each particular brand of fermented liquor sold at his establishment for the three-month period immediately preceding.\n\"Any brewer or importer who, in violation of this Section, misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall, upon final findings by the Commissioner that the violation was committed, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as brewer or importer of fermented liquor.\n\"Any corporation, association or partnership liable for any of the acts or omissions in violation of this Section shall be fined treble the amount of deficiency taxes, surcharges and interest which may be assessed pursuant to this Section.\n\"Any person liable for any of the acts or omissions prohibited under this Section shall be criminally liable and penalized under Section 254 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence, without further proceedings for deportation.\""}},{"id":"PH-H8804-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 144 of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"Section 144. Tobacco Products. – There shall be collected an excise tax of One peso and seventy-five centavos (P1.75) effective on January 1, 2013 on each kilogram of the following products of tobacco:\n\"(a) Tobacco twisted by hand or reduced into a condition to be consumed in any manner other than the ordinary mode of drying and curing;\n\"(b) Tobacco prepared or partially prepared with or without the use of any machine or instruments or without being pressed or sweetened except as otherwise provided hereunder; and \"(c) Fine-cut shorts and refuse, scraps, clippings, cuttings, stems and sweepings of tobacco except as otherwise provided hereunder.\n\"Stemmed leaf tobacco, tobacco prepared or partially prepared with or without the use of any machine or instrument or without being pressed or sweetened, fine-cut shorts and refuse, scraps, clippings, cuttings, stems, midribs, and sweepings of tobacco resulting from the handling or stripping of whole leaf tobacco shall be transferred, disposed of, or otherwise sold, without any prepayment of the excise tax herein provided for, if the same are to be exported or to be used in the manufacture of cigars, cigarettes, or other tobacco products on which the excise tax will eventually be paid on the finished product, under such conditions as may be prescribed in the rules and regulations promulgated by the Secretary of Finance, upon recommendation of the Commissioner.\n\"On tobacco specially prepared for chewing so as to be unsuitable for use in any other manner, on each kilogram, One peso and fifty centavos (P1.50) effective on January 1, 2013.\n\"The rates of tax imposed under this Section shall be increased by four percent. (4%) every year thereafter effective on January 1, 2014, through revenue regulations issued by the Secretary of Finance.\n\"No tobacco products manufactured in the Philippines and produced for export shall be removed from their place of manufacture or exported without posting of an export bond equivalent to the amount of the excise tax due thereon if sold domestically: Provided, however, That tobacco products for export may be transferred from the place of manufacture to a bonded facility, upon posting of a transfer bond, prior to export.\n\"Tobacco products imported into the Philippines and destined for foreign countries shall not be allowed entry without posting a bond equivalent to the amount of customs duty, excise and value-added taxes due thereon if sold domestically.\n\"Manufacturers and importers of tobacco products shall, within thirty (30) days from the effectivity of this Act, and within the first five (5) days of every month thereafter, submit to the Commissioner a sworn statement of the volume of sales for each particular brand of tobacco products sold for the three-month period immediately preceding.\n\"Any manufacturer or importer who, in violation of this Section, misdeclares or misrepresents hi his or its sworn statement herein required any pertinent data or information shall, upon final findings by the Commissioner that the violation was committed, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of cigars or cigarettes.\n\"Any corporation, association or partnership liable for any of the acts or omissions in violation of this Section shall be fined treble the amount of deficiency taxes, surcharges and interest which may be assessed pursuant to this Section.\n\"Any person liable for any of the acts or omissions prohibited under this Section shall be criminally liable and penalized under Section 254 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence, without further proceedings for deportation.\""}},{"id":"PH-H8804-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 145 of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"Section 145. Cigars and Cigarettes. – \"(A) Cigars. – There shall be levied, assessed and collected on cigars an excise tax in accordance with the following schedule:\n\"(1) Effective on January 1, 2013 \"(a) An ad valorem tax equivalent to twenty percent (20%) of the net retail price (excluding the excise tax and the value-added tax) per cigar; and \"(b) In addition to the ad valorem tax herein imposed, a specific tax of Five pesos (P5.00) per cigar.\n\"(2) In addition to the ad valorem tax herein imposed, the specific tax rate of Five pesos (P5.00) imposed under this subsection shall be increased by four percent (4%) effective on January 1, 2014 through revenue regulations issued by the Secretary of Finance.\n\"(B) Cigarettes Packed by Hand. - There shall be levied, assessed and collected on cigarettes packed by hand an excise tax based on the following schedules:\n\"Effective on January 1, 2013, Twelve pesos (P12.00) per pack;\n\"Effective on January 1, 2014, Fifteen pesos (P15.00) per pack;\n\"Effective on January 1, 2015, Eighteen pesos (P18.00) per pack;\n\"Effective on January 1, 2016, Twenty-one pesos (P21.00) per pack; and \"Effective on January 1, 2017, Thirty pesos (P30.00) per pack.\n\"The rates of tax imposed under this subsection shall be increased by four percent (4%) every year* effective on January 1, 2018, through revenue regulations issued by the Secretary of Finance.\n\"Duly registered cigarettes packed by hand shall only be packed in twenties and other packaging combinations of not more than twenty.\n\" ‘Cigarettes packed by hand’ shall refer to the manner of packaging of cigarette sticks using an individual person’s hands and not through any other means such as a mechanical device, machine or equipment.\n\"(C) Cigarettes Packed by Machine. – There shall be levied, assessed and collected on cigarettes packed by machine a tax at the rates prescribed below:\n\"Effective on January 1, 2013 \"(1) If the net retail price (excluding the excise tax and the value-added tax) is Eleven pesos and fifty centavos (P11.50) and below per pack, the tax shall be Twelve pesos (P12.00) per pack; and \"(2) If the net retail price (excluding the excise tax and the value-added tax) is more than Eleven pesos and fifty centavos (P11.50) per pack, the tax shall be Twenty-five pesos (P25.00) per pack.\n\"Effective on January 1, 2014 \"(1) If the net retail price (excluding the excise tax and the value-added tax) is Eleven pesos and fifty centavos (P11.50) and below per pack, the tax shall be Seventeen pesos (P17.00) per pack; and \"(2) If the net retail price (excluding the excise tax and the value-added tax) is more than Eleven pesos and fifty centavos (P11.50) per pack, the tax shall be Twenty-seven pesos (P27.00) per pack.\n\"Effective on January 1, 2015 \"(1) If the net retail price (excluding the excise tax and the value-added tax) is Eleven pesos and fifty centavos (P11.50) and below per pack, the tax shall be Twenty-one pesos (P21.00) per pack; and \"(2) If the net retail price (excluding the excise tax and the value-added tax) is more than Eleven pesos and fifty centavos (P11.50) per pack, the tax shall be Twenty-eight pesos (P28.00) per pack.\n\"Effective on January 1, 2016 \"(1) If the net retail price (excluding the excise tax and the value-added tax) is Eleven pesos and fifty centavos (P11.50) and below per pack, the tax shall be Twenty-five pesos (P25.00) per pack; and \"(2) If the net retail price (excluding the excise tax and the value-added tax) is more than Eleven pesos and fifty centavos (P11.50) per pack, the tax shall be Twenty-nine pesos (P29.00) per pack.\n\"Effective on January 1, 2017, the tax on all cigarettes packed by machine shall be Thirty pesos (P30.00) per pack.\n\"The rates of tax imposed under this subsection shall be increased by four percent (4%) every year thereafter effective on January 1, 2018, through revenue regulations issued by the Secretary of Finance.\n\"Duly registered cigarettes packed by machine shall only be packed in twenties and other packaging combinations of not more than twenty.\n\"Understatement of the suggested net retail price by as much as fifteen percent (15%) of the actual net retail price shall render the manufacturer or importer liable for additional excise tax equivalent to the tax due and difference between the understated suggested net retail price and the actual net retail price.\n\"Cigarettes introduced in the domestic market after the effectivity of this Act shall be initially tax classified according to their suggested net retail prices.\n\" ‘Suggested net retail price’ shall mean the net retail price at which locally manufactured or imported cigarettes are intended by the manufacturer or importer to be sold on retail in major supermarkets or retail outlets in Metro Manila for those marketed nationwide, and in other regions, for those with regional markets. At the end of three (3) months from the product launch, the Bureau of Internal Revenue shall validate the suggested net retail price of the newly introduced cigarette against the net retail price as defined herein and initially determine the correct tax bracket under which a newly introduced cigarette shall be classified. After the end of nine (9) months from such validation, the Bureau of Internal Revenue shall revalidate the initially validated net retail price against the net retail price as of the time of revalidation in order to finally determine the correct tax bracket under which a newly introduced cigarette shall be classified.\n\" ‘Net retail price’ shall mean the price at which the cigarette is sold on retail in at least five (5) major supermarkets in Metro Manila (for brands of cigarettes marketed nationally), excluding the amount intended to cover the applicable excise tax and the value-added tax. For cigarettes which are marketed only outside Metro Manila, the ‘net retail price’ shah mean the price at which the cigarette is sold in at least five (5) major supermarkets in the region excluding the amount intended to cover the applicable excise tax and the value-added tax.\n\"Major supermarkets, as contemplated under this Act, shall be those with the highest annual gross sales in Metro Manila or the region, as the case may be, as determined by the National Statistics Office, and shall exclude retail outlets or kiosks, convenience or sari-sari stores, and others of a similar nature: Provided, That no two (2) supermarkets in the list to be surveyed are affiliated and/or branches of each other: Provided, finally, That in case a particular cigarette is not sold in major supermarkets, the price survey can be conducted in retail outlets where said cigarette is sold in Metro Manila or the region, as the case may be, upon the determination of the Commissioner of Internal Revenue.\n\"The net retail price shall be determined by the Bureau of Internal Revenue through a price survey under oath.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"The proper tax classification of cigarettes, whether registered before or after the effectivity of this Act, shall be determined every two (2) years from the date of effectivity of this Act.\n\"All cigarettes existing in the market at the time of the effectivity of this Act shall be classified according to the net retail prices and the tax rates provided above based on the latest price survey of cigarettes conducted by the Bureau of Internal Revenue.\n\"The methodology and all pertinent documents used in the conduct of the latest price survey shall be submitted to the Congressional Oversight Committee on the Comprehensive Tax Reform Program created under Republic Act No. 8240.\n\"No tobacco products manufactured in the Philippines and produced for export shall be removed from their place of manufacture or exported without posting of an export bond equivalent to the amount of the excise tax due thereon if sold domestically: Provided, however, That tobacco products for export may be transferred from the place of manufacture to a bonded facility, upon posting of a transfer bond, prior to export.\n\"Tobacco products imported into the Philippines and destined for foreign countries shall not be allowed entry without posting a bond equivalent to the amount of customs duty, excise and value-added taxes due thereon if sold domestically.\n\"Of the total volume of cigarettes sold in the country, any manufacturer and/or seller of tobacco products must procure at least fifteen percent (15%) of its tobacco leaf raw material requirements from locally grown sources, subject to adjustments based on international treaty commitments.\n\"Manufacturers and importers of cigars and cigarettes shall, within thirty (30) days from the effectivity of this Act and within the first five (5) days of every month thereafter, submit to the Commissioner a sworn statement of the volume of sales for cigars and/or cigarettes sold for the three-month period immediately preceding.\n\"Any manufacturer or importer who, in violation of this Section, misdeclares or misrepresents in his or its sworn statement herein required any pertinent data or information shall, upon final findings by the Commissioner that the violation was committed, be penalized by a summary cancellation or withdrawal of his or its permit to engage in business as manufacturer or importer of cigars or cigarettes.\n\"Any corporation, association or partnership liable for any of the acts or omissions in violation of this Section shall be fined treble the aggregate amount of deficiency taxes, surcharges and interest which may be assessed pursuant to this Section.\n\"Any person liable for any of the acts or omissions prohibited under this Section shall be criminally liable and penalized under Section 254 of this Code. Any person who willfully aids or abets in the commission of any such act or omission shall be criminally liable in the same manner as the principal.\n\"If the offender is not a citizen of the Philippines, he shall be deported immediately after serving the sentence, without further proceedings for deportation.\""}},{"id":"PH-H8804-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 8 of Republic Act No. 8424 or the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 8. Duty of the Commissioner to Ensure the Provision and Distribution of Forms, Receipts, Certificates, and Appliances, and the Acknowledgment of Payment of Taxes. - \"(A) Provision and Distribution to Proper-Officials. – Any law to the contrary notwithstanding, it shah be the duty of the Commissioner, among other things, to prescribe, provide, and distribute to the proper officials the requisite licenses; internal revenue stamps; unique, secure and nonremovable identification markings (hereafter called unique identification markings), such as codes or stamps, be affixed to or form part of all unit packets and packages and any outside packaging of cigarettes and bottles of distilled spirits; labels and other forms; certificates; bonds; records; invoices; books; receipts; instruments; appliances and apparatus used in administering the laws falling within the jurisdiction of the Bureau. For this purpose, internal revenue stamps, or other markings and labels shall be caused by the Commissioner to be printed with adequate security features.\n\"Internal revenue stamps, whether of a bar code or fuson design, or other markings shall be firmly and conspicuously affixed or printed on each pack of cigars and cigarettes and bottles of distilled spirits subject to excise tax in the manner and form as prescribed by the Commissioner, upon approval of the Secretary of Finance.\n\"To further improve tax administration,’ cigarette and alcohol manufacturers shall be required to install automated volume-counters of packs and bottles to deter over-removals and misdeclaration of removals.\""}},{"id":"PH-H8804-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 131, Subsection A of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended as follows:\n\"Section 131. Payment of Excise Taxes on. Imported Articles. – \"x x x \"The provision of any special or general law to the contrary notwithstanding, the importation of cigars and cigarettes distilled spirits, fermented liquors and wines into the Philippines, even if destined for tax and duty-free shops, shall be subject to all applicable taxes, duties, charges, including excise taxes due thereon. This shall apply to cigars and cigarettes, distilled spirits, fermented liquors and wines brought directly into the duly chartered or legislated freeports of the Subic Special Economic and Freeport Zone, created under Republic Act No. 7227; the Cagayan Special Economic Zone and Freeport, created under Republic Act No. 7922; and the Zamboanga City Special Economic Zone, created under Republic Act No. 7903, and such other freeports as may hereafter be established or created by law: Provided, further, That notwithstanding the provisions of Republic Act Nos. 9400 and 9593, importations of cigars and cigarettes, distilled spirits, fermented liquors and wines made directly by a government-owned and operated duty-free shop, like the Duty-Free Philippines (DFP), shall be exempted from all applicable duties only: x x x \"x x x \"Articles confiscated shall be destroyed using the most environmentally friendly method available in accordance with the rules and regulations to be promulgated by the Secretary of Finance, upon recommendation of the Commissioners of Customs and Internal Revenue.\n\"x x x.\""}},{"id":"PH-H8804-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 288, subsections (B) and (C) of the National Internal Revenue Code of 1997, as amended by Republic Act No. 9334, is hereby further amended to read as follows:\n\"(B) Incremental Revenues from Republic Act No. 8240. – Fifteen percent (15%) of the incremental revenue collected from the excise tax on tobacco products under R. A. No. 8240 shall be allocated and divided among the provinces producing burley and native tobacco in accordance with the volume of tobacco leaf production. The fund shall be exclusively utilized for programs to promote economically viable alternatives for tobacco farmers and workers such as:\n\"(1) Programs that will provide inputs, training, and other support for tobacco farmers who shift to production of agricultural products other than tobacco including, but not limited to, high-value crops, spices, rice, corn, sugarcane, coconut, livestock and fisheries;\n\"(2) Programs that will provide financial support for tobacco farmers who are displaced or who cease to produce tobacco;\n\"(3) Cooperative programs to assist tobacco farmers in planting alternative crops or implementing other livelihood projects;\n\"(4) Livelihood programs and projects that will promote, enhance, and develop the tourism potential of tobacco-growing provinces;\n\"(5) Infrastructure projects such as farm to market roads, schools, hospitals, and rural health facilities; and \"(6) Agro-industrial projects that will enable tobacco farmers to be involved in the management and subsequent ownership of projects, such as post-harvest and secondary processing like cigarette manufacturing and by-product utilization.\n\"The Department of Budget and Management, in consultation with the Department of Agriculture, shall issue rules and regulations governing the allocation and disbursement of this fund, not later than one hundred eighty (] 80) days from the effectivity of this Act.\n\"(C) Incremental Revenues from the Excise Tax on Alcohol and Tobacco Products. – \"After deducting the allocations under Republic Act Nos. 7171 and 8240, eighty percent (80%) of the remaining balance of the incremental revenue derived from this Act shall be allocated for the universal health care under the National Health Insurance Program, the attainment of the millennium development goals and health awareness programs; and twenty percent (20%) shall be allocated nationwide, based on political and district subdivisions, for medical assistance and health enhancement facilities program, the annual requirements of which shall be determined by the Department of Health (DOH).\""}},{"id":"PH-H8804-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Transitory Provision. – A special financial support for displaced workers in the alcohol and tobacco industries shall be allocated and included in the appropriations under the Department of Labor and Employment (DOLE) to finance unemployment alleviation program; and to the Technical Education and Skills Development Authority (TESDA) to finance the training and retooling programs of displaced workers, to be included in the General Appropriations Acts for the Fiscal Years 2014 to 2017."}},{"id":"PH-H8804-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Annual Report. – The Department of Budget and Management (DBM), the Department of Agriculture (DA), the Department of Health (DOH) and the Philippine Health Insurance Corporation (PhilHealth) shall each submit to the Oversight Committee, created under Republic Act No. 8240, a detailed report on the expenditure of the amounts earmarked in this Section on the first week of August of every year. The reports shall be simultaneously published in the Official Gazette and in the agencies’ websites."}},{"id":"PH-H8804-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Congressional Oversight Committee. – The composition of the Congressional Oversight Committee, created under Republic Act No. 8240, shall include the Agriculture and Health Committee Chairpersons of the Senate and the House of Representatives as part of the four (4) members to be appointed from each House.\nUpon receipt of the annual reports from the DBM, DA, DOH, DOLE, PhilHealth and TESDA, the Committee shall review and ensure the proper implementation of this Act as regards the expenditures of the earmarked funds.\nStarting the third quarter of Calendar Year 2016, the Committee is mandated to review the impact of the tax rates provided under this Act."}},{"id":"PH-H8804-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Implementing Rules and Regulations. – The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, and in consultation with the Department of Health, promulgate the necessary rules and regulations for the effective implementation of this Act not later than one hundred eighty (180) days upon the effectivity of this Act."}},{"id":"PH-H8804-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. – If any of the provisions of this Act is declared invalid by a competent court, the remainder of this Act or any provision not affected by such declaration of invalidity shall remain in force and effect."}},{"id":"PH-H8804-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. – All laws, decrees ordinances, rules and regulations, executive or administrative orders and such other presidential issuances that are inconsistent with any of the provisions of this Act are hereby repealed, amended or otherwise modified accordingly."}},{"id":"PH-H8804-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity. – This Act shall take effect upon its publication in a newspaper of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Restructuring the Excise Tax on Alcohol and Tobacco Products by Amending Sections 141, 142, 143, 144, 145, 8, 131 and 288 of Republic Act No. 8424. Otherwise Known as the National Internal Revenue Code of 1997, as Amended by Republic Act No. 9334, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8805"] = {"id":"PH-H8805","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10353_2012.html","fetchedAt":"2026-10-06","articleCount":33,"structureMode":"ARTICLE","title":{"zh":"界定并处罚强迫或非自愿失踪的法案","en":"An Act Defining and Penalizing Enforced or Involuntary Disappearance","orig":"An Act Defining and Penalizing Enforced or Involuntary Disappearance","vi":"Đạo luật xác định và trừng phạt hành vi cưỡng bức mất tích","th":"พระราชบัญญัติกำหนดและลงโทษการบังคับให้บุคคลสูญหาย","id":"Undang-Undang menetapkan dan menghukum tindak pidana penghilangan orang secara paksa","ms":"Akta menetapkan dan menghukum kehilangan orang secara paksa"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 10353","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-21","completenessNote":"全文，共 33 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10353_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8805-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. –This Act shall be known as the \"Anti-Enforced or Involuntary Disappearance Act of 2012″."}},{"id":"PH-H8805-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. –The State values the dignity of every human person and guarantees full respect for human rights for which highest priority shall be given to the enactment of measures for the enhancement of the right of all people to human dignity, the prohibition against secret detention places, solitary confinement, incommunicado, or other similar forms of detention, the provision for penal and civil sanctions for such violations, and compensation and rehabilitation for the victims and their families, particularly with respect to the use of torture, force, violence, threat, intimidation or any other means which vitiate the free will of persons abducted, arrested, detained, disappeared or otherwise removed from the effective protection of the law.\nFurthermore, the State adheres to the principles and standards on the absolute condemnation of human rights violations set by the 1987 Philippine Constitution and various international instruments such as, but not limited to, the International Covenant on Civil and Political Rights (ICCPR), and the Convention Against Torture and Other Cruel, Inhuman or Degrading Treatment or Punishment (CAT), to which the Philippines is a State party."}},{"id":"PH-H8805-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. –For purposes of this Act, the following terms shall be defined as follows:\n(a) Agents of the State refer to persons who, by direct provision of the law, popular election or appointment by competent authority, shall take part in the performance of public functions in the government, or shall perform in the government or in any of its branches public duties as an employee, agent or subordinate official, of any rank or class.\n(b) Enforced or involuntary disappearance refers to the arrest, detention, abduction or any other form of deprivation of liberty committed by agents of the State or by persons or groups of persons acting with the authorization, support or acquiescence of the State, followed by a refusal to acknowledge the deprivation of liberty or by concealment of the fate or whereabouts of the disappeared person, which places such person outside the protection of the law.\n(c) O rder of Battle refers to a document made by the military, police or any law enforcement agency of the government, listing the names of persons and organizations that it perceives to be enemies of the State and which it considers as legitimate targets as combatants that it could deal with, through the use of means allowed by domestic and international law.\n(d) Victim refers to the disappeared person and any individual who has suffered harm as a direct result of an enforced or involuntary disappearance as defined in letter (b) of this Section."}},{"id":"PH-H8805-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Nonderogability of the Right Against Enforced or Involuntary Disappearance. –The right against enforced or involuntary disappearance and the fundamental safeguards for its prevention shall not be suspended under any circumstance including political instability, threat of war, state of war or other public emergencies."}},{"id":"PH-H8805-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"\"Order of Battle\" or Any Order of Similar Nature, Not Legal Ground, for Enforced or Involuntary Disappearance. – An \"Order of Battle\" or any order of similar nature, official or otherwise, from a superior officer or a public authority causing the commission of enforced or involuntary disappearance is unlawful and cannot be invoked as a justifying or exempting circumstance. Any person receiving such an order shall have the right to disobey it."}},{"id":"PH-H8805-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Access to Communication. – It shall be the absolute right of any person deprived of liberty to have immediate access to any form of communication available in order for him or her to inform his or her family, relative, friend, lawyer or any human rights organization on his or her whereabouts and condition."}},{"id":"PH-H8805-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Duty to Report Victims of Enforced or Involuntary Disappearance. – Any person, not being a principal, accomplice or accessory, who has an information of a case of enforced or involuntary disappearance or who shall learn of such information or that a person is a victim of enforced or involuntary disappearance, shall immediately report in writing the circumstances and whereabouts of the victim to any office, detachment or division of the Department of the Interior and Local Government (DILG), the Department of National Defense (DND), the Philippine National Police (PNP), the Armed Forces of the Philippines (AFP), the National Bureau of Investigation (NBI), the City or Provincial Prosecutor, the Commission on Human Rights (CHR) or any human rights organization and, if known, the victim’s family, relative, or lawyer."}},{"id":"PH-H8805-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Duty to Certify in Writing on the Results of Inquiry into a Reported Disappeared Person’s Whereabouts. –In case a family member, relative, lawyer, representative of a human rights organization or a member of the media inquires with a member or official of any police or military detention center, the PNP or any of its agencies, the AFP or any of its agencies, the NBI or any other agency or instrumentality of the government, as well as any hospital or morgue, public or private, on the presence or whereabouts of a reported victim of enforced or involuntary disappearance, such member or official shall immediately issue a certification in writing to the inquiring person or entity on the presence or absence and/or information on the whereabouts of such disappeared person, stating, among others, in clear and unequivocal manner the date and time of inquiry, details of the inquiry and the response to the inquiry."}},{"id":"PH-H8805-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Duty of Inquest/Investigating Public Prosecutor or any Judicial or Quasi-Judicial Official or Employee. –Any inquest or investigating public prosecutor, or any judicial or quasi-judicial official or employee who learns that the person delivered for inquest or preliminary investigation or for any other judicial process is a victim of enforced or involuntary disappearance shall have the duty to immediately disclose the victim’s whereabouts to his or her immediate family, relatives, lawyer/s or to a human rights organization by the most expedient means."}},{"id":"PH-H8805-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Official Up-to-Date Register of All Persons Detained or Confined. - All persons detained or confined shall be placed solely in officially recognized and controlled places of detention or confinement where an official up-to-date register of such persons shall be maintained. Relatives, lawyers, judges, official bodies and all persons who have legitimate interest in the whereabouts and condition of the persons deprived of liberty shall have free access to the register.\nThe following details, among others, shall be recorded, in the register:\n(a) The identity or name, description and address of the person deprived of liberty;\n(b) The date, time and location where the person was deprived of liberty and the identity of the person who made such deprivation of liberty;\n(c) The authority who decided the deprivation of liberty and the reasons for the deprivation of liberty or the crime or offense committed;\n(d) The authority controlling the deprivation of liberty;\n(e) The place of deprivation of liberty, the date and time of admission to the place of deprivation of liberty and the authority responsible for the place of deprivation of liberty;\n(f) Records of physical, mental and psychological condition of the detained or confined person before and after the deprivation of liberty and the name and address of the physician who examined him or her physically, mentally and medically;\n(g) The date and time of release or transfer of the detained or confined person to another place of detention, the destination and the authority responsible for the transfer;\n(h) The date and time of each removal of the detained or confined person from his or her cell, the reason or purpose for such removal and the date and time of his or her return to his or her cell;\n(i) A summary of the physical, mental and medical findings of the detained or confined person after each interrogation;\n(j) The names and addresses of the persons who visit the detained or confined person and the date and time of such visits and the date and time of each departure;\n(k) In the event of death during the deprivation of liberty, the identity, the circumstances and cause of death of the victim as well as the destination of the human remains; and\n(l) All other important events bearing on and all relevant details regarding the treatment of the detained or confined person.\nProvided, That the details required under letters (a) to (f) shall be entered immediately in the register upon arrest and/or detention.\nAll information contained in the register shall be regularly or upon request reported to the CHR or any other agency of government tasked to monitor and protect human rights and shall be made available to the public."}},{"id":"PH-H8805-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Submission of List of Government Detention Facilities. –Within six (6) months from the effectivity of this Act and as may be requested by the CHR thereafter, all government agencies concerned shall submit an updated inventory or list of all officially recognized and controlled detention or confinement facilities, and the list of detainees or persons deprived of liberty under their respective jurisdictions to the CHR."}},{"id":"PH-H8805-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Immediate Issuance and Compliance of the Writs of Habeas Corpus, Amparo and Habeas Data. – All proceedings pertaining to the issuance of the writs of habeas corpus, amparo and habeas data shall be dispensed with expeditiously. As such, all courts and other concerned agencies of government shall give priority to such proceedings.\nMoreover, any order issued or promulgated pursuant to such writs or their respective proceedings shall be executed and complied with immediately."}},{"id":"PH-H8805-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Visitation /Inspection of Places of Detention and, Confinement. –The CHR or its duly authorized representatives are hereby mandated and authorized to conduct regular, independent, unannounced and unrestricted visits to or inspection of all places of detention and confinement."}},{"id":"PH-H8805-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Liability of Commanding Officer or Superior. - The immediate commanding officer of the unit concerned of the AFP or the immediate senior official of the PNP and other law enforcement agencies shall be held liable as a principal to the crime of enforced or involuntary disappearance for acts committed by him or her that shall have led, assisted, abetted or allowed, whether directly or indirectly, the commission thereof by his or her subordinates. If such commanding officer has knowledge of or, owing to the circumstances at the time, should have known that an enforced or involuntary disappearance is being committed, or has been committed by subordinates or by others within the officer’s area of responsibility and, despite such knowledge, did not take preventive or coercive action either before, during or immediately after its commission, when he or she has the authority to prevent or investigate allegations of enforced or involuntary disappearance but failed to prevent or investigate such allegations, whether deliberately or due to negligence, shall also be held liable as principal."}},{"id":"PH-H8805-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Penal Provisions. – (a) The penalty of reclusion perpetua and its accessory penalties shall be imposed upon the following persons:\n(1) Those who directly committed the act of enforced or involuntary disappearance;\n(2) Those who directly forced, instigated, encouraged or induced others to commit the act of enforced or involuntary disappearance;\n(3) Those who cooperated in the act of enforced or involuntary disappearance by committing another act without which the act of enforced or involuntary disappearance would not have been consummated;\n(4) Those officials who allowed the act or abetted in the consummation of enforced or involuntary disappearance when it is within their power to stop or uncover the commission thereof; and\n(5) Those who cooperated in the execution of the act of enforced or involuntary disappearance by previous or simultaneous acts.\n(b) The penalty of reclusion temporal and its accessory penalties shall be imposed upon those who shall commit the act of enforced or involuntary disappearance in the attempted stage as provided for and defined under Article 6 of the Revised Penal Code.\n(c) The penalty of reclusion temporal and its accessory penalties shall also be imposed upon persons who, having knowledge of the act of enforced or involuntary disappearance and without having participated therein, either as principals or accomplices, took part subsequent to its commission in any of the following manner:\n(1) By themselves profiting from or assisting the offender to profit from the effects of the act of enforced or involuntary disappearance;\n(2) By concealing the act of enforced or involuntary disappearance and/or destroying the effects or instruments thereof in order to prevent its discovery; or\n(3) By harboring, concealing or assisting in the escape of the principal/s in the act of enforced or involuntary disappearance, provided such accessory acts are done with the abuse of official functions.\n(d) The penalty of prision correctional and its accessory penalties shall be imposed against persons who defy, ignore or unduly delay compliance with any order duly issued or promulgated pursuant to the writs of habeas corpus, amparo and habeas data or their respective proceedings.\n(e) The penalty of arresto mayor and its accessory penalties shall be imposed against any person who shall violate the provisions of Sections 6, 7, 8, 9 and 10 of this Act."}},{"id":"PH-H8805-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Preventive Suspension/Summary Dismissal. –Government officials and personnel who are found to be perpetrators of or participants in any manner in the commission of enforced or involuntary disappearance as a result of a preliminary investigation conducted for that purpose shall be preventively suspended or summarily dismissed from the service, depending on the strength of the evidence so presented and gathered in the said preliminary investigation or as may be recommended by the investigating authority."}},{"id":"PH-H8805-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Civil Liability. –The act of enforced or involuntary disappearance shall render its perpetrators and the State agencies which organized, acquiesced in or tolerated such disappearance liable under civil law."}},{"id":"PH-H8805-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Independent Liability. –The criminal liability of the offender under this Act shall be independent of or without prejudice to the prosecution and conviction of the said offender for any violation of Republic Act No. 7438, otherwise known as \"An Act Defining Certain Rights of Person Arrested, Detained or Under Custodial Investigation as well as the Duties of the Arresting, Detaining, and Investigating Officers, and Providing Penalties for Violations Thereof’; Republic Act No. 9745, otherwise known as \"An Act Penalizing Torture and Other Cruel, Inhuman and Degrading Treatment or Punishment, and Prescribing Penalties Therefor\"; and applicable provisions of the Revised Penal Code."}},{"id":"PH-H8805-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Nonexclusivity or Double Jeopardy Under International Law. – Any investigation, trial and decision in any Philippines court, or body for any violation of this Act shall; be without prejudice to any investigation, trial, decision or any other legal or administrative process before any appropriate international court or agency under applicable international human rights and humanitarian law."}},{"id":"PH-H8805-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Exemption from Prosecution. – Any offender who volunteers information that leads to the discovery of the victim of enforced or involuntary disappearance or the prosecution of the offenders without the victim being found shall be exempt from any criminal and/or civil liability under this Act: Provided , That said offender does not appear to be the most guilty."}},{"id":"PH-H8805-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Continuing Offense. – An act constituting enforced or involuntary disappearance shall be considered a continuing offense as long as the perpetrators continue to conceal the fate and whereabouts of the disappeared person and such circumstances have not been determined with certainty."}},{"id":"PH-H8805-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Statue of Limitations Exemption. – The prosecution of persons responsible for enforced or involuntary disappearance shall not prescribe unless the victim surfaces alive. In which case, the prescriptive period shall be twenty-five (25) years from the date of such reappearance."}},{"id":"PH-H8805-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Special Amnesty Law Exclusion. – Persons who are changed with and/or guilty of the act of enforced or involuntary disappearance shall not benefit from any special amnesty law or other similar executive measures that shall exempt them from any penal proceedings or sanctions."}},{"id":"PH-H8805-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"State Protection – The State, through its appropriate agencies, shall ensure the safety of all persons involved in the search, investigation and prosecution of enforced or involuntary disappearance including, but not limited to, the victims, their families, complainants, witnesses, legal counsel and representatives of human rights organizations and media. They shall likewise be protected from any intimidation or reprisal."}},{"id":"PH-H8805-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Applicability of Refouler. –No person shall be expelled, returned or extradited to another State where there are substantial grounds to believe that such person shall be in danger of being subjected to enforced or involuntary disappearance. For purposes of determining whether such grounds exist, the Secretary of the Department, of Foreign Affairs (DFA) and the Secretary of the Department of Justice (DOJ) in coordination with the Chairperson of the CHR, shall take into account all relevant considerations including where applicable and not limited to, the existence in the requesting State of a consistent pattern of gross, flagrant or mass violations of human rights."}},{"id":"PH-H8805-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Restitution and Compensation to Victims of Enforced or Involuntary Disappearance and/or Their Immediate Relatives. –The victims of enforced or involuntary disappearance who surface alive shall be entitled to monetary compensation, rehabilitation and restitution of honor and reputation. Such restitution of honor and reputation shall include immediate expunging or rectification of any derogatory record, information or public declaration/statement on his or her person, personal circumstances, status, and/or organizational affiliation by the appropriate government or private agency or agencies concerned.\nThe immediate relatives of a victim of enforced or involuntary disappearance, within the fourth civil degree of consanguinity or affinity, may also claim for compensation as provided for under Republic Act No. 7309, entitled \"An Act Creating a Board of Claims under the Department of Justice for Victims of Unjust Imprisonment or Detention and Victims of Violent Crimes and For Other Purposes\", and other relief programs of the government.\nThe package of indemnification for both the victims and the immediate relatives within the fourth civil degree of consanguinity or affinity shall be without prejudice to other legal remedies that may be available to them."}},{"id":"PH-H8805-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Rehabilitation of Victims and/or Their Immediate Relatives, and Offenders. – In order that the victims of enforced or involuntary disappearance who surfaced alive and/or their immediate relatives within the fourth civil degree of consanguinity or affinity, may be effectively reintegrated into the mainstream of society and in the process of development, the State, through the CHR, in coordination with the Department of Health, the Department of Social Welfare and Development (DSWD) and the concerned nongovernment organization/s, shall provide them with appropriate medical care and rehabilitation free of charge.\nToward the attainment of restorative justice, a parallel rehabilitation program for persons who have committed enforced or involuntary disappearance shall likewise be implemented without cost to such offenders."}},{"id":"PH-H8805-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Implementing Rules and Regulations. – Within thirty (30) days from the effectivity of this Act, the DOJ, the DSWD, the CHR, the Families of Victims of Involuntary Disappearance (FIND) and the Families of Desaparecidos for Justice (Desaparecidos), in consultation with other human rights organizations, shall jointly promulgate the rules and regulations for the effective implementation of this Act and shall ensure the full dissemination of the same to the public."}},{"id":"PH-H8805-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Suppletory Applications. – The applicable provisions of the Revised Penal Code shall have suppletory application insofar as they are consistent with the provisions of this Act."}},{"id":"PH-H8805-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Appropriations. –The amount of Ten million pesos (P10,000,000.00) is hereby appropriated for the initial implementation of this Act by the CHR. Subsequent fluids for the continuing implementation of this Act shall be included in the respective budgets of the CHR and the DOJ in the annual General Appropriations Act."}},{"id":"PH-H8805-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Separability Clause. –If for any reason, any section or provision of this Act is declared unconstitutional or invalid, such other sections or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H8805-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations and other issuances or parts thereof inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8805-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation or the Official Gazette, which shall not be later than seven (7) days after the approval thereof."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Defining and Penalizing Enforced or Involuntary Disappearance","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8806"] = {"id":"PH-H8806","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10354_2012.html","fetchedAt":"2026-10-06","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"规定负责任父母与生殖健康国家政策的法案，即 2012 年负责任父母与生殖健康法","en":"An Act Providing for a National Policy on Responsible Parenthood and Reproductive Health The Responsible Parenthood and Reproductive Health Act of 2012","orig":"An Act Providing for a National Policy on Responsible Parenthood and Reproductive Health The Responsible Parenthood and Reproductive Health Act of 2012","vi":"Đạo luật quy định chính sách quốc gia về cha mẹ có trách nhiệm và sức khỏe sinh sản năm 2012","th":"พระราชบัญญัติกำหนดนโยบายแห่งชาติว่าด้วยความเป็นพ่อแม่ที่มีความรับผิดชอบและอนามัยการเจริญพันธุ์ ค.ศ. 2012","id":"Undang-Undang menetapkan kebijakan nasional tentang orang tua bertanggung jawab dan kesehatan reproduksi Tahun 2012","ms":"Akta menetapkan dasar negara tentang ibu bapa bertanggungjawab dan kesihatan reproduktif 2012"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10354","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-12-21","completenessNote":"全文，共 30 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10354_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8806-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as \"The Responsible Parenthood and Reproductive Health Act of 2012″."}},{"id":"PH-H8806-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – The State recognizes and guarantees the human rights of all persons including their right to equality and nondiscrimination of these rights, the right to sustainable human development, the right to health which includes reproductive health, the right to education and information, and the right to choose and make decisions for themselves in accordance with their religious convictions, ethics, cultural beliefs, and the demands of responsible parenthood.\nPursuant to the declaration of State policies under Section 12, Article II of the 1987 Philippine Constitution, it is the duty of the State to protect and strengthen the family as a basic autonomous social institution and equally protect the life of the mother and the life of the unborn from conception. The State shall protect and promote the right to health of women especially mothers in particular and of the people in general and instill health consciousness among them. The family is the natural and fundamental unit of society. The State shall likewise protect and advance the right of families in particular and the people in general to a balanced and healthful environment in accord with the rhythm and harmony of nature. The State also recognizes and guarantees the promotion and equal protection of the welfare and rights of children, the youth, and the unborn.\nMoreover, the State recognizes and guarantees the promotion of gender equality, gender equity, women empowerment and dignity as a health and human rights concern and as a social responsibility. The advancement and protection of women’s human rights shall be central to the efforts of the State to address reproductive health care.\nThe State recognizes marriage as an inviolable social institution and the foundation of the family which in turn is the foundation of the nation. Pursuant thereto, the State shall defend:\n(a) The right of spouses to found a family in accordance with their religious convictions and the demands of responsible parenthood;\n(b) The right of children to assistance, including proper care and nutrition, and special protection from all forms of neglect, abuse, cruelty, exploitation, and other conditions prejudicial to their development;\n(c) The right of the family to a family living wage and income; and\n(d) The right of families or family associations to participate in the planning and implementation of policies and programs The State likewise guarantees universal access to medically-safe, non-abortifacient, effective, legal, affordable, and quality reproductive health care services, methods, devices, supplies which do not prevent the implantation of a fertilized ovum as determined by the Food and Drug Administration (FDA) and relevant information and education thereon according to the priority needs of women, children and other underprivileged sectors, giving preferential access to those identified through the National Household Targeting System for Poverty Reduction (NHTS-PR) and other government measures of identifying marginalization, who shall be voluntary beneficiaries of reproductive health care, services and supplies for free. ■ • The State shall eradicate discriminatory practices, laws and policies that infringe on a person’s exercise of reproductive health rights.\nThe State shall also promote openness to life; Provided, That parents bring forth to the world only those children whom they can raise in a truly humane way."}},{"id":"PH-H8806-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Guiding Principles for Implementation. – This Act declares the following as guiding principles:\n(a) The right to make free and informed decisions, which is central to the exercise of any right, shall not be subjected to any form of coercion and must be fully guaranteed by the State, like the right itself;\n(b) Respect for protection and fulfillment of reproductive health and rights which seek to promote the rights and welfare of every person particularly couples, adult individuals, women and adolescents;\n(c) Since human resource is among the principal assets of the country, effective and quality reproductive health care services must be given primacy to ensure maternal and child health, the health of the unborn, safe delivery and birth of healthy children, and sound replacement rate, in line with the State’s duty to promote the right to health, responsible parenthood, social justice and full human development;\n(d) The provision of ethical and medically safe, legal, accessible, affordable, non-abortifacient, effective and quality reproductive health care services and supplies is essential in the promotion of people’s right to health, especially those of women, the poor, and the marginalized, and shall be incorporated as a component of basic health care;\n(e) The State shall promote and provide information and access, without bias, to all methods of family planning, including effective natural and modern methods which have been proven medically safe, legal, non-abortifacient, and effective in accordance with scientific and evidence-based medical research standards such as those registered and approved by the FDA for the poor and marginalized as identified through the NHTS-PR and other government measures of identifying marginalization: Provided, That the State shall also provide funding support to promote modern natural methods of family planning, especially the Billings Ovulation Method, consistent with the needs of acceptors and their religious convictions;\n(f) The State shall promote programs that: (1) enable individuals and couples to have the number of children they desire with due consideration to the health, particularly of women, and the resources available and affordable to them and in accordance with existing laws, public morals and their religious convictions: Provided, That no one shall be deprived, for economic reasons, of the rights to have children; (2) achieve equitable allocation and utilization of resources; (3) ensure effective partnership among national government, local government units (LGUs) and the private sector in the design, implementation, coordination, integration, monitoring and evaluation of people-centered programs to enhance the quality of life and environmental protection; (4) conduct studies to analyze demographic trends including demographic dividends from sound population policies towards sustainable human development in keeping with the principles of gender equality, protection of mothers and children, born and unborn and the promotion and protection of women’s reproductive rights and health; and (5) conduct scientific studies to determine the safety and efficacy of alternative medicines and methods for reproductive health care development;\n(g) The provision of reproductive health care, information and supplies giving priority to poor beneficiaries as identified through the NHTS-PR and other government measures of identifying marginalization must be the primary responsibility of the national government consistent with its obligation to respect, protect and promote the right to health and the right to life;\n(h) The State shall respect individuals’ preferences and choice of family planning methods that are in accordance with their religious convictions and cultural beliefs, taking into consideration the State’s obligations under various human rights instruments;\n(i) Active participation by nongovernment organizations (NGOs), women’s and people’s organizations, civil society, faith-based organizations, the religious sector and communities is crucial to ensure that reproductive health and population and development policies, plans, and programs will address the priority needs of women, the poor, and the marginalized;\n(j) While this Act recognizes that abortion is illegal and punishable by law, the government shall ensure that all women needing care for post-abortive complications and all other complications arising from pregnancy, labor and delivery and related issues shall be treated and counseled in a humane, nonjudgmental and compassionate manner in accordance with law and medical ethics;\n(k) Each family shall have the right to determine its ideal family size: Provided, however, That the State shall equip each parent with the necessary information on all aspects of family life, including reproductive health and responsible parenthood, in order to make that determination;\n(l) There shall be no demographic or population targets and the mitigation, promotion and/or stabilization of the population growth rate is incidental to the advancement of reproductive health;\n(m) Gender equality and women empowerment are central elements of reproductive health and population and development;\n(n) The resources of the country must be made to serve the entire population, especially the poor, and allocations thereof must be adequate and effective: Provided, That the life of the unborn is protected;\n(o) Development is a multi-faceted process that calls for the harmonization and integration of policies, plans, programs and projects that seek to uplift the quality of life of the people, more particularly the poor, the needy and the marginalized; and\n(p) That a comprehensive reproductive health program addresses the needs of people throughout their life cycle."}},{"id":"PH-H8806-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. – For the purpose of this Act, the following terms shall be defined as follows:\n(a) Abortifacient refers to any drug or device that induces abortion or the destruction of a fetus inside the mother’s womb or the prevention of the fertilized ovum to reach and be implanted in the mother’s womb upon determination of the FDA.\n(b) Adolescent refers to young people between the ages of ten (10) to nineteen (19) years who are in transition from childhood to adulthood.\n(c) Basic Emergency Obstetric and Newborn Care (BEMONC) refers to lifesaving services for emergency maternal and newborn conditions/complications being provided by a health facility or professional to include the following services: administration of parenteral oxytocic drugs, administration of dose of parenteral anticonvulsants, administration of parenteral antibiotics, administration of maternal steroids for preterm labor, performance of assisted vaginal deliveries, removal of retained placental products, and manual removal of retained placenta. It also includes neonatal interventions which include at the minimum: newborn resuscitation, provision of warmth, and referral, blood transfusion where possible.\n(d) Comprehensive Emergency Obstetric and Newborn Care (CEMONC) refers to lifesaving services for emergency maternal and newborn conditions/complications as in Basic Emergency Obstetric and Newborn Care plus the provision of surgical delivery (caesarian section) and blood bank services, and other highly specialized obstetric interventions. It also includes emergency neonatal care which includes at the minimum: newborn resuscitation, treatment of neonatal sepsis infection, oxygen support, and antenatal administration of (maternal) steroids for threatened premature delivery.\n(e) Family planning refers to a program which enables couples and individuals to decide freely and responsibly the number and spacing of their children and to have the information and means to do so, and to have access to a full range of safe, affordable, effective, non-abortifacient modem natural and artificial methods of planning pregnancy.\n(f) Fetal and infant death review refers to a qualitative and in-depth study of the causes of fetal and infant death with the primary purpose of preventing future deaths through changes or additions to programs, plans and policies.\n(g) Gender equality refers to the principle of equality between women and men and equal rights to enjoy conditions in realizing their full human potentials to contribute to, and benefit from, the results of development, with the State recognizing that all human beings are free and equal in dignity and rights. It entails equality in opportunities, in the allocation of resources or benefits, or in access to services in furtherance of the rights to health and sustainable human development among others, without discrimination.\n(h) Gender equity refers to the policies, instruments, programs and actions that address the disadvantaged position of women in society by providing preferential treatment and affirmative action. It entails fairness and justice in the distribution of benefits and responsibilities between women and men, and often requires women-specific projects and programs to end existing inequalities. This concept recognizes that while reproductive health involves women and men, it is more critical for women’s health.\n(i) Male responsibility refers to the involvement, commitment, accountability and responsibility of males in all areas of sexual health and reproductive health, as well as the care of reproductive health concerns specific to men.\n(j) Maternal death review refers to a qualitative and in-depth study of the causes of maternal death with the primary purpose of preventing future deaths through changes or additions to programs, plans and policies.\n(k) Maternal health refers to the health of a woman of reproductive age including, but not limited to, during pregnancy, childbirth and the postpartum period.\n(l) Modern methods of family planning refers to safe, effective, non-abortifacient and legal methods, whether natural or artificial, that are registered with the FDA, to plan pregnancy.\n(m) Natural family planning refers to a variety of methods used to plan or prevent pregnancy based on identifying the woman’s fertile days.\n(n) Public health care service provider refers to: (1) public health care institution, which is duly licensed and accredited and devoted primarily to the maintenance and operation of facilities for health promotion, disease prevention, diagnosis, treatment and care of individuals suffering from illness, disease, injury, disability or deformity, or in need of obstetrical or other medical and nursing care; (2) public health care professional, who is a doctor of medicine, a nurse or a midwife; (3) public health worker engaged in the delivery of health care services; or (4) barangay health worker who has undergone training programs under any accredited government and NGO and who voluntarily renders primarily health care services in the community after having been accredited to function as such by the local health board in accordance with the guideline’s promulgated by the Department of Health (DOH).\n(o) Poor refers to members of households identified as poor through the NHTS-PR by the Department of Social Welfare and Development (DSWD) or any subsequent system used by the national government in identifying the poor.\n(p) Reproductive Health (RH) refers to the state of complete physical, mental and social well-being and not merely the absence of disease or infirmity, in all matters relating to the reproductive system and to its functions and processes. This implies that people are able to have a responsible, safe, consensual and satisfying sex life, that they have the capability to reproduce and the freedom to decide if, when, and how often to do so. This further implies that women and men attain equal relationships in matters related to sexual relations and reproduction.\n(q) Reproductive health care refers to the access to a full range of methods, facilities, services and supplies that contribute to reproductive health and well-being by addressing reproductive health-related problems. It also includes sexual health, the purpose of which is the enhancement of life and personal relations. The elements of reproductive health care include the following:\n(1) Family planning information and services which shall include as a first priority making women of reproductive age fully aware of their respective cycles to make them aware of when fertilization is highly probable, as well as highly improbable;\n(2) Maternal, infant and child health and nutrition, including breastfeeding;\n(3) Proscription of abortion and management of abortion complications;\n(4) Adolescent and youth reproductive health guidance and counseling;\n(5) Prevention, treatment and management of reproductive tract infections (RTIs), HIV and AIDS and other sexually transmittable infections (STIs);\n(6) Elimination of violence against women and children and other forms of sexual and gender-based violence;\n(7) Education and counseling on sexuality and reproductive health;\n(8) Treatment of breast and reproductive tract cancers and other gynecological conditions and disorders;\n(9) Male responsibility and involvement and men’s reproductive health;\n(10) Prevention, treatment and management of infertility and sexual dysfunction;\n(11) Reproductive health education for the adolescents; and\n(12) Mental health aspect of reproductive health care.\n(r) Reproductive health care program refers to the systematic and integrated provision of reproductive health care to all citizens prioritizing women, the poor, marginalized and those invulnerable or crisis situations.\n(s) Reproductive health rights refers to the rights of individuals and couples, to decide freely and responsibly whether or not to have children; the number, spacing and timing of their children; to make other decisions concerning reproduction, free of discrimination, coercion and violence; to have the information and means to do so; and to attain the highest standard of sexual health and reproductive health: Provided, however, That reproductive health rights do not include abortion, and access to abortifacients.\n(t) Reproductive health and sexuality education refers to a lifelong learning process of providing and acquiring complete, accurate and relevant age- and development-appropriate information and education on reproductive health and sexuality through life skills education and other approaches.\n(u) Reproductive Tract Infection (RTI) refers to sexually transmitted infections (STIs), and other types of infections affecting the reproductive system.\n(v) Responsible parenthood refers to the will and ability of a parent to respond to the needs and aspirations of the family and children. It is likewise a shared responsibility between parents to determine and achieve the desired number of children, spacing and timing of their children according to their own family life aspirations, taking into account psychological preparedness, health status, sociocultural and economic concerns consistent with their religious convictions.\n(w) Sexual health refers to a state of physical, mental and social well-being in relation to sexuality. It requires a positive and respectful approach to sexuality and sexual relationships, as well as the possibility of having pleasurable and safe sexual experiences, free from coercion, discrimination and violence.\n(x) Sexually Transmitted Infection (STI) refers to any infection that may be acquired or passed on through sexual contact, use of IV, intravenous drug needles, childbirth and breastfeeding.\n(y) Skilled birth attendance refers to childbirth managed by a skilled health professional including the enabling conditions of necessary equipment and support of a functioning health system, including transport and referral faculties for emergency obstetric care.\n(z) Skilled health professional refers to a midwife, doctor or nurse, who has been educated and trained in the skills needed to manage normal and complicated pregnancies, childbirth and the immediate postnatal period, and in the identification, management and referral of complications in women and newborns.\n(aa) Sustainable human development refers to bringing people, particularly the poor and vulnerable, to the center of development process, the central purpose of which is the creation of an enabling environment in which all can enjoy long, healthy and productive lives, done in the manner that promotes their rights and protects the life opportunities of future generations and the natural ecosystem on which all life depends."}},{"id":"PH-H8806-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Hiring of Skilled Health Professionals for Maternal Health Care and Skilled Birth Attendance. – The LGUs shall endeavor to hire an adequate number of nurses, midwives and other skilled health professionals for maternal health care and skilled birth attendance to achieve an ideal skilled health professional-to-patient ratio taking into consideration DOH targets: Provided, That people in geographically isolated or highly populated and depressed areas shall be provided the same level of access to health care: Provided, further, That the national government shall provide additional and necessary funding and other necessary assistance for the effective implementation of this provision.\nFor the purposes of this Act, midwives and nurses shall be allowed to administer lifesaving drugs such as, but not limited to, oxytocin and magnesium sulfate, in accordance with the guidelines set by the DOH, under emergency conditions and when there are no physicians available: Provided, That they are properly trained and certified to administer these lifesaving drugs."}},{"id":"PH-H8806-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Health Care Facilities. – Each LGU, upon its determination of the necessity based on well-supported data provided by its local health office shall endeavor to establish or upgrade hospitals and facilities with adequate and qualified personnel, equipment and supplies to be able to provide emergency obstetric and newborn care: Provided, That people in geographically isolated or highly populated and depressed areas shall have the same level of access and shall not be neglected by providing other means such as home visits or mobile health care clinics as needed: Provided, further, That the national government shall provide additional and necessary funding and other necessary assistance for the effective implementation of this provision."}},{"id":"PH-H8806-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Access to Family Planning. – All accredited public health facilities shall provide a full range of modern family planning methods, which shall also include medical consultations, supplies and necessary and reasonable procedures for poor and marginalized couples having infertility issues who desire to have children: Provided, That family planning services shall likewise be extended by private health facilities to paying patients with the option to grant free care and services to indigents, except in the case of non-maternity specialty hospitals and hospitals owned and operated by a religious group, but they have the option to provide such full range of modern family planning methods: Provided, further, That these hospitals shall immediately refer the person seeking such care and services to another health facility which is conveniently accessible: Provided, finally, That the person is not in an emergency condition or serious case as defined in Republic Act No. 8344.\nNo person shall be denied information and access to family planning services, whether natural or artificial: Provided, That minors will not be allowed access to modern methods of family planning without written consent from their parents or guardian/s except when the minor is already a parent or has had a miscarriage."}},{"id":"PH-H8806-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Maternal Death Review and Fetal and Infant Death Review. – All LGUs, national and local government hospitals, and other public health units shall conduct an annual Maternal Death Review and Fetal and Infant Death Review in accordance with the guidelines set by the DOH. Such review should result in an evidence-based programming and budgeting process that would contribute to the development of more responsive reproductive health services to promote women’s health and safe motherhood."}},{"id":"PH-H8806-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Philippine National Drug Formulary System and Family Planning Supplies. – The National Drug Formulary shall include hormonal contraceptives, intrauterine devices, injectables and other safe, legal, non-abortifacient and effective family planning products and supplies. The Philippine National Drug Formulary System (PNDFS) shall be observed in selecting drugs including family planning supplies that will be included or removed from the Essential Drugs List (EDL) in accordance with existing practice and in consultation with reputable medical associations in the Philippines. For the purpose of this Act, any product or supply included or to be included in the EDL must have a certification from the FDA that said product and supply is made available on the condition that it is not to be used as an abortifacient.\nThese products and supplies shall also be included in the regular purchase of essential medicines and supplies of all national hospitals: Provided, further, That the foregoing offices shall not purchase or acquire by any means emergency contraceptive pills, postcoital pills, abortifacients that will be used for such purpose and their other forms or equivalent."}},{"id":"PH-H8806-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Procurement and Distribution of Family Planning Supplies. – The DOH shall procure, distribute to LGUs and monitor the usage of family planning supplies for the whole country. The DOH shall coordinate with all appropriate local government bodies to plan and implement this procurement and distribution program. The supply and budget allotments shall be based on, among others, the current levels and projections of the following:\n(a) Number of women of reproductive age and couples who want to space or limit their children;\n(b) Contraceptive prevalence rate, by type of method used; and\n(c) Cost of family planning supplies.\nProvided, That LGUs may implement its own procurement, distribution and monitoring program consistent with the overall provisions of this Act and the guidelines of the DOH."}},{"id":"PH-H8806-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Integration of Responsible Parenthood and Family Planning Component in Anti-Poverty Programs. – A multidimensional approach shall be adopted in the implementation of policies and programs to fight poverty. Towards this end, the DOH shall implement programs prioritizing full access of poor and marginalized women as identified through the NHTS-PR and other government measures of identifying marginalization to reproductive health care, services, products and programs. The DOH shall provide such programs, technical support, including capacity building and monitoring."}},{"id":"PH-H8806-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"PhilHealth Benefits for Serious and Life-Threatening Reproductive Health Conditions. – All serious and life-threatening reproductive health conditions such as HIV and AIDS, breast and reproductive tract cancers, and obstetric complications, and menopausal and post-menopausal-related conditions shall be given the maximum benefits, including the provision of Anti-Retroviral Medicines (ARVs), as provided in the guidelines set by the Philippine Health Insurance Corporation (PHIC)."}},{"id":"PH-H8806-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Mobile Health Care Service. – The national or the local government may provide each provincial, city, municipal and district hospital with a Mobile Health Care Service (MHCS) in the form of a van or other means of transportation appropriate to its terrain, taking into consideration the health care needs of each LGU. The MHCS shall deliver health care goods and services to its constituents, more particularly to the poor and needy, as well as disseminate knowledge and information on reproductive health. The MHCS shall be operated by skilled health providers and adequately equipped with a wide range of health care materials and information dissemination devices and equipment, the latter including, but not limited to, a television set for audio-visual presentations. All MHCS shall be operated by LGUs of provinces and highly urbanized cities."}},{"id":"PH-H8806-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Age- and Development-Appropriate Reproductive Health Education. – The State shall provide age- and development-appropriate reproductive health education to adolescents which shall be taught by adequately trained teachers informal and nonformal educational system and integrated in relevant subjects such as, but not limited to, values formation; knowledge and skills in self-protection against discrimination; sexual abuse and violence against women and children and other forms of gender based violence and teen pregnancy; physical, social and emotional changes in adolescents; women’s rights and children’s rights; responsible teenage behavior; gender and development; and responsible parenthood: Provided, That flexibility in the formulation and adoption of appropriate course content, scope and methodology in each educational level or group shall be allowed only after consultations with parents-teachers-community associations, school officials and other interest groups. The Department of Education (DepED) shall formulate a curriculum which shall be used by public schools and may be adopted by private schools."}},{"id":"PH-H8806-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Certificate of Compliance. – No marriage license shall be issued by the Local Civil Registrar unless the applicants present a Certificate of Compliance issued for free by the local Family Planning Office certifying that they had duly received adequate instructions and information on responsible parenthood, family planning, breastfeeding and infant nutrition."}},{"id":"PH-H8806-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Capacity Building of Barangay Health Workers (BHWs). – The DOH shall be responsible for disseminating information and providing training programs to the LGUs. The LGUs, with the technical assistance of the DOH, shall be responsible for the training of BHWs and other barangay volunteers on the promotion of reproductive health. The DOH shall provide the LGUs with medical supplies and equipment needed by BHWs to carry out their functions effectively: Provided, further, That the national government shall provide additional and necessary funding and other necessary assistance for the effective implementation of this provision including the possible provision of additional honoraria for BHWs."}},{"id":"PH-H8806-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Pro Bono Services for Indigent Women. – Private and nongovernment reproductive healthcare service providers including, but not limited to, gynecologists and obstetricians, are encouraged to provide at least forty-eight (48) hours annually of reproductive health services, ranging from providing information and education to rendering medical services, free of charge to indigent and low-income patients as identified through the NHTS-PR and other government measures of identifying marginalization, especially to pregnant adolescents. The forty-eight (48) hours annual pro bono services shall be included as a prerequisite in the accreditation under the PhilHealth."}},{"id":"PH-H8806-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Sexual and Reproductive Health Programs for Persons with Disabilities (PWDs). – The cities and municipalities shall endeavor that barriers to reproductive health services for PWDs are obliterated by the following:\n(a) Providing physical access, and resolving transportation and proximity issues to clinics, hospitals and places where public health education is provided, contraceptives are sold or distributed or other places where reproductive health services are provided;\n(b) Adapting examination tables and other laboratory procedures to the needs and conditions of PWDs;\n(c) Increasing access to information and communication materials on sexual and reproductive health in braille, large print, simple language, sign language and pictures;\n(d) Providing continuing education and inclusion of rights of PWDs among health care providers; and\n(e) Undertaking activities to raise awareness and address misconceptions among the general public on the stigma and their lack of knowledge on the sexual and reproductive health needs and rights of PWDs."}},{"id":"PH-H8806-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Duties and Responsibilities. – (a) Pursuant to the herein declared policy, the DOH shall serve as the lead agency for the implementation of this Act and shall integrate in their regular operations the following functions:\n(1) Fully and efficiently implement the reproductive health care program;\n(2) Ensure people’s access to medically safe, non-abortifacient, legal, quality and affordable reproductive health goods and services; and\n(3) Perform such other functions necessary to attain the purposes of this Act.\n(b) The DOH, in coordination with the PHIC, as may be applicable, shall:\n(1) Strengthen the capacities of health regulatory agencies to ensure safe, high quality, accessible and affordable reproductive health services and commodities with the concurrent strengthening and enforcement of regulatory mandates and mechanisms;\n(2) Facilitate the involvement and participation of NGOs and the private sector in reproductive health care service delivery and in the production, distribution and delivery of quality reproductive health and family planning supplies and commodities to make them accessible and affordable to ordinary citizens;\n(3) Engage the services, skills and proficiencies of experts in natural family planning who shall provide the necessary training for all BHWs;\n(4) Supervise and provide assistance to LGUs in the delivery of reproductive health care services and in the purchase of family planning goods and supplies; and\n(5) Furnish LGUs, through their respective local health offices, appropriate information and resources to keep the latter updated on current studies and researches relating to family planning, responsible parenthood, breastfeeding and infant nutrition.\n(c) The FDA shall issue strict guidelines with respect to the use of contraceptives, taking into consideration the side effects or other harmful effects of their use.\n(d) Corporate citizens shall exercise prudence in advertising its products or services through all forms of media, especially on matters relating to sexuality, further taking into consideration its influence on children and the youth."}},{"id":"PH-H8806-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Public Awareness. – The DOH and the LGUs shall initiate and sustain a heightened nationwide multimedia-campaign to raise the level of public awareness on the protection and promotion of reproductive health and rights including, but not limited to, maternal health and nutrition, family planning and responsible parenthood information and services, adolescent and youth reproductive health, guidance and counseling and other elements of reproductive health care under Section 4(q).\nEducation and information materials to be developed and disseminated for this purpose shall be reviewed regularly to ensure their effectiveness and relevance."}},{"id":"PH-H8806-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Reporting Requirements. – Before the end of April each year, the DOH shall submit to the President of the Philippines and Congress an annual consolidated report, which shall provide a definitive and comprehensive assessment of the implementation of its programs and those of other government agencies and instrumentalities and recommend priorities for executive and legislative actions. The report shall be printed and distributed to all national agencies, the LGUs, NGOs and private sector organizations involved in said programs.\nThe annual report shall evaluate the content, implementation, and impact of all policies related to reproductive health and family planning to ensure that such policies promote, protect and fulfill women’s reproductive health and rights."}},{"id":"PH-H8806-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Congressional Oversight Committee on Reproductive Health Act. – There is hereby created a Congressional Oversight Committee (COC) composed of five (5) members each from the Senate and the House of Representatives. The members from the Senate and the House of Representatives shall be appointed by the Senate President and the Speaker, respectively, with at least one (1) member representing the Minority.\nThe COC shall be headed by the respective Chairs of the Committee on Health and Demography of the Senate and the Committee on Population and Family Relations of the House of Representatives. The Secretariat of the COC shall come from the existing Secretariat personnel of the Senate and the House of Representatives committees concerned.\nThe COC shall monitor and ensure the effective implementation of this Act, recommend the necessary remedial legislation or administrative measures, and shall conduct a review of this Act every five (5) years from its effectivity. The COC shall perform such other duties and functions as may be necessary to attain the objectives of tins Act."}},{"id":"PH-H8806-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Prohibited Acts. – The following acts are prohibited:\n(a) Any health care service provider, whether public or private, who shall:\n(1) Knowingly withhold information or restrict the dissemination thereof, and/or intentionally provide incorrect information regarding programs and services on reproductive health including the right to informed choice and access to a full range of legal, medically-safe, non-abortifacient and effective family planning methods;\n(2) Refuse to perform legal and medically-safe reproductive health procedures on any person of legal age on the ground of lack of consent or authorization of the following persons in the following instances:\n(i) Spousal consent in case of married persons: Provided, That in case of disagreement, the decision of the one undergoing the procedure shall prevail; and\n(ii) Parental consent or that of the person exercising parental authority in the case of abused minors, where the parent or the person exercising parental authority is the respondent, accused or convicted perpetrator as certified by the proper prosecutorial office of the court. In the case of minors, the written consent of parents or legal guardian or, in their absence, persons exercising parental authority or next-of-kin shall be required only in elective surgical procedures and in no case shall consent be required in emergency or serious cases as defined in Republic Act No. 8344; and\n(3) Refuse to extend quality health care services and information on account of the person’s marital status, gender, age, religious convictions, personal circumstances, or nature of work: Provided, That the conscientious objection of a health care service provider based on his/her ethical or religious beliefs shall be respected; however, the conscientious objector shall immediately refer the person seeking such care and services to another health care service provider within the same facility or one which is conveniently accessible: Provided, further, That the person is not in an emergency condition or serious case as defined in Republic Act No. 8344, which penalizes the refusal of hospitals and medical clinics to administer appropriate initial medical treatment and support in emergency and serious cases;\n(b) Any public officer, elected or appointed, specifically charged with the duty to implement the provisions hereof, who, personally or through a subordinate, prohibits or restricts the delivery of legal and medically-safe reproductive health care services, including family planning; or forces, coerces or induces any person to use such services; or refuses to allocate, approve or release any budget for reproductive health care services, or to support reproductive health programs; or shall do any act that hinders the full implementation of a reproductive health program as mandated by this Act;\n(c) Any employer who shall suggest, require, unduly influence or cause any applicant for employment or an employee to submit himself/herself to sterilization, use any modern methods of family planning, or not use such methods as a condition for employment, continued employment, promotion or the provision of employment benefits. Further, pregnancy or the number of children shall not be a ground for non-hiring or termination from employment;\n(d) Any person who shall falsify a Certificate of Compliance as required in Section 15 of this Act; and\n(e) Any pharmaceutical company, whether domestic or multinational, or its agents or distributors, which directly or indirectly colludes with government officials, whether appointed or elected, in the distribution, procurement and/or sale by the national government and LGUs of modern family planning supplies, products and devices."}},{"id":"PH-H8806-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Penalties. – Any violation of this Act or commission of the foregoing prohibited acts shall be penalized by imprisonment ranging from one (1) month to six (6) months or a fine of Ten thousand pesos (P10,000.00) to One hundred thousand pesos (P100,000.00), or both such fine and imprisonment at the discretion of the competent court: Provided, That, if the offender is a public officer, elected or appointed, he/she shall also suffer the penalty of suspension not exceeding one (1) year or removal and forfeiture of retirement benefits depending on the gravity of the offense after due notice and hearing by the appropriate body or agency.\nIf the offender is a juridical person, the penalty shall be imposed upon the president or any responsible officer. An offender who is an alien shall, after service of sentence, be deported immediately without further proceedings by the Bureau of Immigration. If the offender is a pharmaceutical company, its agent and/or distributor, their license or permit to operate or conduct business in the Philippines shall be perpetually revoked, and a fine triple the amount involved in the violation shall be imposed."}},{"id":"PH-H8806-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Appropriations. – The amounts appropriated in the current annual General Appropriations Act (GAA) for reproductive health and natural and artificial family planning and responsible parenthood under the DOH and other concerned agencies shall be allocated and utilized for the implementation of this Act. Such additional sums necessary to provide for the upgrading of faculties necessary to meet BEMONC and CEMONC standards; the training and deployment of skilled health providers; natural and artificial family planning commodity requirements as outlined in Section 10, and for other reproductive health and responsible parenthood services, shall be included in the subsequent years’ general appropriations. The Gender and Development (GAD) funds of LGUs and national agencies may be a source of funding for the implementation of this Act."}},{"id":"PH-H8806-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Implementing Rules and Regulations (IRR). – Within sixty (60) days from the effectivity of this Act, the DOH Secretary or his/her designated representative as Chairperson, the authorized representative/s of DepED, DSWD, Philippine Commission on Women, PHIC, Department of the Interior and Local Government, National Economic and Development Authority, League of Provinces, League of Cities, and League of Municipalities, together with NGOs, faith-based organizations, people’s, women’s and young people’s organizations, shall jointly promulgate the rules and regulations for the effective implementation of this Act. At least four (4) members of the IRR drafting committee, to be selected by the DOH Secretary, shall come from NGOs."}},{"id":"PH-H8806-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Interpretation Clause. – This Act shall be liberally construed to ensure the provision, delivery and access to reproductive health care services, and to promote, protect and fulfill women’s reproductive health and rights."}},{"id":"PH-H8806-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Separability Clause. – If any part or provision of this Act is held invalid or unconstitutional, the other provisions not affected thereby shall remain in force and effect."}},{"id":"PH-H8806-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Repealing Clause. – Except for prevailing laws against abortion, any law, presidential decree or issuance, executive order, letter of instruction, administrative order, rule or regulation contrary to or is inconsistent with the provisions of this Act including Republic Act No. 7392, otherwise known as the Midwifery Act, is hereby repealed, modified or amended accordingly."}},{"id":"PH-H8806-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for a National Policy on Responsible Parenthood and Reproductive Health The Responsible Parenthood and Reproductive Health Act of 2012","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8807"] = {"id":"PH-H8807","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10355_2013.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将邦板牙 San Fernando 市 Jose B. Lingad 纪念综合医院床位由两百五十（250）张增至五百（500）张、提升其服务设施、授权增加医务人员并拨款","en":"An Act Increasing the Bed Capacity of Jose B. Lingad Memorial General Hospital in San Fernando City, Pampanga From Two Hundred Fifty (250) to Five Hundred (500), Upgrading its Services and Facilities and Professional Health Care, Authorizing the Increase of its Medical Personnel and Appropriating Funds Therefore","orig":"An Act Increasing the Bed Capacity of Jose B. Lingad Memorial General Hospital in San Fernando City, Pampanga From Two Hundred Fifty (250) to Five Hundred (500), Upgrading its Services and Facilities and Professional Health Care, Authorizing the Increase of its Medical Personnel and Appropriating Funds Therefore","vi":"Đạo luật tăng sức chứa giường bệnh của Bệnh viện Đa khoa Tưởng niệm Jose B. Lingad tại Tỉnh Pampanga từ 250 lên 500 giường, và phân bổ kinh phí","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของโรงพยาบาลทั่วไปอนุสรณ์ Jose B. Lingad ในจังหวัด Pampanga จาก 250 เป็น 500 เตียง และจัดสรรงบประมาณ","id":"Undang-Undang meningkatkan kapasitas tempat tidur Rumah Sakit Umum Memorial Jose B. Lingad di Provinsi Pampanga dari 250 menjadi 500 tempat tidur, dan mengalokasikan dana","ms":"Akta meningkatkan kapasiti katil Hospital Besar Memorial Jose B. Lingad di Wilayah Pampanga daripada 250 kepada 500 katil, serta memperuntukkan dana"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10355","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10355_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8807-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The authorized bed capacity of the Jose B. Lingad Memorial General Hospital (JBLMGH) in San Fernando City, Pampanga is hereby upgraded from two hundred fifty (250) to five hundred (500) beds."}},{"id":"PH-H8807-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The existing service facilities and professional health care services of the JBLMGH are hereby upgraded to conform with and be commensurate to the bed capacity increase as provided for in Section 1 hereof."}},{"id":"PH-H8807-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The existing workforce of the JBLMGH shall also be correspondingly increased. The Department of Health, in coordination with the Department of Budget and Management and the Civil Service Commission, shall determine the additional plantilla positions to be created and filled up upon prior consultation with the JBLMGH."}},{"id":"PH-H8807-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The increase in bed capacity of the JBLMGH from two hundred fifty (250) to five hundred (500) beds shall be implemented for a period of not more than four (4) years from the approval of this Act."}},{"id":"PH-H8807-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Health shall immediately include in the Departments program the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8807-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of Jose B. Lingad Memorial General Hospital in San Fernando City, Pampanga From Two Hundred Fifty (250) to Five Hundred (500), Upgrading its Services and Facilities and Professional Health Care, Authorizing the Increase of its Medical Personnel and Appropriating Funds Therefore","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8808"] = {"id":"PH-H8808","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10356_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"依据本法授予Jessie Josephine Coe Lichauco菲律宾公民身份、使其归化为菲律宾公民并享有公民权利的法案","en":"An Act Granting Philippine Citizenship to Jessie Josephine Coe Lichauco","orig":"An Act Granting Philippine Citizenship to Jessie Josephine Coe Lichauco","vi":"Đạo luật trao quốc tịch Philippines cho Jessie Josephine Coe Lichauco","th":"พระราชบัญญัติให้สัญชาติฟิลิปปินส์แก่ Jessie Josephine Coe Lichauco","id":"Undang-Undang memberikan kewarganegaraan Filipina kepada Jessie Josephine Coe Lichauco","ms":"Akta memberikan kewarganegaraan Filipina kepada Jessie Josephine Coe Lichauco"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 10356","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10356_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8808-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Jessie Josephine Coe Lichauco is hereby granted Philippine citizenship with all the rights, privileges, duties and obligations appurtenant thereto and with the same effects and subject to the same conditions as provided under the Constitution."}},{"id":"PH-H8808-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the taking of the oath of allegiance to the Republic of the Philippines before the Bureau of Immigration and the issuance to him of the Certificate of Naturalization Jessie Josephine Coe Lichauco shall enter upon the full enjoyment of Philippine citizenship."}},{"id":"PH-H8808-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect after fifteen (15) days from its complete publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philippine Citizenship to Jessie Josephine Coe Lichauco","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8809"] = {"id":"PH-H8809","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10357_2013.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"那牙市宪章日","en":"Charter Day of the City of Naga","orig":"An Act Declaring September 5 of Every Year a Special Working Public Holiday in the City of Naga Province of Cebu to be Known as the \"Charter Day of the City of Naga\"","vi":"Ngày Hiến chương Thành phố Naga","th":"วันก่อตั้งตามกฎบัตรของเมือง Naga","id":"Hari Piagam Kota Naga","ms":"Hari Piagam Bandaraya Naga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10357","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10357_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8809-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September 5 of every year is hereby declared to be a special working public holiday in the City of Naga, Province of Cebu to commemorate its founding day and to be known as the \"Charter Day of the City of Naga\"."}},{"id":"PH-H8809-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Charter Day of the City of Naga","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8810"] = {"id":"PH-H8810","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10358_2013.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Carcar市","en":"City of Carcar Charter Day","orig":"An Act Declaring July 7 of Every Year a Special Working Public Holiday in the City of Carcar, Province of Cebu to be Known as the \"City of Carcar Charter Day\"","vi":"Ngày Hiến chương Thành phố Carcar","th":"วันก่อตั้งตามกฎบัตรของเมือง Carcar","id":"Hari Piagam Kota Carcar","ms":"Hari Piagam Bandaraya Carcar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10358","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10358_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8810-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July 7 of every year is hereby declared to be a special working public holiday in the City of Carcar, Province of Cebu to commemorate its founding day and to be known as the \"City of Carcar Charter Day\"."}},{"id":"PH-H8810-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125"};
  FT["PH-H8811"] = {"id":"PH-H8811","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10359_2013.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布每年 3 月 26 日为宿务省特别工作公共假日的法案","en":"An Act Declaring March 26 of Every Year as a Special Working Public Holiday in the Province of Cebu to Commemorate the Historic Liberation of Cebu From the Japanese Occupation During World War II","orig":"An Act Declaring March 26 of Every Year as a Special Working Public Holiday in the Province of Cebu to Commemorate the Historic Liberation of Cebu From the Japanese Occupation During World War II"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10359","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10359_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8811-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"March 26 of every year is hereby declared as a special working public holiday not only in the City of Talisay, by virtue of Republic Act No. 7280, but also in the entire Province of Cebu to commemorate the historic liberation of Cebu from the Japanese occupation during World War II."}},{"id":"PH-H8811-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in at least one (1) national newspaper of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring March 26 of Every Year as a Special Working Public Holiday in the Province of Cebu to Commemorate the Historic Liberation of Cebu From the Japanese Occupation During World War II","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8812"] = {"id":"PH-H8812","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10360_2013.html","fetchedAt":"2026-10-06","articleCount":54,"structureMode":"ARTICLE","title":{"zh":"设立西达沃省法案","en":"An Act Creating the Province of Davao Occidental","orig":"An Act Creating the Province of Davao Occidental","vi":"Đạo luật thành lập Tỉnh Davao Occidental","th":"พระราชบัญญัติจัดตั้งจังหวัด Davao Occidental","id":"Undang-Undang membentuk Provinsi Davao Occidental","ms":"Akta mewujudkan Wilayah Davao Occidental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10360","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-09","completenessNote":"全文，共 54 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10360_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8812-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \"Charter of the Province of Davao Occidental\"."}},{"id":"PH-H8812-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Province of Davao Occidental. – There is hereby created a new province from the present Province of Davao del Sur to be known as the Province of Davao Occidental, consisting of the municipalities of Sta. Maria, Malita, Don Marcelino, Jose Abad Santos and Sarangani. The territorial jurisdiction of the Province of Davao Occidental shall be within the present metes and bounds of all the municipalities that comprise the Province of Davao Occidental.\nThe foregoing provision shall be without prejudice to the resolution by the appropriate agency or forum of existing boundary disputes or cases involving questions of territorial jurisdiction between the Province of Davao Occidental and adjoining local government units (LGUs): Provided, That the territorial jurisdiction of the disputed area or areas shall remain with the LGU, which has existing administrative supervision over said area or areas until final resolution of the case."}},{"id":"PH-H8812-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Capital Town and Seat of Government. – The capital town and seat of government of the new Province of Davao Occidental shall be the Municipality of Malita."}},{"id":"PH-H8812-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Corporate Powers of the Province. – The province constitutes a political body corporate and as such is endowed with the attributes of perpetual succession and possessed of the powers which pertain to a provincial corporation to be exercised in conformity with the provision of this Charter and the 1991 Local Government Code, as amended. The province shall have the following corporate powers:\n(a) To have a continuous succession in its corporate name;\n(b) To sue and be sued;\n(c) To have and use a corporate seal;\n(d) To acquire, hold and convey real or personal property;\n(e) To enter into contracts and/or agreements; and\n(f) To exercise such other powers, prerogatives or authority subject to the limitations provided in this Act or other laws."}},{"id":"PH-H8812-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"General Powers. – The province shall have a common seal and may alter the same at its pleasure: Provided, That any change of corporate seal shall be registered with the Department of the Interior and Local Government (DILG). It shall have the power to create its sources of revenue and to levy taxes, fees and charges; to close and open roads, streets, alleys, parks or squares; to take, purchase, receive, hold, lease, convey and dispose of real and personal property for the general interests of the province; to expropriate or condemn private property for public use; to contract and to be contracted with; to sue and be sued; to prosecute and defend to final judgment and execution suits wherein the province is involved or interested in and to exercise all the powers as are granted to corporations or as hereinafter granted, subject to the provisions of the 1991 Local Government Code, as amended."}},{"id":"PH-H8812-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Liability for Damages. – The province and its officials shall not be exempt from liability for death or injury to persons or damage to property."}},{"id":"PH-H8812-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Legislative District. – The Province of Davao Occidental shall have its own legislative district to commence in the next national and local elections after the effectivity of this Charter. Henceforth, the municipalities of Sta. Maria, Malita, Don Marcelino, Jose Abad Santos and Sarangani shall comprise the Lone Legislative District of the Province of Davao Occidental while the City of Digos and the municipalities of Malalag, Sulop, Kiblawan, Padada, Hagonoy, Sta. Cruz, Matanao, Bansalan and Magsaysay shall comprise the Lone Legislative District of the Province of Davao del Sur.\nThe incumbent Representatives of the present Province of Davao del Sur shall continue to represent their respective legislative districts until the expiration of their term of office.\nPROVINCIAL OFFICIALS IN GENERAL"}},{"id":"PH-H8812-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Officials of the Provincial Government. –\n(a) There shall be in the Province of Davao Occidental: a provincial governor, a provincial vice governor, the regular members of the sangguniang panlalawigan, a secretary to the sangguniang panlalawigan, a provincial treasurer, a provincial assessor, a provincial accountant, a provincial budget officer, a provincial planning and development coordinator, a provincial engineer, a provincial health officer, a provincial administrator, a provincial legal officer, a provincial agriculturist, a provincial social welfare and development officer, a provincial veterinarian and a provincial general services officer.\n(b) In addition thereto, the provincial governor may appoint a provincial architect, a provincial population officer, a provincial environment and natural resources officer, a provincial cooperatives officer and a provincial information officer.\n(c) The sangguniang panlalawigan may:\n(1) Maintain existing offices mentioned in subsections (a) and (b) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the provincial government; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy.\nUnless otherwise provided herein or in the 1991 Local Government Code, as amended, the heads of departments and offices shall be appointed by the provincial governor with the concurrence of a majority of all the sangguniang panlalawigan members, subject to civil service law, rules and regulations. The sangguniang panlalawigan shall act on the appointment within fifteen (15) days from the day of its submission; otherwise, the same shall be deemed confirmed."}},{"id":"PH-H8812-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Residence and Office. – During the incumbency of the provincial governor, he or she shall have his or her official residence and office in the capital of the province. All elective and appointive provincial officials shall hold office in the provincial capital: Provided, That, upon the resolution of the sangguniang panlalawigan, elective and appointive provincial officials may hold office in any component city or municipality within the province for a period of not more than seven (7) days for any given month.\nElective and appointive provincial officials shall receive such compensation, allowances and other emoluments as may be determined by law or ordinance, subject to the budgetary limitations on personal services prescribed under Title V, Book II of the Local Government Code of 1991, as amended: Provided, That, no increase in compensation shall take effect until after the expiration of the full term of all the elective officials approving such increase.\nELECTIVE PROVINCIAL OFFICIALS"}},{"id":"PH-H8812-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Provincial Governor. – (a) The provincial governor, as the chief executive of the provincial government, shall exercise such powers and perform such duties and functions as provided for in the Local Government Code of 1991, as amended, and other laws.\n(b) For efficient, effective and economical governance, the purpose of which is the general welfare of the province and its inhabitants pursuant to Section 16 of the Local Government Code of 1991, as amended, the provincial governor shall:\n(1) Exercise general supervision and control over all programs, projects, services and activities of the provincial government and, in this connection, shall:\n(i) Determine the guidelines of provincial policies and be responsible to the sangguniang panlalawigan for the program of the government;\n(ii) Direct the formulation of the provincial development plan, with the assistance of the provincial development council and upon approval thereof by the sangguniang panlalawigan, implement the same;\n(iii) Present the program of government and propose policies and projects for the consideration of the sangguniang panlalawigan at the opening of the regular session of the sangguniang panlalawigan every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the provincial government may require;\n(iv) Initiate and propose legislative measures to the sangguniang panlalawigan and as often as may be deemed necessary, provide such information and data needed or requested by said sangguniang panlalawigan in the performance of its legislative functions;\n(v) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of provincial funds and whose appointments are not otherwise provided for in this Act as well as those he or she may be authorized by law to appoint;\n(vi) Represent the province in all its business transactions and sign in its behalf all bonds, contracts and obligations, and such other documents upon the authority of the sangguniang panlalawigan or pursuant to law or ordinance;\n(vii) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(viii) Determine the time, manner and place of payment of salaries or wages of the provincial officials and employees, in accordance with law or ordinance;\n(ix) Allocate and assign office space to the provincial and other officials and employees who, by law or ordinance, are entitled to such space in the provincial capitol and other buildings owned or leased by the provincial government;\n(x) Ensure that all executive officials and employees of the province faithfully discharge their duties and functions as provided for by law and the Local Government Code of 1991, as amended, and cause to be instituted administrative or judicial proceedings against any official or employee of the province who may have committed an offense in the performance of his or her official duties;\n(xi) Examine the books, records and other documents of all offices, officials, agents or employees of the province and, in aid of his or her executive powers and authority, require all national officials and employees stationed in the province to make available to him or her such books, records and other documents in their custody, except those classified by law as confidential;\n(xii) Furnish copies of executive orders issued by him or her to the Office of the President within seventy-two (72) hours after their issuance;\n(xiii) Visit component cities and municipalities of the province at least once every six (6) months to deepen his or her understanding of problems and conditions, listen and give appropriate counsel to local officials and inhabitants, inform the officials and inhabitants of component cities and municipalities of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the province will improve the quality of life of the inhabitants;\n(xiv) Act on leave applications of officials and employees appointed by him or her and the commutation of the monetary value of their leave credits in accordance with law;\n(xv) Authorize official trips of provincial officials and employees outside of the province for a period not exceeding thirty (30) days;\n(xvi) Call upon any national official or employee stationed in or assigned to the province to advise him or her on matters affecting the province and to make recommendations thereon; coordinate with the said official or employee in the formulation and implementation of plans, programs and projects; and, when appropriate, initiate an administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his or her duties while stationed in or assigned to the province;\n(xvii) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of provincial officials and employees who are injured while in the performance of their official duties and functions, subject to the availability of funds;\n(xviii) Represent the province in inter-provincial or regional sports councils or committees, and coordinate the efforts of component cities or municipalities in the regional or national palaro or sports development activities;\n(xix) Conduct an annual palarong panlalawigan, which shall feature traditional sports and disciplines included in national and international games, in coordination with the Department of Education (DepED); and\n(xx) Submit to the Office of the President the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the province and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the province, region or country;\n(2) Enforce all laws and ordinances relative to the governance of the province and the exercise of the appropriate corporate powers provided for in Section 22 of the Local Government Code of 1991, as amended; implement all approved policies, programs, projects, services and activities of the province; and, in addition to the foregoing, shall:\n(i) Ensure that the acts of the component cities and municipalities of the province and of its officials and employees are within the scope of their prescribed powers, duties and functions;\n(ii) Call conventions, conferences, seminars or meetings of any elective and appointive officials of the province and its component cities and municipalities, including national officials and employees stationed in or assigned to the province, at such time and place and on such subject as he or she may deem important for the promotion of the general welfare of the province and its inhabitants;\n(iii) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(iv) Be entitled to carry the necessary firearm within his or her territorial jurisdiction;\n(v) In coordination with the mayors of component cities and municipalities and the National Police Commission, formulate the peace and order plan of the province and upon its approval, implement the same in accordance with Republic Act No. 6975; and\n(vi) Call upon the appropriate national law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition or to apprehend violators of the law when public interest so requires and the police forces of the component city and municipality where the disorder or violation is happening are inadequate to cope with the situation or the violators;\n(3) Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities as provided for under Section 18 of the Local Government Code of 1991, as amended, particularly those resources and revenues programmed for agro-industrial development and countrywide growth and progress and, relative thereto, shall;\n(i) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process under Title V, Book II of the Local Government Code of 1991, as amended;\n(ii) Prepare and submit to the sangguniang panlalawigan for approval the executive and supplemental budgets of the province for the ensuing calendar year in the manner provided for under Title V, Book II of the Local Government Code of 1991, as amended;\n(iii) Ensure that all taxes and other revenues of the province are collected, and that provincial funds are applied to the payment of expenses and the settlement of obligations of the province, in accordance with law or ordinance;\n(iv) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(v) Adopt adequate measures to safeguard and conserve land, mineral, marine, forest and other resources of the province, in coordination with the mayors of component cities and municipalities;\n(vi) Provide efficient and effective property and supply management in the province; and protect the funds, credits, rights and other properties of the province; and\n(vii) Institute or cause to be instituted administrative or judicial proceedings for violations of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property, and cause the province to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n(4) Ensure the delivery of basic services and the provision of adequate facilities as provided for under Section 17 of the Local Government Code of 1991, as amended and, in addition thereto, shall:\n(i) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the province and of its component cities and municipalities; and\n(ii) Coordinate the implementation of technical services by national offices for the province and its component cities and municipalities, including public works and infrastructure programs of the provincial government and its component cities and municipalities; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe provincial governor shall receive a minimum monthly compensation corresponding to Salary Grade Thirty (30) as prescribed under Republic Act No. 6758, as amended, and the implementing guidelines issued pursuant thereto."}},{"id":"PH-H8812-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The Provincial Vice Governor. – (a) The provincial vice governor shall:\n(1) Be the presiding officer of the sangguniang panlalawigan and sign all warrants drawn on the provincial treasury for all expenditures appropriated for the operation of the sangguniang panlalawigan;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang panlalawigan, except those whose manner of appointment is specifically provided for under existing laws;\n(3) Assume the office of the provincial governor for the unexpired term of the latter in the event of permanent vacancy as provided for in Section 44, Book I of the Local Government Code of 1991, as amended;\n(4) Exercise the powers and perform the duties and functions of the provincial governor in case of temporary vacancy as provided for in Section 46, Book I of the Local Government Code of 1991, as amended; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The provincial vice governor shall receive a monthly compensation corresponding to Salary Grade Twenty-eight (28) as prescribed under Republic Act No. 6758, as amended, and the implementing guidelines issued pursuant thereto.\nTHE SANGGUNIANG PANLALAWIGAN"}},{"id":"PH-H8812-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Composition. – (a) The sangguniang panlalawigan, the legislative body of the province, shall be composed of the provincial vice governor as the presiding officer, the regular sangguniang panlalawigan members, the president of the provincial chapter of the liga ng mga barangay, the president of the panlalawigang pederasyon ng mga sangguniang kabataan, the president of the provincial federation of sanggunian members of municipalities and component cities and the three (3) sectoral representatives, as members, who shall come from the following sectors: one (1) from the women sector; and, as shall be determined by the sangguniang panlalawigan within ninety (90) days prior to the holding of the local elections, one (1) from the agricultural or industrial workers sector; and one (1) from the other sectors, including the urban poor, indigenous cultural communities or persons with disability.\n(b) The regular members of the sangguniang panlalawigan and the sectoral representatives shall be elected in the manner as provided for by law, and shall receive a monthly compensation corresponding to Salary Grade Twenty-seven (27) as prescribed under Republic Act No. 6758, as amended, and the implementing guidelines issued pursuant thereto."}},{"id":"PH-H8812-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers, Duties, Functions and Compensation. – (a) The sangguniang panlalawigan, as the legislative body of the province, shall enact ordinances, approve resolutions and appropriate funds for the general welfare of the province and its inhabitants pursuant to Section 16 of the Local Government Code of 1991, as amended, and in the proper exercise of the corporate powers of the province as provided for under Section 22 of the Local Government Code of 1991, as amended, and shall:\n(1) Approve all ordinances and pass resolutions necessary for an efficient and effective provincial government and, in this connection, shall:\n(i) Review all ordinances approved by the sanggunians of component cities and municipalities and executive orders issued by the mayors of said component units to determine whether these are within the scope of the prescribed powers of the sanggunian and of the mayor;\n(ii) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(iii) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000.00) or an imprisonment not exceeding one (1) year, or both, in the discretion of the court, for the violation of a provincial ordinance;\n(iv) Adopt measures to protect the inhabitants of the province from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters and calamities and their return to productive livelihood following said events;\n(v) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, the establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publication, and such other activities inimical to the welfare and morals of the inhabitants of the province;\n(vi) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging and smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash-and-burn farming and such other activities which result in pollution, acceleration of eutrophication of rivers and lakes, or of ecological imbalance;\n(vii) Subject to the provisions of the Local Government Code of 1991, as amended, and pertinent laws, determine the powers and duties of officials and employees of the province;\n(viii) Determine the positions and salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from provincial funds and provide for expenditures necessary for the proper conduct of programs, projects, services and activities of the provincial government;\n(ix) Authorize the payment of compensation to a qualified person not in the government service who fills in a temporary vacancy or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity at the rate authorized by law;\n(x) Provide mechanism and the appropriate funds therefore to ensure the safety and protection of all provincial government property, public documents or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits and such other records and documents of public interest in the offices and departments of the provincial government; and\n(xi) When the finances of the provincial government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed or assigned to the province;\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the province as provided for under Section 18 of the Local Government Code of 1991, as amended, with particular attention to agro-industrial development and countrywide growth and progress and, relative thereto, shall:\n(i) Enact the annual and supplemental appropriations of the provincial government and appropriate funds for specific programs, projects, services and activities of the province, or for other purposes not contrary to law, in order to promote the general welfare of the province and its inhabitants;\n(ii) Subject to the provisions of Book II of the Local Government Code of 1991, as amended and applicable laws and, upon the majority vote of all the members of the sangguniang panlalawigan, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes and granting tax exemptions, incentives or reliefs;\n(iii) Subject to the provisions of Book II of the Local Government Code of 1991, as amended and applicable laws and, upon the majority vote of all the members of the sangguniang panlalawigan, authorize the provincial governor to negotiate and contract loans and other forms of indebtedness;\n(iv) Subject to the provisions of Book II of the Local Government Code of 1991, as amended and applicable laws and, upon the majority vote of all the members of the sangguniang panlalawigan, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(v) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the province and, upon the majority vote of all the members of the sangguniang panlalawigan, authorize the provincial governor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(vi) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the province;\n(vii) Review the comprehensive land use plans and zoning ordinances of component cities and municipalities and adopt a comprehensive provincial land use plan, subject to existing laws; and\n(viii) Adopt measures to enhance the full implementation of the national agrarian reform program in coordination with the Department of Agrarian Reform (DAR);\n(3) Subject to the provisions of Book II of the Local Government Code of 1991, as amended, grant franchises, approve the issuance of permits or licenses, or enact ordinances levying taxes, fees and charges upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the province and, pursuant to the legislative authority, shall:\n(i) Fix and impose reasonable fees and charges for all services rendered by the provincial government to private persons or entities; and\n(ii) Regulate and fix the license fees for such activities as provided for under the Local Government Code of 1991, as amended;\n(4) Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided in Section 17 of the Local Government Code of 1991, as amended, and, in addition to said services and facilities, shall:\n(i) Adopt measures and safeguards against pollution and for the preservation of the natural ecosystem in the province, in consonance with approved standards on human settlements and environmental sanitation;\n(ii) Subject to applicable laws, facilitate or provide for the establishment and maintenance of a waterworks system or district waterworks for supplying water to inhabitants of component cities and municipalities;\n(iii) Subject to the availability of funds and to existing laws, rules and regulations, provide for the establishment and operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the DepED and subject to existing laws on tuition fees, fix reasonable tuition fees and other school charges in educational institutions supported by the provincial government;\n(iv) Establish a scholarship fund for the poor but deserving students in schools located within its jurisdiction or of students residing within the province;\n(v) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases within its territorial jurisdiction;\n(vi) Provide for the care of paupers, the aged, the sick, persons of unsound mind, abandoned minors, abused children, disabled persons, juvenile delinquents, drug dependents, and other needy and disadvantaged persons, particularly children and youth below eighteen (18) years of age; subject to the availability of funds, establish and support the operation of centers and facilities for said needy and disadvantaged persons; and facilitate the efforts to promote the welfare of families below the poverty threshold, the disadvantaged and the exploited;\n(vii) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program and appropriate funds for the subsistence of detainees and convicted prisoners in the province;\n(viii) Establish a provincial council whose purpose is the promotion of culture and the arts, coordinate with government agencies and nongovernmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(ix) Establish a provincial council for the elderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the province; subject to the availability of funds, appropriate funds to support programs and projects for the elderly; and provide incentives for nongovernmental agencies and entities to support the programs and projects of the elderly; and\n(5) Exercise such other powers and perform such other duties and functions as provided for under the Local Government Code of 1991, as amended, and as may be prescribed by law or ordinance.\nPROCESS OF LEGISLATION"}},{"id":"PH-H8812-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Internal Rules of Procedure. – (a) On the first regular session following the election of its members and within ninety (90) days thereafter, the sangguniang panlalawigan shall adopt or update its existing rules of procedure.\n(b) The rules of procedure shall provide for the following:\n(1) The organization of the sanggunian and the election of its officers as well as the creation of standing committees which shall include, but shall not be limited to, the committees on appropriations, women and family, human rights, youth and sports development, environment protection, peace and order and traffic, and cooperatives; the general jurisdiction of each committee; and the election of the chairman and members of each committee;\n(2) The order and calendar of business for each session;\n(3) The legislative process;\n(4) The parliamentary procedures which include the conduct of members during sessions;\n(5) The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions for which they may be censured, reprimanded or excluded from the session, suspended for not more than sixty (60) days, or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) of all the sanggunian members: Provided, further, That a member convicted by final judgment to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the sanggunian; and\n(6) Such other rules as the sanggunian may adopt."}},{"id":"PH-H8812-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Full Disclosure of Financial and Business Interests of Sangguniang Panlalawigan Members. – (a) Every sangguniang panlalawigan member shall, upon assumption to office, make a full disclosure of his or her business and financial interests. He or she shall also disclose any business financial, professional relationship or any relation by affinity or consanguinity within the fourth civil degree, which he or she may have with any person, firm or entity affected by any ordinance or resolution under consideration by the sanggunian of which he or she is a member, which relationship may result in conflict of interest. Such relationship shall include:\n(1) Ownership of stocks or capital, or investment in the entity or firm to which the ordinance or resolution may apply; and\n(2) Contracts or agreement with any person or entity which the ordinance or resolution under consideration may affect.\nIn the absence of a specific constitutional or statutory provisions applicable to this situation, \"conflict of interest\" refers in general to one where it may be reasonably deduced that a member of a sangguniang panlalawigan may not act in the public interest due to some private, pecuniary or other personal considerations that may tend to affect his or her judgment to the prejudice of the service or the public.\n(b) The disclosure required under this Act shall be made in writing and submitted to the secretary of the sanggunian or the secretary of the committee of which he or she is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n(1) Disclosure shall be made before the member participates in the deliberations on the ordinance or resolution under consideration: Provided, That if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n(2) Disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection or professional relationship described herein."}},{"id":"PH-H8812-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Sessions. – (a) On the first day of session immediately following the election of its members, the sangguniang panlalawigan shall, by resolution, fix the day, time and place of its regular sessions. The minimum number of regular sessions of the sangguniang panlalawigan shall be once a week.\n(b) When the public interest so demands, special sessions may be called by the provincial governor or by a majority of the members of the sanggunian.\n(c) All sanggunian sessions shall be open to the public unless a closed-door session is ordered by an affirmative vote of a majority of the members present, there being a quorum, in the public interest or for reasons of security, decency or morality. No two (2) sessions, regular or special, may be held in a single day.\n(d) In the case of special sessions of the sanggunian, a written notice to the members shall be served personally at the members’ usual place of residence at least twenty-four (24) hours before the special session is held.\nUnless otherwise concurred in by two-thirds (2/3) vote of the sanggunian members present, there being a quorum, no other matters may be considered at a special session except those stated in the notice.\n(e) The sanggunian shall keep a journal and a record of its proceedings which may be published upon resolution of the sangguniang panlalawigan."}},{"id":"PH-H8812-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Quorum. – (a) A majority of all the members of the sanggunian who have been elected and qualified shall constitute a quorum to transact official business. Should a question of quorum be raised during the session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the results.\n(b) Where there is no quorum, the presiding officer may declare a recess until such time a quorum is constituted, or a majority of the members present may adjourn from day to day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the sanggunian, to be assisted by a member or members of the police force assigned in the territorial jurisdiction of the province, to arrest the absent member and present him or her at the session.\n(c) If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H8812-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Approval of Ordinances. – (a) Every ordinance enacted by the sangguniang panlalawigan shall be presented to the provincial governor. If the provincial governor approves the same, he or she shall affix his or her signature on each and every page thereof; otherwise, he or she shall veto it and return the same with his or her objections to the sanggunian, which may proceed to reconsider the same. The sanggunian may override the veto of the provincial governor by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\n(b) The veto shall be communicated by the provincial governor to the sangguniang panlalawigan within fifteen (15) days; otherwise, the ordinance shall be deemed approved as if he or she had signed it."}},{"id":"PH-H8812-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Veto Power of the Provincial Governor. – (a) The provincial governor may veto any ordinance of the sangguniang panlalawigan on the ground that it is prejudicial to the public welfare, stating his or her reasons thereof in writing.\n(b) The provincial governor shall have the power to veto any particular item or items of an appropriation ordinance, an ordinance or resolution adopting a local development plan and public investment program or an ordinance directing the payment of money or creating liability. In such case, the veto shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the sangguniang panlalawigan overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\n(c) The provincial governor may veto an ordinance or resolution only once. The sanggunian may override the veto of the provincial governor by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the provincial governor.\nSUCCESSION FOR ELECTIVE PROVINCIAL OFFICIALS"}},{"id":"PH-H8812-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Permanent Vacancy in the Office of the Provincial Governor. – (a) If a permanent vacancy occurs m the office of the provincial governor, the provincial vice governor shall become the provincial governor or in case of his or her permanent inability, the highest ranking sanggunian member shall become the provincial governor. If a permanent vacancy occurs in the office of the provincial vice governor, the highest ranking sangguniang panlalawigan member shall become the provincial vice governor or, in case of his or her permanent incapacity, the highest ranking sangguniang panlalawigan member shall become the provincial vice governor. Subsequent vacancies shall be filled automatically by other sanggunian members according to their ranking as defined herein:\n(1) A tie between or among the highest ranking sangguniang panlalawigan members shall be resolved by drawing of lots;\n(2) The successors as defined herein shall serve only the unexpired terms of the predecessors;\n(3) For purposes of this Act, a permanent vacancy arises when an elective official fills a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions of his or her office; and\n(4) For purposes of succession as provided for in this Act, ranking in the sangguniang panlalawigan shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in the province in the immediately preceding local elections."}},{"id":"PH-H8812-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Permanent Vacancies in the Sangguniang Panlalawigan. – (a) Permanent vacancies in the sangguniang panlalawigan where automatic succession as provided does not apply shall be filled by appointment by the President, through the Executive Secretary.\n(b) Only the nominee of the political party under which the sanggunian member concerned had been elected and whose elevation to the position next higher in rank created the last vacancy in the sanggunian shall be appointed in the manner herein provided. The appointee shall come from the same political party as that of the sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office.\nIn the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be a ground for administrative action against the official responsible therefor.\n(c) In case the permanent vacancy is caused by a sanggunian member who does not belong to any political party, the provincial governor shall, upon recommendation of the sangguniang panlalawigan, appoint a qualified person to fill in the vacancy.\n(d) In case of vacancy in the representation of the sangguniang kabataan, the sangguniang barangay and the provincial league of councilors in the sangguniang panlalawigan, said vacancy shall be filled in automatically by the official next-in-rank of the organization concerned."}},{"id":"PH-H8812-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Temporary Vacancy in the Office of the Provincial Governor. – (a) When the provincial governor is temporarily incapacitated to perform his or her duties for physical or legal reasons such as, but not limited to, leave of absence, travel abroad and suspension from office, the provincial vice governor shall automatically exercise the powers and perform the duties and functions of the provincial governor, except the power to appoint, suspend or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\n(b) Said temporary incapacity shall terminate upon submission to the sangguniang panlalawigan of a written declaration by the provincial governor that he or she has reported back to office. In case where the temporary incapacity is due to legal cause, the provincial governor shall also submit necessary documents showing that the said legal cause no longer exists.\n(c) When the provincial governor is traveling within the country but outside territorial jurisdiction for a period not exceeding three (3) consecutive days, he or she may designate in writing the officer-in-charge of his or her office. Such authorization shall specify the powers and functions that the local official concerned shall exercise in the absence of the provincial governor, except the power to appoint, suspend or dismiss employees.\n(d) In the event, however, that the provincial governor fads or refuses to issue such authorization, the provincial vice governor shall have the right to assume the powers, duties and functions of the said office on the fourth (4th) day of absence of the provincial governor, subject to the limitations provided for in subsection (c) hereof.\n(e) Except as provided above, the provincial governor shall, in no case, authorize any local official to assume the powers, duties and functions of the office other than the provincial vice governor.\nAPPOINTIVE PROVINCIAL OFFICIALS:\nTHEIR QUALIFICATIONS, POWERS AND DUTIES"}},{"id":"PH-H8812-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Secretary to the Sangguniang Panlalawigan. – (a) There shall be a secretary to the sangguniang panlalawigan who shall be a career official with the rank and salary equal to a head of a department or office.\n(b) No person shall be appointed secretary to the sanggunian unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in law, commerce or public administration from a recognized college or university, and a first grade civil service eligible or its equivalent.\n(c) The secretary to the sanggunian shall take charge of the office of the sangguniang panlalawigan, and shall:\n(1) Attend meetings of the sanggunian and keep a journal of its proceedings;\n(2) Keep the seal of the LGU and affix the same with his or her signature to all ordinances, resolutions and other official acts of the sanggunian and present the same to the presiding officer for his or her signature;\n(3) Forward to the provincial governor, for approval, copies of ordinances enacted by the sanggunian and duly certified by the presiding officer, in the manner provided for in Section 54 of the Local Government Code of 1991, as amended;\n(4) Forward to the sangguniang bayan or sangguniang panlungsod, as the case may be, copies of duly approved ordinances in the manner provided for in Sections 56 and 57 of the Local Government Code of 1991, as amended;\n(5) Furnish, upon the request of any interested party, certified copies of records of public character in his or her custody, upon payment to the treasurer of such fees as may be prescribed by ordinance;\n(6) Record in a book kept for the purpose, all ordinances and resolutions enacted or adopted by the sanggunian, with the dates of passage and publication thereof;\n(7) Keep his or her office and all nonconfidential records therein open to the public during usual business hours;\n(8) Translate into the dialect used by the majority of the inhabitants, all ordinances and resolutions immediately after their approval, and cause the publication of the same together with the original version in the manner provided for under the Local Government Code of 1991, as amended; and\n(9) Take custody of the local archives and, where applicable, the local library and annually account for the same.\n(d) Exercise such powers and perform such other duties and functions as may be prescribed by law or ordinance relative to his or her position."}},{"id":"PH-H8812-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Treasurer. – (a) The provincial treasurer shall be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the provincial governor, subject to civil service law, rules and regulations.\n(b) The provincial treasurer shall be under the administrative supervision of the provincial governor, to whom he or she shall report regularly on the tax collection efforts in the LGU.\n(c) No person shall be appointed provincial treasurer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in treasury or accounting service for at least five (5) years.\nThe appointment of the provincial treasurer shall be mandatory.\n(d) He or she shall take charge of the treasury office, and perform the duties as provided for under Book II of the Local Government Code of 1991, as amended, and shall:\n(1) Advise the provincial governor or the sanggunian, as the case may be, and other local government and national officials concerned regarding disposition of local government funds and on such other matters relative to public finance;\n(2) Take custody of and exercise proper management of the funds of the LGU concerned;\n(3) Take charge of the disbursement of all local government funds and such other funds, the custody of which may be entrusted to him or her by law or other competent authority;\n(4) Inspect private commercial and industrial establishments within the jurisdiction of the province in relation to the implementation of tax ordinances, pursuant to the provisions under Book II of the Local Government Code of 1991, as amended;\n(5) Maintain and update the tax information system of the LGU; and\n(6) Exercise technical supervision over all treasury offices of component cities and municipalities.\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Assessor. – (a) No person shall be appointed provincial assessor unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in real property assessment work or in any related field for at least five (5) years.\nThe appointment of the provincial assessor shall he mandatory.\n(b) The provincial assessor shall take charge of the assessor’s office and perform the duties as provided for under Book II of the Local Government Code of 1991, as amended, and shall:\n(1) Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purposes are properly executed;\n(2) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purposes;\n(3) Establish a systematic method of real property assessment;\n(4) Install and maintain a real property identification and accounting system;\n(5) Prepare, install and maintain a system of tax mapping, showing graphically all property subject to assessment and gather all data concerning the same;\n(6) Conduct frequent physical surveys to verify and determine whether all real properties within the province are properly listed in the assessment rolls;\n(7) Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the province;\n(8) Prepare a schedule of the fair market value for the different classes of real properties in accordance with Title 2, Book II of the Local Government Code of 1991, as amended;\n(9) Issue, upon request of any interested party, certified copies of assessment records of real properties and all other records relative to its assessment, upon payment of a service charge or fee to the provincial treasurer;\n(10) Submit every semester a report of all assessments, as well as cancellations and modifications of assessments to the provincial governor and the sangguniang panlalawigan; and\n(11) Exercise technical supervision and visitorial functions over all component city and municipal assessors, coordinate with component city or municipal assessors in the conduct of tax mapping operations and all other assessment activities, and provide all forms of assistance therefor: Provided, however, That, upon full provision by the component city or municipality concerned to its assessor’s office of the minimum personnel, equipment and funding requirements as may be prescribed by the Secretary of Finance, such functions shall be delegated to the said municipal assessor.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Accountant. – (a) No person shall be appointed provincial accountant unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a certified public accountant. He or she must have acquired experience in the treasury or accounting service for at least five (5) years.\nThe appointment of a provincial accountant is mandatory.\n(b) The provincial accountant shall take charge of both the accounting and internal audit services of the province, and shall:\n(1) Install and maintain an internal audit system in the province;\n(2) Prepare and submit financial statements to the provincial governor and to the sangguniang panlalawigan;\n(3) Apprise the sanggunian and other local government officials on the financial condition and operations of the provincial government;\n(4) Certify to the availability of budgetary allotment from which expenditures and obligations may be properly charged;\n(5) Review supporting documents before the preparation of vouchers to determine completeness of requirements;\n(6) Prepare statements of cash advances, liquidations, salaries, allowances, reimbursements and remittances pertaining to the provincial government;\n(7) Prepare statements of journal vouchers and liquidations of the same and other adjustments related thereto;\n(8) Post individual disbursements to subsidiary ledgers and index cards;\n(9) Maintain individual ledgers for officials and employees of the provincial government pertaining to payrolls and deductions;\n(10) Record and post in index cards details of purchased furniture, fixtures and equipment, including disposal thereof, if any;\n(11) Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n(12) Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n(13) Exercise such other powers and perform such other duties and functions as may be provided by law or ordinance."}},{"id":"PH-H8812-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Budget Officer. – (a) No person shall be appointed provincial budget officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in accounting, economics, public administration or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in government budgeting or in any related field for at least five (5) years.\nThe appointment of the provincial budget officer shall be mandatory.\n(b) The provincial budget officer shall take charge of the budget office, and shall:\n(1) Prepare forms, orders and circulars embodying instructions on budgetary and appropriation matters for the signature of the provincial governor;\n(2) Review and consolidate the budget proposals of different departments and offices of the province;\n(3) Assist the provincial governor in the preparation of the budget and during the budget hearings;\n(4) Study and evaluate budgetary implications of proposed legislation and submit comments and recommendations thereon;\n(5) Submit periodic budgetary reports to the Department of Budget and Management (DBM);\n(6) Coordinate with the provincial treasurer, the provincial accountant and the provincial planning and development coordinator for the purpose of budgeting;\n(7) Assist the sangguniang panlalawigan in reviewing the approved budgets of the component cities and municipalities; and\n(8) Coordinate with the provincial planning and development coordinator in the formulation of the provincial development plan.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(d) The appropriations for personal services of the budget officer shall be provided for in full in the annual budget of the provincial government."}},{"id":"PH-H8812-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Planning and Development Coordinator. – (a) No person shall be appointed provincial planning and development coordinator unless he or she is a citizen of the Philippines; a resident of the province; of good moral character; a holder of a college degree preferably in urban planning, development studies, economics, public administration or in any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in development planning or in any related field for at least five (5) years.\nThe appointment of a provincial planning and development coordinator shall be mandatory to the provincial government.\n(b) The provincial planning and development coordinator shall take charge of the planning and development office, and shall:\n(1) Formulate integrated economic, social, physical and other development plans and policies for consideration of the local government development council;\n(2) Conduct continuing studies, researches and training programs necessary to evolve plans and programs for implementation;\n(3) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups and agencies;\n(4) Monitor and evaluate the implementation of the different development programs, projects and activities in the province in accordance with the approved development plan;\n(5) Prepare comprehensive plans and other development planning documents for the consideration of the provincial development council;\n(6) Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for the consideration of the finance committee of the province as provided under Title V, Book II of the Local Governemnt Code of 1991, as amended;\n(7) Promote people’s participation in development planning within the province; and\n(8) Exercise supervision and control over the secretariat of the provincial development council.\n(c) Exercise such other powers and perform such other functions and duties as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Engineer. – (a) No person shall be appointed provincial engineer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a licensed civil engineer. He or she must have acquired experience in the practice of his or her profession for at least five (5) years.\nThe appointment of the provincial engineer shall be mandatory.\n(b) The provincial engineer shall take charge of the engineering office, and shall:\n(1) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in infrastructure development and public works in general of the province;\n(2) Advise the provincial governor on infrastructure, public works and other engineering matters;\n(3) Administer, coordinate, supervise and control the construction, maintenance, improvement and repair of roads, bridges and other engineering and public works projects of the province;\n(4) Provide engineering services to the province, including investigations and surveys, engineering designs, feasibility studies and project management; and\n(5) Exercise technical supervision over all engineering offices of the component cities and municipalities.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Health Officer. – (a) No person shall be appointed provincial health officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a licensed medical practitioner. He or she must have acquired experience in the practice of his or her profession for at least five (5) years.\nThe appointment of a provincial health officer shall be mandatory.\n(b) The provincial health officer shall take charge of the office on health services, and shall:\n(1) Supervise the personnel and staff of the said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the provincial governor in order to assist him or her in the efficient, effective and economical implementation of health services program geared to the implementation of health-related projects and activities;\n(2) Formulate measures for the consideration of the sangguniang panlalawigan and provide technical assistance and support to the provincial governor in carrying out activities to ensure the delivery of basic services and the provision of adequate facilities relative to health services provided for under Section 17 of the Local Government Code of 1991, as amended;\n(3) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with health programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(4) In addition to the foregoing duties and functions, the provincial health officer shall:\n(i) Formulate and implement policies, plans, programs and projects to promote the health of the people of the province;\n(ii) Advise the provincial governor and the sanggunian on matters pertaining to health;\n(iii) Execute and enforce all laws, ordinances and regulations relating to public health;\n(iv) Recommend to the sanggunian, through the provincial health board, the passage of such ordinances as he or she may deem necessary for the preservation of public health;\n(v) Recommend the prosecution of any violation of sanitary laws, ordinances and regulations;\n(vi) Direct the sanitary inspection of all business establishments selling food items or providing accommodations, such as hotels, motels, lodging houses, pension houses and the like, in accordance with the Sanitation Code of the Philippines;\n(vii) Conduct health information campaigns and render health intelligence services;\n(viii) Coordinate with other government agencies and nongovernmental organizations involved in the promotion and delivery of health services; and\n(ix) Exercise general supervision over health offices of component cities and municipalities; and\n(5) Be in the frontline of the delivery of health services, particularly during and in the aftermath of man-made and natural disasters or calamities.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Administrator. – (a) No person shall be appointed provincial administrator unless he or she is a citizen of the Philippines; a resident of the province; of good moral character; a holder of a college degree preferably in public administration, law or any related course from a recognized college or university; and a first grade civil service eligible or its equivalent. He or she must have acquired experience in management and administration work for at least five (5) years.\nThe term of the provincial administrator is coterminous with that of his or her appointing authority.\nThe appointment of the provincial administrator shall be mandatory.\n(b) The provincial administrator shall take charge of the office of the administrator, and shall:\n(1) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the management and administration-related programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(2) In addition to the foregoing duties and functions, the provincial administrator shall:\n(i) Assist in the coordination of the work of all the officials of the province under the supervision, direction and control of the provincial governor and, for this purpose, he or she may convene the chiefs of offices and other officials of the province;\n(ii) Establish and maintain a sound personnel program for the province designed to promote career development and uphold the merit principle in the province; and\n(iii) Conduct a continuing organizational development of the province with the end in view of instituting effective administrative reforms;\n(3) Be in the frontline of the delivery of administrative support services, particularly those related to the situations during and in the aftermath of man-made and natural disasters and calamities;\n(4) Recommend to the sanggunian and advise the provincial governor on all other matters relative to the management and administration of the province; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Legal Officer. – (a) No person shall be appointed provincial legal officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a member of the Philippine Bar. He or she must have practiced his or her profession for at least five (5) years.\nThe term of the provincial legal officer shall be coterminous with that of his or her appointing authority.\nThe appointment of the provincial legal officer shall be mandatory.\n(b) The provincial legal officer, the chief legal counsel of the province, shall take charge of the office for legal services, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide legal assistance and support to the provincial governor in carrying out the delivery of basic services and the provisions of adequate facilities as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the programs and projects related to legal services which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial legal officer shall:\n(i) Represent the province in all civil actions and special proceedings wherein the province or any official thereof, in his or her official capacity, is a party: Provided, That actions or proceedings where a component city or municipality is a party adverse to the provincial government or to another component city or municipality, a special legal officer may be employed to represent the adverse party;\n(ii) When required by the provincial governor or the sanggunian, draft ordinances, contracts, bonds, leases and other instruments, involving any interest of the province and provide comments and recommendations on any instrument already drawn;\n(iii) Render his or her opinion in writing on any question of law when requested to do so by the provincial governor or the sanggunian;\n(iv) Investigate or cause to be investigated any provincial official or employee for administrative neglect or misconduct in office and recommend appropriate action to the provincial governor, or the sangguniang panlalawigan;\n(v) Investigate or cause to be investigated any person, firm or corporation holding any franchise or exercising any public privilege for failure to comply with any term or condition in the grant of such franchise or privilege, and recommend appropriate action to the provincial governor or the sanggunian;\n(vi) When directed by the provincial governor or the sanggunian, initiate and prosecute, in the interest of the province, any civil action on any bond, lease or other contract upon any breach or violation thereof; and\n(vii) Review and submit recommendations on ordinances approved and executive orders issued by the component cities and municipalities;\n(4) Recommend measures to the sangguniang panlalawigan and advise the provincial governor on all other matters related to the upholding of the rule of law; and\n(5) Be in the frontline of protecting human rights and prosecuting any violation thereof, particularly those which occur during and in the aftermath of man-made or natural disasters and calamities.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Agriculturist. – (a) No person shall be appointed provincial agriculturist unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree in agriculture or in any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have practiced his or her profession in agriculture or acquired experience in a related field for at least five (5) years.\nThe appointment of the provincial agriculturist shall be mandatory.\n(b) The provincial agriculturist shall take charge of the office for agricultural services, and shall:\n(1) Formulate measures for the approval of the sanggunian and provide technical assistance and support to the provincial governor in carrying out said measures to ensure the delivery of basic services and the provision of adequate facilities relative to agricultural services as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the agricultural programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial agriculturist shall:\n(i) Ensure that maximum assistance and access to resources in the production, processing and marketing of agricultural and aquacultural and marine products are extended to farmers, fishermen and local entrepreneurs;\n(ii) Conduct or cause to be conducted location-specific agricultural researches and assist in making available the appropriate technology arising out of and disseminating information on basic research on crops, preventive control of plant diseases and pests, and other agricultural matters which will maximize productivity;\n(iii) Assist the provincial governor in the establishment and extension services of demonstration farms on aquaculture and marine products;\n(iv) Enforce rules and regulations relating to agriculture and aquaculture; and\n(v) Coordinate with government agencies and nongovernmental organizations which promote agricultural productivity through appropriate technology compatible with environmental integrity;\n(4) Be in the frontline of delivery of basic agricultural services, particularly those needed for the survival of the inhabitants during and in the aftermath of man-made and natural disasters or calamities; and\n(5) Recommend to the sanggunian and advise the provincial governor on all matters related to agriculture and aquaculture which will improve the livelihood and living conditions of the inhabitants.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Social Welfare and Development Officer. – (a) No person shall be appointed provincial social welfare and development officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a duly licensed social worker, or a holder of a college degree preferably in sociology or in any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in the practice of social work for at least five (5) years.\nThe appointment of a provincial social welfare and development officer shall be mandatory.\n(b) The provincial social welfare and development officer shall take charge of the office on social welfare and development services, and shall:\n(1) Formulate measures for the approval of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to social welfare and development services as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the social welfare programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties, the provincial social welfare and development officer shall:\n(i) Identify the basic needs of the needy, the disadvantaged and the impoverished and develop and implement appropriate measures to alleviate their problems and improve their living conditions;\n(ii) Provide relief and appropriate crisis intervention for victims of abuse and exploitation and recommend appropriate measures to deter further abuse and exploitation;\n(iii) Assist the provincial governor in implementing the barangay level program for the total development and protection of children up to six (6) years of age;\n(iv) Facilitate the implementation of welfare programs for the disabled, the elderly and victims of drug addiction, the rehabilitation of prisoners and parolees, the prevention of juvenile delinquency and such other activities which would eliminate or minimize the ill-effects of poverty;\n(v) Initiate and support welfare programs that will enhance the role of the youth in nation-building; and\n(vi) Coordinate with government agencies and nongovernmental organizations which have for their purpose the promotion and the protection of all the needy, disadvantaged, underprivileged or impoverished groups or individuals, particularly those identified to be vulnerable and high-risk to exploitation, abuse and neglect;\n(4) Be in the frontline of service delivery, particularly those which have to do with the immediate relief and assistance during and in the aftermath of man-made and natural disasters or calamities; and\n(5) Recommend to the sanggunian and advise the provincial governor on all other matters related to social welfare and development service which will improve the livelihood and living conditions of the inhabitants.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Environment and Natural Resources Officer. – (a) No person shall be appointed provincial environment and natural resources officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in environmental and natural resources management, conservation and utilization for at least five (5) years.\nThe appointment of a provincial environment and natural resources officer shall be optional.\n(b) The provincial environment and natural resources officer shall take charge of the office on environment and natural resources, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to environment and natural resources services as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the environment and natural resources programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the environment and natural resources officer shall:\n(i) Establish, maintain, protect and preserve communal forests, watersheds, tree parks, mangroves, greenbelts, commercial forests and similar forest projects like industrial tree farms and agro-forestry projects;\n(ii) Provide extension services to beneficiaries of forest development projects and technical, financial and infrastructure assistance;\n(iii) Manage and maintain seed banks and produce seedlings for forests and tree parks;\n(iv) Provide extension services to beneficiaries of forest development projects and render assistance for natural resources-related conservation and utilization activities consistent with ecological balance;\n(v) Promote small-scale mining and utilization of mineral resources, particularly the mining of gold; and\n(vi) Coordinate with government agencies and nongovernmental organizations in the implementation of measures to prevent and control land, air and water pollution with the assistance of the Department of Environment and Natural Resources (DENR);\n(4) Be in the frontline of the delivery of services concerning the environment and natural resources, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made and natural disasters or calamities; and\n(5) Recommend to the sanggunian and advise the provincial governor on all matters relative to the protection, conservation, maximum utilization, application of appropriate technology and other matters related to the environment and natural resources.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Veterinarian. – (a) No person shall be appointed provincial veterinarian unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a licensed doctor of veterinary medicine. He or she must have practiced his or her profession for at least three (3) years.\nThe appointment of a provincial veterinarian shall be mandatory.\n(b) The provincial veterinarian shall take charge of the office for veterinary services, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities pursuant to Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the veterinary-related activities which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial veterinarian shall:\n(i) Advise the provincial governor on all matters pertaining to the slaughter of animals for human consumption and the regulation of slaughterhouses;\n(ii) Regulate the keeping of domestic animals;\n(iii) Regulate and inspect poultry, milk and dairy products for public consumption;\n(iv) Enforce all laws and regulations for the prevention of cruelty to animals; and\n(v) Take the necessary measures to eradicate, prevent or cure all forms of animal diseases;\n(4) Be in the frontline of veterinary-related activities, such as in the outbreak of highly contagious and deadly diseases and in situations resulting in the depletion of animals for work and for human consumption, particularly those arising from and in the aftermath of man-made and natural disasters or calamities; and\n(5) Recommend to the sanggunian and advise the provincial governor on all other matters relative to veterinary services which will increase the number and improve the quality of livestock, poultry and other domestic animals used for work or for human consumption.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial General Services Officer. – (a) No person shall be appointed provincial general services officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree in public administration, business administration and management from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in general services, including the management of supply, property, solid waste disposal and general sanitation for at least five (5) years.\nThe appointment of a provincial general services officer shall be mandatory.\n(b) The provincial general services officer shall take charge of the office of general services, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities pursuant to Section 17 of the Local Government Code of 1991, as amended, and which require general services expertise and technical support services;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with general services supportive to the welfare of the inhabitants which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial general services officer shall:\n(i) Take custody of and be accountable for all properties, real or personal, owned by the provincial government and those granted to it in the form of donation, reparation, assistance and counterpart of joint projects;\n(ii) With the approval of the provincial governor, assign building or land space to provincial officials or other public officials who, by law, are entitled to such space;\n(iii) Recommend to the provincial governor, the reasonable rental rates for local government properties whether real or personal which will be leased to public or private entities by the provincial government;\n(iv) Recommend to the provincial governor, the reasonable rental rates of private properties which may be leased for the official use of the provincial government;\n(v) Maintain and supervise janitorial, security, landscaping and other related services on all local government public buildings and other real property, whether owned or leased by the provincial government;\n(vi) Collate and disseminate information regarding prices, shipping and other costs of supplies and other items commonly used by the provincial government;\n(vii) Perform archival and record management with respect to records of offices and departments of the province; and\n(viii) Perform all other functions pertaining to supply and property management heretofore performed by the local government treasurer and to enforce policies on records creation, maintenance and disposal;\n(4) Be in the frontline of general services-related activities, such as the possible or imminent destruction or damage to records, supplies, properties and structures and the orderly and sanitary clearing up of waste materials or debris, particularly during and in the aftermath of man-made and natural disasters or calamities; and\n(5) Recommend to the sanggunian and advise the provincial governor on all matters relative to general services.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Cooperatives Officer. – (a) No person shall be appointed provincial cooperatives officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in business administration course with special training in cooperatives or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in cooperatives organization and management for at least five (5) years.\nThe appointment of a provincial cooperatives officer shall be optional.\n(b) The provincial cooperatives officer shall take charge of the office for the development of cooperatives, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities through the development of cooperatives, and in providing access to such services and facilities;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the integration of cooperatives principles and methods in programs which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial cooperatives officer shall:\n(i) Assist in the organization of cooperatives;\n(ii) Provide technical and the forms of assistance to existing cooperatives to enhance their viability as an economic enterprise and social organization; and\n(iii) Assist cooperatives in establishing linkages with government agencies and nongovernmental organizations involved in the promotion and integration of the concept of cooperatives in the livelihood of the people and other community activities;\n(4) Be in the frontline of cooperatives organization, rehabilitation or viability enhancement, particularly during and in the aftermath of man-made and natural disasters or calamities, to aid in their survival and, if necessary, subsequent rehabilitation; and\n(5) Recommend to the sanggunian and advise the provincial governor on all other matters relative to cooperatives development and viability enhancement which will improve the livelihood and the quality of life of the inhabitants.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Architect. – (a) No person shall be appointed provincial architect unless he or she is a citizen of the Philippines, a resident of the province, of good moral character and a duly licensed architect. He or she must have practiced his or her profession for at least five (5) years.\nThe appointment of a provincial architect shall be optional.\n(b) The provincial architect shall take charge of the office on architectural planning and design, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to architectural planning and design as provided for under Section 17 of the Local Government Code of 1991, as amended;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with architectural planning and design programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the provincial architect shall:\n(i) Prepare and recommend for consideration of the sanggunian the architectural plan and design for the province or a part thereof, including the renewal of slums and blighted areas, land reclamation activities, the greening of land and the appropriate planning of marine and foreshore areas;\n(ii) Review and recommend for appropriate action of the sanggunian and the provincial governor, the architectural plan and design submitted by governmental and nongovernmental entities or individuals, particularly those for undeveloped, underdeveloped and poorly-designed areas; and\n(iii) Coordinate with government agencies and nongovernmental entities and individuals involved in the aesthetics and the maximum utilization of the land and water within the jurisdiction of the province, compatible with environmental integrity and ecological balance;\n(4) Be in the frontline of the delivery of basic services involving architectural planning and design, particularly those related to the redesigning of spatial distribution of basic facilities and physical structures during and in the aftermath of man-made and natural calamities or disasters; and\n(5) Recommend to the sanggunian and advise the provincial governor on all other matters related to the architectural planning and design as it relates to the total socioeconomic development of the province.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Population Officer. – (a) No person shall be appointed provincial population officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree with specialized training in population development from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have experience in the implementation of programs on population development or responsible parenthood for at least five (5) years.\nThe appointment of a provincial population officer shall be optional.\n(b) The provincial population officer shall take charge of the office on population development, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in carrying out measures to ensure the delivery of basic services and the provision of adequate facilities relative to the integration of the population development principles and in providing access to said services and facilities;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with the integration of population development principles and methods in programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended; and\n(3) In addition to the foregoing duties and functions, the provincial population officer shall:\n(i) Assist the provincial governor in the implementation of the constitutional provisions relative to population development and the promotion of responsible parenthood;\n(ii) Establish and maintain an updated data bank for program operations, development planning and an educational program to ensure the people’s participation in and undertaking of population development; and\n(iii) Implement appropriate training programs responsive to the cultural heritage of the inhabitants.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H8812-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The Provincial Information Officer. – (a) No person shall be appointed provincial information officer unless he or she is a citizen of the Philippines, a resident of the province, of good moral character, a holder of a college degree preferably in journalism, mass communication or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He or she must have acquired experience in writing articles and research papers, or in writing for print, television or broadcast media for at least three (3) years.\nThe term of the provincial information officer is coterminous with that of his or her appointing authority.\nThe appointment of a provincial information officer shall be optional.\n(b) The provincial information officer shall take charge of the office on public information, and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the provincial governor in providing the information and research data required for the delivery of basic services and the provision of adequate facilities so that the public becomes aware of the said service and may fully avail of the same;\n(2) Develop plans and strategies and, upon approval thereof by the provincial governor, implement the same, particularly those which have to do with public information and research data to support the programs and projects which the provincial governor is empowered to implement and which the sanggunian is empowered to provide for under the Local Government Code of 1991, as amended;\n(3) In addition to the foregoing duties and functions, the information officer shall:\n(i) Provide relevant, adequate and timely information to the provincial government and its residents;\n(ii) Maintain effective liaison with the various sectors of the community on matters and issues that affect the livelihood and the quality of life of the inhabitants and encourage support for programs of the local and national government; and\n(iii) Furnish information and data on the province to government agencies or offices as may be required by law or ordinance and nongovernmental organizations to be furnished to said agencies and organizations;\n(4) Be in the frontline of providing information during and in the aftermath of man-made and natural disasters or calamities, with special attention to the victims thereof, to help minimize injuries and casualties during and after emergency, and accelerate relief and rehabilitation; and\n(5) Recommend to the sanggunian and advise the provincial governor on all other matters relative to public information and research data as it relates to the total socioeconomic development of the province.\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nTHE PROVINCIAL FIRE STATION, THE PROVINCIAL\nJAIL, THE PROVINCIAL SCHOOLS DIVISION AND\nTHE PROVINCIAL PROSECUTION SERVICE"}},{"id":"PH-H8812-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Provincial Fire Station Service. – (a) There shall be established in the province at least five (5) fire stations with adequate personnel, firefighting facilities and equipment by the DILG, within two (2) months upon the commencement of the corporate existence of the new province. The provincial government shall provide the necessary land or site of the provincial fire stations.\n(b) The provincial fire station service shall be headed by a provincial fire marshal whose qualifications shall be as those provided for under Republic Act No. 9263, as amended, otherwise known as the \"Bureau of Fire Protection and Bureau of Jail Management and Penology Professionalization Act of 2004″.\n(c) The provincial fire stations shall be responsible for the protection of various emergency services such as the rescue and evacuation of injured people at fire-related incidents and, in general, fire prevention and suppression measures to secure the safety of life and property of the citizenry."}},{"id":"PH-H8812-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Provincial Jail Service. – (a) There shall be established and maintained in the province, within two (2) months upon the commencement of the corporate existence of the new province by the DILG, a secured, clean, adequately equipped and sanitary jail facility for the custody and safekeeping of prisoners, any fugitive from justice, or person detained awaiting investigation or trial and/or transfer to the national penitentiary, and/or violent mentally ill person who endangers himself or the safety of others, duly certified as such by the proper medical health officer, pending the transfer to a mental institution.\n(b) The provincial jail service shall be headed by a provincial jail warden whose qualifications shall be as those provided for under Republic Act No. 9263, as amended, otherwise known as the \"Bureau of Fire Protection and Bureau of Jail Management and Penology Professionalization Act of 2004″. He or she shall assist in the immediate rehabilitation of individuals or detention of prisoners. Great care must be exercised so that human rights of these prisoners are respected and protected, and their spiritual and physical well-being are properly and promptly attended to."}},{"id":"PH-H8812-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Provincial Schools Division. – (a) The DepED shall, within two (2) months upon the commencement of the corporate existence of the province herein created, establish and maintain a separate schools division in the province whose jurisdiction shall cover all the municipalities of the new province.\n(b) The provincial schools division shall be headed by a division superintendent who must possess the necessary qualifications required by the DepED."}},{"id":"PH-H8812-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The Provincial Prosecution Service. – (a) There shall be established and maintained a prosecution service by the Department of Justice (DOJ), within two (2) months upon the commencement of the corporate existence of the province herein created, who shall be headed by a provincial prosecutor and such number of assistant prosecutors as may be necessary, who shall be organizationally part of the DOJ, and under the supervision and control, of the Secretary of the DOJ, and whose qualifications, manner of appointment, rank, salary and benefits shall be governed by existing laws covering prosecutors in the DOJ.\n(b) The provincial prosecutor shall handle the criminal prosecution in the municipal trial courts in the province as well as in the regional trial courts for criminal cases originating in the territory of the new province and shall render to and for the province such other services as are required by law or regulation of the DOJ.\nTRANSITORY AND FINAL, PROVISIONS"}},{"id":"PH-H8812-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Plebiscite. – The Province of Davao Occidental shall be created, as provided for in this Charter, upon approval by the majority of the votes cast by the voters of the affected areas in a plebiscite to be conducted and supervised by the Commission on Elections (COMELEC) within sixty (60) days from the date of the effectivity of this Charter.\nThe amount, necessary for the conduct of the plebiscite shall be borne by the COMELEC."}},{"id":"PH-H8812-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Commencement of Corporate Existence. – The Province of Davao Occidental shall commence corporate existence upon the election and qualification of the provincial governor, provincial vice governor and majority of the members of the sangguniang panlalawigan."}},{"id":"PH-H8812-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Officials of the Province of Davao Occidental. – The first set of elective officials of the Province of Davao Occidental shall be elected in the next national and local elections following the effectivity of this Charter.\nAll elective and nonelective provincial and local government officials and employees of the present Province of Davao del Sur shall continue to serve their term of office, perform their duties and functions in the province, until the commencement of the corporate existence of the new province, as provided for in the immediately preceding section of this Act."}},{"id":"PH-H8812-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Organization of the Provincial Government. – All provincial appointive positions in the Province of Davao Occidental shall be filled within sixty (60) days upon commencement of its corporate existence. This shall be done without prejudice to the officials and employees of the present Province of Davao del Sur who may wish to serve in the Province of Davao Occidental."}},{"id":"PH-H8812-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Suspension of Increase in the Rates of Local Taxes. – No increase in the rates of local taxes shall be imposed by the new province within the period of five (5) years from its acquisition of corporate existence."}},{"id":"PH-H8812-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Present Provincial Properties. – Upon the effectivity of this Act, the ownership of real properties and infrastructure projects of each LGU situated in the present Province of Davao del Sur shall belong to the province where it is situated."}},{"id":"PH-H8812-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Applicability of Laws. – The provisions of Republic Act No. 7160, otherwise known as the Local Government Code of 1991, as amended, and other laws as are applicable to provinces shall govern the herein created province insofar as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H8812-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Separability Clause. – If any part of this Act is declared invalid or unconstitutional, the other parts or provisions thereof shall remain valid and effective."}},{"id":"PH-H8812-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days upon its publication in at least two (2) newspapers of general and local circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Province of Davao Occidental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8813"] = {"id":"PH-H8813","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10361_2013.html","fetchedAt":"2026-10-06","articleCount":45,"structureMode":"ARTICLE","title":{"zh":"制定家庭工人保护与福利政策的法案","en":"An Act Instituting Policies for the Protection and Welfare of Domestic Workers","orig":"An Act Instituting Policies for the Protection and Welfare of Domestic Workers","vi":"Đạo luật thiết lập chính sách bảo vệ và phúc lợi cho người giúp việc gia đình","th":"พระราชบัญญัติกำหนดนโยบายคุ้มครองและสวัสดิการของคนทำงานบ้าน","id":"Undang-Undang menetapkan kebijakan perlindungan dan kesejahteraan pekerja rumah tangga","ms":"Akta menetapkan dasar perlindungan dan kebajikan pekerja rumah tangga"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 10361","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-18","completenessNote":"全文，共 45 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10361_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8813-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \"Domestic Workers Act\" or \"Batas Kasambahay\"."}},{"id":"PH-H8813-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policies. – It is hereby declared that:\n(a) The State strongly affirms labor as a primary social force and is committed to respect, promote, protect and realize the fundamental principles and rights at work including, but not limited to, abolition of child labor, elimination of all forms of forced labor, discrimination in employment and occupation, and trafficking in persons, especially women and children;\n(b) The State adheres to internationally accepted working conditions for workers in general, and establishes labor standards for domestic workers in particular, towards decent employment and income, enhanced coverage of social protection, respect for human rights and strengthened social dialogue;\n(c) The State recognizes the need to protect the rights of domestic workers against abuse, harassment, violence, economic exploitation and performance of work that is hazardous to their physical and mental health; and\n(d) The State, in protecting domestic workers and recognizing their special needs to ensure safe and healthful working conditions, promotes gender-sensitive measures in the formulation and implementation of policies and programs affecting the local domestic work."}},{"id":"PH-H8813-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Coverage. – This Act applies to all domestic workers employed and working within the country."}},{"id":"PH-H8813-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. – As used in this Act, the term:\n(a) Debt bondage refers to the rendering of service by the domestic worker as security or payment for a debt where the length and nature of service is not clearly defined or when the value of the service is not reasonably applied in the payment of the debt.\n(b) Deployment expenses refers to expenses that are directly used for the transfer of the domestic worker from place of origin to the place of work covering the cost of transportation. Advances or loans by the domestic worker are not included in the definition of deployment expenses.\n(c) Domestic work refers to work performed in or for a household or households.\n(d) Domestic worker or \"Kasambahay\" refers to any person engaged in domestic work within an employment relationship such as, but not limited to, the following: general househelp, nursemaid or \"yaya\", cook, gardener, or laundry person, but shall exclude any person who performs domestic work only occasionally or sporadically and not on an occupational basis.\nThe term shall not include children who are under foster family arrangement, and are provided access to education and given an allowance incidental to education, i.e. \"baon\", transportation, school projects and school activities.\n(e) Employer refers to any person who engages and controls the services of a domestic worker and is party to the employment contract.\n(f) Household refers to the immediate members of the family or the occupants of the house that are directly provided services by the domestic worker.\n(g) Private Employment Agency (PEA) refers to any individual, legitimate partnership, corporation or entity licensed to engage in the recruitment and placement of domestic workers for local employment.\n(h) Working children, as used under this Act, refers to domestic workers who are fifteen (15) years old and above but below eighteen (18) years old.\nRIGHTS AND PRIVILEGES"}},{"id":"PH-H8813-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Standard of Treatment. – The employer or any member of the household shall not subject a domestic worker or \"kasambahay\" to any kind of abuse nor inflict any form of physical violence or harassment or any act tending to degrade the dignity of a domestic worker."}},{"id":"PH-H8813-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Board, Lodging and Medical Attendance. – The employer shall provide for the basic necessities of the domestic worker to include at least three (3) adequate meals a day and humane sleeping arrangements that ensure safety.\nThe employer shall provide appropriate rest and assistance to the domestic worker in case of illnesses and injuries sustained during service without loss of benefits.\nAt no instance shall the employer withdraw or hold in abeyance the provision of these basic necessities as punishment or disciplinary action to the domestic worker."}},{"id":"PH-H8813-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Guarantee of Privacy. – Respect for the privacy of the domestic worker shall be guaranteed at all times and shall extend to all forms of communication and personal effects. This guarantee equally recognizes that the domestic worker is obliged to render satisfactory service at all times."}},{"id":"PH-H8813-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Access to Outside Communication. – The employer shall grant the domestic worker access to outside communication during free time: Provided, That in case of emergency, access to communication shall be granted even during work time. Should the domestic worker make use of the employer’s telephone or other communication facilities, the costs shall be borne by the domestic worker, unless such charges are waived by the employer."}},{"id":"PH-H8813-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Right to Education and Training. – The employer shall afford the domestic worker the opportunity to finish basic education and may allow access to alternative learning systems and, as far as practicable, higher education or technical and vocational training. The employer shall adjust the work schedule of the domestic worker to allow such access to education or training without hampering the services required by the employer."}},{"id":"PH-H8813-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Prohibition Against Privileged Information. – All communication and information pertaining to the employer or members of the household shall be treated as privileged and confidential, and shall not be publicly disclosed by the domestic worker during and after employment. Such privileged information shall be inadmissible in evidence except when the suit involves the employer or any member of the household in a crime against persons, property, personal liberty and security, and chastity.\nPRE-EMPLOYMENT"}},{"id":"PH-H8813-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Employment Contract. – An employment contract shall be executed by and between the domestic worker and the employer before the commencement of the service in a language or dialect understood by both the domestic worker and the employer. The domestic worker shall be provided a copy of the duly signed employment contract which must include the following:\n(a) Duties and responsibilities of the domestic worker;\n(b) Period of employment;\n(c) Compensation;\n(d) Authorized deductions;\n(e) Hours of work and proportionate additional payment;\n(f) Rest days and allowable leaves;\n(g) Board, lodging and medical attention;\n(h) Agreements on deployment expenses, if any;\n(i) Loan agreement;\n(j) Termination of employment; and\n(k) Any other lawful condition agreed upon by both parties.\nThe Department of Labor and Employment (DOLE) shall develop a model employment contract for domestic workers which shall, at all times, be made available free of charge to domestic workers, employers, representative organizations and the general public. The DOLE shall widely disseminate information to domestic workers and employers on the use of such model employment contract.\nIn cases where the employment of the domestic worker is facilitated through a private employment agency, the PEA shall keep a copy of all employment contracts of domestic workers and shall be made available for verification and inspection by the DOLE."}},{"id":"PH-H8813-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Pre-Employment Requirement. – Prior to the execution of the employment contract, the employer may require the following from the domestic worker:\n(a) Medical certificate or a health certificate issued by a local government health officer;\n(b) Barangay and police clearance;\n(c) National Bureau of Investigation (NBI) clearance; and\n(d) Duly authenticated birth certificate or if not available, any other document showing the age of the domestic worker such as voter’s identification card, baptismal record or passport.\nHowever, Section 12(a), (b), (c) and (d) shall be standard requirements when the employment of the domestic worker is facilitated through the PEA.\nThe cost of the foregoing shall be borne by the prospective employer or agency, as the case may be."}},{"id":"PH-H8813-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Recruitment and Finder’s Fees. – Regardless of whether the domestic worker was hired through a private employment agency or a third party, no share in the recruitment or finder’s fees shall be charged against the domestic worker by the said private employment agency or third party."}},{"id":"PH-H8813-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Deposits for Loss or Damage. – It shall be unlawful for the employer or any other person to require a domestic worker to make deposits from which deductions shall be made for the reimbursement of loss or damage to tools, materials, furniture and equipment in the household."}},{"id":"PH-H8813-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Prohibition on Debt Bondage. – It shall be unlawful for the employer or any person acting on behalf of the employer to place the domestic worker under debt bondage."}},{"id":"PH-H8813-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Employment Age of Domestic Workers. – It shall be unlawful to employ any person below fifteen (15) years of age as a domestic worker. Employment of working children, as defined under this Act, shall be subject to the provisionsof Section 10(A), paragraph 2 of Section 12-A, paragraph 4 of Section 12-D, and Section 13 of Republic Act No. 7610, as amended, otherwise known as the \"Special Protection of Children Against Child Abuse, Exploitation and Discrimination Act\".\nWorking children shall be entitled to minimum wage, and all benefits provided under this Act.\nAny employer who has been sentenced by a court of law of any offense against a working child under this Act shall be meted out with a penalty one degree higher and shall be prohibited from hiring a working child."}},{"id":"PH-H8813-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Employer’s Reportorial Duties. – The employers shall register all domestic workers under their employment in the Registry of Domestic Workers in the barangay where the employer’s residence is located. The Department of the Interior and Local Government (DILG) shall, in coordination with the DOLE, formulate a registration system for this purpose."}},{"id":"PH-H8813-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Skills Training, Assessment and Certification. – To ensure productivity and assure quality services, the DOLE, through the Technical Education and Skills Development Authority (TESDA), shall facilitate access of domestic workers to efficient training, assessment and certification based on a duly promulgated training regulation.\nEMPLOYMENT – TERMS AND CONDITIONS"}},{"id":"PH-H8813-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Health and Safety. – The employer shall safeguard the health and safety of the domestic worker in accordance with laws, rules and regulations, with due consideration of the peculiar nature of domestic work."}},{"id":"PH-H8813-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Daily Rest Period. – The domestic worker shall be entitled to an aggregate daily rest period of eight (8) hours per day."}},{"id":"PH-H8813-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Weekly Rest Period. – The domestic worker shall be entitled to at least twenty-four (24) consecutive hours of rest in a week. The employer and the domestic worker shall agree in writing on the schedule of the weekly rest day of the domestic worker: Provided, That the employer shall respect the preference of the domestic worker as to the weekly rest day when such preference is based on religious grounds. Nothing in this provision shall deprive the domestic worker and the employer from agreeing to the following:\n(a) Offsetting a day of absence with a particular rest day;\n(b) Waiving a particular rest day in return for an equivalent daily rate of pay;\n(c) Accumulating rest days not exceeding five (5) days; or\n(d) Other similar arrangements."}},{"id":"PH-H8813-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Assignment to Nonhousehold Work. – No domestic worker shall be assigned to work in a commercial, industrial or agricultural enterprise at a wage rate lower than that provided for agricultural or nonagricultural workers. In such cases, the domestic worker shall be paid the applicable minimum wage."}},{"id":"PH-H8813-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Extent of Duty. – The domestic worker and the employer may mutually agree for the former to temporarily perform a task that is outside the latter’s household for the benefit of another household. However, any liability that will be incurred by the domestic worker on account of such arrangement shall be borne by the original employer. In addition, such work performed outside the household shall entitle the domestic worker to an additional payment of not less than the existing minimum wage rate of a domestic worker. It shall be unlawful for the original employer to charge any amount from the said household where the service of the domestic worker was temporarily performed."}},{"id":"PH-H8813-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Minimum Wage. – The minimum wage of domestic workers shall not be less than the following:\n(a) Two thousand five hundred pesos (P2,500.00) a month for those employed in the National Capital Region (NCR);\n(b) Two thousand pesos (P2,000.00) a month for those employed in chartered cities and first class municipalities; and\n(c) One thousand five hundred pesos (P1,500.00) a month for those employed mother municipalities.\nAfter one (1) year from the effectivity of this Act, and periodically thereafter, the Regional Tripartite and Productivity Wage Boards (RTPWBs) shall review, and if proper, determine and adjust the minimum wage rates of domestic workers."}},{"id":"PH-H8813-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Payment of Wages. – Payment of wages shall be made on time directly to the domestic worker to whom they are due in cash at least once a month. The employer, unless allowed by the domestic worker through a written consent, shall make no deductions from the wages other than that which is mandated by law. No employer shall pay the wages of a domestic worker by means of promissory notes, vouchers, coupons, tokens, tickets, chits, or any object other than the cash wage as provided for under this Act.\nThe domestic worker is entitled to a thirteenth month pay as provided for by law."}},{"id":"PH-H8813-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Pay Slip. – The employer shall at all times provide the domestic worker with a copy of the pay slip containing the amount paid in cash every pay day, and indicating all deductions made, if any. The copies of the pay slip shall be kept by the employer for a period of three (3) years."}},{"id":"PH-H8813-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Prohibition on Interference in the Disposal of Wages. – It shall be unlawful for the employer to interfere with the freedom of any domestic worker to dispose of the latter’s wages. The employer shall not force, compel or oblige the domestic worker to purchase merchandise, commodities or other properties from the employer or from any other person, or otherwise make use of any store or services of such employer or any other person."}},{"id":"PH-H8813-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Prohibition Against Withholding of Wages. – It shall be unlawful for an employer, directly or indirectly, to withhold the wages of the domestic worker. If the domestic worker leaves without any justifiable reason, any unpaid salary for a period not exceeding fifteen (15) days shall be forfeited. Likewise, the employer shall not induce the domestic worker to give up any part of the wages by force, stealth, intimidation, threat or by any other means whatsoever."}},{"id":"PH-H8813-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Leave Benefits. – A domestic worker who has rendered at least one (1) year of service shall be entitled to an annual service incentive leave of five (5) days with pay: Provided, That any unused portion of said annual leave shall not be cumulative or carried over to the succeeding years. Unused leaves shall not be convertible to cash."}},{"id":"PH-H8813-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Social and Other Benefits. – A domestic worker who has rendered at least one (1) month of service shall be covered by the Social Security System (SSS), the Philippine Health Insurance Corporation (PhilHealth), and the Home Development Mutual Fund or Pag-IBIG, and shall be entitled to all the benefits in accordance with the pertinent provisions provided by law.\nPremium payments or contributions shall be shouldered by the employer. However, if the domestic worker is receiving a wage of Five thousand pesos (P5,000.00) and above per month, the domestic worker shall pay the proportionate share in the premium payments or contributions, as provided by law.\nThe domestic worker shall be entitled to all other benefits under existing laws."}},{"id":"PH-H8813-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Rescue and Rehabilitation of Abused Domestic Workers. – Any abused or exploited domestic worker shall be immediately rescued by a municipal or city social welfare officer or a social welfare officer from the Department of Social Welfare and Development (DSWD) in coordination with the concerned barangay officials. The DSWD and the DILG shall develop a standard operating procedure for the rescue and rehabilitation of abused domestic workers, and in coordination with the DOLE, for possible subsequent job placement.\nPOST EMPLOYMENT"}},{"id":"PH-H8813-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Termination of Service. – Neither the domestic worker nor the employer may terminate the contract before the expiration of the term except for grounds provided for in Sections 33 and 34 of this Act. If the domestic worker is unjustly dismissed, the domestic worker shall be paid the compensation already earned plus the equivalent of fifteen (15) days work by way of indemnity. If the domestic worker leaves without justifiable reason, any unpaid salary due not exceeding the equivalent fifteen (15) days work shall be forfeited. In addition, the employer may recover from the domestic worker costs incurred related to the deployment expenses, if any: Provided, That the service has been terminated within six (6) months from the domestic worker’s employment.\nIf the duration of the domestic service is not determined either in stipulation or by the nature of the service, the employer or the domestic worker may give notice to end the working relationship five (5) days before the intended termination of the service.\nThe domestic worker and the employer may mutually agree upon written notice to pre-terminate the contract of employment to end the employment relationship."}},{"id":"PH-H8813-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Termination Initiated by the Domestic Worker. – The domestic worker may terminate the employment relationship at any time before the expiration of the contract for any of the following causes:\n(a) Verbal or emotional abuse of the domestic worker by the employer or any member of the household;\n(b) Inhuman treatment including physical abuse of the domestic worker by the employer or any member of the household;\n(c) Commission of a crime or offense against the domestic worker by the employer or any member of the household;\n(d) Violation by the employer of the terms and conditions of the employment contract and other standards set forth under this law;\n(e) Any disease prejudicial to the health of the domestic worker, the employer, or member/s of the household; and\n(f) Other causes analogous to the foregoing."}},{"id":"PH-H8813-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Termination Initiated by the Employer. – An employer may terminate the services of the domestic worker at any time before the expiration of the contract, for any of the following causes:\n(a) Misconduct or willful disobedience by the domestic worker of the lawful order of the employer in connection with the former’s work;\n(b) Gross or habitual neglect or inefficiency by the domestic worker in the performance of duties;\n(c) Fraud or willful breach of the trust reposed by the employer on the domestic worker;\n(d) Commission of a crime or offense by the domestic worker against the person of the employer or any immediate member of the employer’s family;\n(e) Violation by the domestic worker of the terms and conditions of the employment contract and other standards set forth under this law;\n(f) Any disease prejudicial to the health of the domestic worker, the employer, or member/s of the household; and\n(g) Other causes analogous to the foregoing."}},{"id":"PH-H8813-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Employment Certification. – Upon the severance of the employment relationship, the employer shall issue the domestic worker within five (5) days from request a certificate of employment indicating the nature, duration of the service and work performance.\nPRIVATE EMPLOYMENT AGENCIES"}},{"id":"PH-H8813-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Regulation of Private Employment Agencies (PEAs). – The DOLE shall, through a system of licensing and regulation, ensure the protection of domestic workers hired through the PEAs.\nThe PEA shall be jointly and severally liable with the employer for all the wages, wage-related benefits, and other benefits due a domestic worker.\nThe provision of Presidential Decree No. 442, as amended, otherwise known as the \"Labor Code of the Philippines\", on qualifications of the PEAs with regard to nationality, networth, owners and officers, office space and other requirements, as well as nontransferability of license and commission of prohibited practices, shall apply.\nIn addition, PEAs shall have the following responsibilities:\n(a) Ensure that domestic workers are not charged or levied any recruitment or placement fees;\n(b) Ensure that the employment agreement between the domestic worker and the employer stipulates the terms and conditions of employment and all the benefits prescribed by this Act;\n(c) Provide a pre-employment orientation briefing to the domestic worker and the employer about their rights and responsibilities in accordance with this Act;\n(d) Keep copies of employment contracts and agreements pertaining to recruited domestic workers which shall be made available during inspections or whenever required by the DOLE or local government officials;\n(e) Assist domestic workers with respect to complaints or grievances against their employers; and\n(f) Cooperate with government agencies in rescue operations involving abused or exploited domestic workers.\nSETTLEMENT OF DISPUTES"}},{"id":"PH-H8813-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Mechanism for Settlement of Disputes. – All labor-related disputes shall be elevated to the DOLE Regional Office having jurisdiction over the workplace without prejudice to the filing of a civil or criminal action in appropriate cases. The DOLE Regional Office shall exhaust all conciliation and mediation efforts before a decision shall be rendered.\nOrdinary crimes or offenses committed under the Revised Penal Code and other special penal laws by either party shall be filed with the regular courts.\nSPECIAL PROVISIONS"}},{"id":"PH-H8813-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Information Program. – The DOLE shall, in coordination with the DILG, the SSS, the PhilHealth and Pag-IBIG develop and implement a continuous information dissemination program on the provisions of this Act, both at the national and local level, immediately after the enactment of this law."}},{"id":"PH-H8813-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"\"Araw Ng Mga Kasambahay\". – The date upon which the President shall approve this \"Domestic Workers Act\" shall be designated as the \"Araw ng mga Kasambahay\".\nPENAL AND MISCELLANEOUS PROVISIONS"}},{"id":"PH-H8813-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Penalty. – Any violation of the provisions of this Act declared unlawful shall be punishable with a fine of not less than Ten thousand pesos (P10,000.00) but not more than Forty thousand pesos (P40,000.00) without prejudice to the filing of appropriate civil or criminal action by the aggrieved party."}},{"id":"PH-H8813-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Transitory Provision; Non-Diminution of Benefits. – All existing arrangements between a domestic worker and the employer shall be adjusted to conform to the minimum standards set by this Act within a period of sixty (60) days after the effectivity of this Act: Provided, That adjustments pertaining to wages shall take effect immediately after the determination and issuance of the appropriate wage order by the RTWPBs: Provided, further, That nothing in this Act shall be construed to cause the diminution or substitution of any benefits and privileges currently enjoyed by the domestic worker hired directly or through an agency."}},{"id":"PH-H8813-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Implementing Rules and Regulations. – Within ninety (90) days from the effectivity of this Act, the Secretary of Labor and Employment, the Secretary of Social Welfare and Development, the Secretary of the Interior and Local Government, and the Director General of the Philippine National Police, in coordination with other concerned government agencies and accredited nongovernment organizations (NGOs) assisting domestic workers, shall promulgate the necessary rules and regulations for the effective implementation of this Act.\nFINAL PROVISIONS"}},{"id":"PH-H8813-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Separability Clause. – If any provision or part of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected shall remain in full force and effect."}},{"id":"PH-H8813-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Repealing Clause. – All articles or provisions of Chapter III (Employment of Househelpers) of Presidential Decree No. 442, as amended and renumbered by Republic Act No. 10151 are hereby expressly repealed. All laws, decrees, executive orders, issuances, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8813-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Instituting Policies for the Protection and Welfare of Domestic Workers","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8814"] = {"id":"PH-H8814","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10362_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Trento市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating an Additional Regional Trial Court Branch to be Stationed in the Municipality of Trento, Province of Agusan Del Sur, Amending for the Purpose Section 14, Paragraph (k) of Batas Pambansa Blg. 129, as amended, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", and Providing Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10362","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10362_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8814-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"An additional Regional Trial Court branch is hereby created in the Tenth Judicial Region with seat at the Municipality of Trento, Province of Agusan del Sur.\nThe Supreme Court shall assign the branch number of the newly-created branch of the Regional Trial Court in the Tenth Judicial Region."}},{"id":"PH-H8814-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of an additional branch of the Regional Trial Court to be stationed in the Municipality of Trento, Province of Agusan del Sur, the funding of which, shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court herein created shall be appropriated and released only upon the actual organization of the Court and the appointment of its personnel."}},{"id":"PH-H8814-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(k) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8814-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8815"] = {"id":"PH-H8815","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10363_2013.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Mandaue市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Seven (7) Additional Branches of the Regional Trial Court in the Seventh Judicial Region to be Stationed at the City of Mandaue, Province of Cebu, Further Amending for the Purpose Batas Pambansa Bilang 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10363","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-01-28","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10363_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8815-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Seven (7) additional Regional Trial Court branches for Mandaue City, Cebu, with seats thereat, are hereby created in the Seventh Judicial Region."}},{"id":"PH-H8815-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Supreme Court shall assign the respective branch numbers for the newly created branches."}},{"id":"PH-H8815-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the implementation of this Act. The funding therefor shall likewise be included in the annual General Appropriations Act. The funds necessary for the operation of the court(s) herein created shall be appropriated and released only upon the actual organization of the court(s) and the appointment of its personnel."}},{"id":"PH-H8815-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 14 (h) of Batas Pambansa Bilang 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, as well as other provisions that may be inconsistent herewith, is hereby deemed repealed, modified and/or further amended."}},{"id":"PH-H8815-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after completion of its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8816"] = {"id":"PH-H8816","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10364_2013.html","fetchedAt":"2026-10-06","articleCount":27,"structureMode":"ARTICLE","title":{"zh":"扩展第 9208 号共和国法（题为「规定消除人口贩运特别是贩运妇女儿童的政策、建立保护与支助被贩运者的必要体制机制、规定违规处罚并为其他目的法案」）的法案","en":"An Act Expanding Republic Act No. 9208, Entitled \"An Act to Institute Policies to Eliminate Trafficking in Persons Especially Women and Children, Establishing the Necessary Institutional Mechanisms for the Protection and Support of Trafficked Persons, Providing Penalties for its Violations and for Other Purposes\"","orig":"An Act Expanding Republic Act No. 9208, Entitled \"An Act to Institute Policies to Eliminate Trafficking in Persons Especially Women and Children, Establishing the Necessary Institutional Mechanisms for the Protection and Support of Trafficked Persons, Providing Penalties for its Violations and for Other Purposes\""},"level":"law","status":"active","topics":["criminal","civil"],"docNumber":"Republic Act No. 10364","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-06","completenessNote":"全文，共 27 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10364_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8816-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the \"Expanded Anti-Trafficking in Persons Act of 2012″."}},{"id":"PH-H8816-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 2. Declaration of Policy. – It is hereby declared that the State values the dignity of every human person and guarantees the respect of individual rights. In pursuit of this policy, the State shall give highest priority to the enactment of measures and development of programs that will promote human dignity, protect the people from any threat of violence and exploitation, eliminate trafficking in persons, and mitigate pressures for involuntary migration and servitude of persons, not only to support trafficked persons but more importantly, to ensure their recovery, rehabilitation and reintegration into the mainstream of society.\n\"It shall be a State policy to recognize the equal rights and inherent human dignity of women and men as enshrined in the United Nations Universal Declaration on Human Rights, United Nations Convention on the Elimination of All Forms of Discrimination Against Women, United Nations Convention on the Rights of the Child, United Nations Convention on the Protection of Migrant Workers and their Families, United Nations Convention Against Transnational Organized Crime Including its Protocol to Prevent, Suppress and Punish Trafficking in Persons, Especially Women and Children and all other relevant and universally accepted human rights instruments and other international conventions to which the Philippines is a signatory.\""}},{"id":"PH-H8816-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 3 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 3. Definition of Terms. – As used in this Act:\n\"(a) Trafficking in Persons – refers to the recruitment, obtaining, hiring, providing, offering, transportation, transfer, maintaining, harboring, or receipt of persons with or without the victim’s consent or knowledge, within or across national borders by means of threat, or use of force, or other forms of coercion, abduction, fraud, deception, abuse of power or of position, taking advantage of the vulnerability of the person, or, the giving or receiving of payments or benefits to achieve the consent of a person having control over another person for the purpose of exploitation which includes at a minimum, the exploitation or the prostitution of others or other forms of sexual exploitation, forced labor or services, slavery, servitude or the removal or sale of organs.\n\"The recruitment, transportation, transfer, harboring, adoption or receipt of a child for the purpose of exploitation or when the adoption is induced by any form of consideration for exploitative purposes shall also be considered as ‘trafficking in persons’ even if it does not involve any of the means set forth in the preceding paragraph.\n\"(b) Child – refers to a person below eighteen (18) years of age or one who is over eighteen (18) but is unable to fully take care of or protect himself/herself from abuse, neglect, cruelty, exploitation, or discrimination because of a physical or mental disability or condition.\n\"(c) Prostitution – refers to any act, transaction, scheme or design involving the use of a person by another, for sexual intercourse or lascivious conduct in exchange for money, profit or any other consideration.\n\"(d) Forced Labor – refers to the extraction of work or services from any person by means of enticement, violence, intimidation or threat, use of, force or coercion, including deprivation of freedom, abuse of authority or moral ascendancy, debt-bondage or deception including any work or service extracted from any person under the menace of penalty.\n\"(e) Slavery – refers to the status or condition of a person over whom any or all of the powers attaching to the right of ownership are exercised.\n\"(f) Involuntary Servitude – refers to a condition of enforced and compulsory service induced by means of any scheme, plan or pattern, intended to cause a person to believe that if he or she did not enter into or continue in such condition, he or she or another person would suffer serious harm or other forms of abuse or physical restraint, or threat of abuse or harm, or coercion including depriving access to travel documents and withholding salaries, or the abuse or threatened abuse of the legal process.\n\"(g) Sex Tourism – refers to a program organized by travel and tourism-related establishments and individuals which consists of tourism packages or activities, utilizing and offering escort and sexual services as enticement for tourists. This includes sexual services and practices offered during rest and recreation periods for members of the military.\n\"(h) Sexual Exploitation – refers to participation by a person in prostitution, pornography or the production of pornography, in exchange for money, profit or any other consideration or where the participation is caused or facilitated by any means of intimidation or threat, use of force, or other forms of coercion, abduction, fraud, deception, debt bondage, abuse of power or of position or of legal process, taking advantage of the vulnerability of the person, or giving or receiving of payments or benefits to achieve the consent of a person having control over another person; or in sexual intercourse or lascivious conduct caused or facilitated by any means as provided in this Act.\n\"(i) Debt Bondage – refers to the pledging by the debtor of his/her personal services or labor or those of a person under his/her control as security or payment for a debt, when the length and nature of services is not clearly defined or when the value of the services as reasonably assessed is not applied toward the liquidation of the debt.\n\"(j) Pornography – refers to any representation, through publication, exhibition, cinematography, indecent shows, information technology, or by whatever means, of a person engaged in real or simulated explicit sexual activities or any representation of the sexual parts of a person for primarily sexual purposes.\n\"(k) Council – shall mean the Inter-Agency Council Against Trafficking created under Section 20 of this Act.\""}},{"id":"PH-H8816-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 4 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 4. Acts of Trafficking in Persons. – It shall be unlawful for any person, natural or juridical, to commit any of the following acts:\n\"(a) To recruit, obtain, hire, provide, offer, transport, transfer, maintain, harbor, or receive a person by any means, including those done under the pretext of domestic or overseas employment or training or apprenticeship, for the purpose of prostitution, pornography, or sexual exploitation;\n\"(b) To introduce or match for money, profit, or material, economic or other consideration, any person or, as provided for under Republic Act No. 6955, any Filipino woman to a foreign national, for marriage for the purpose of acquiring, buying, offering, selling or trading him/her to engage in prostitution, pornography, sexual exploitation, forced labor, slavery, involuntary servitude or debt bondage;\n\"(c) To offer or contract marriage, real or simulated, for the purpose of acquiring, buying, offering, selling, or trading them to engage in prostitution, pornography, sexual exploitation, forced labor or slavery, involuntary servitude or debt bondage;\n\"(d) To undertake or organize tours and travel plans consisting of tourism packages or activities for the purpose of utilizing and offering persons for prostitution, pornography or sexual exploitation;\n\"(e) To maintain or hire a person to engage in prostitution or pornography;\n\"(f) To adopt persons by any form of consideration for exploitative purposes or to facilitate the same for purposes of prostitution, pornography, sexual exploitation, forced labor, slavery, involuntary servitude or debt bondage;\n\"(g) To adopt or facilitate the adoption of persons for the purpose of prostitution, pornography, sexual exploitation, forced labor, slavery, involuntary servitude or debt bondage;\n\"(h) To recruit, hire, adopt, transport, transfer, obtain, harbor, maintain, provide, offer, receive or abduct a person, by means of threat or use of force, fraud, deceit, violence, coercion, or intimidation for the purpose of removal or sale of organs of said person;\n\"(i) To recruit, transport, obtain, transfer, harbor, maintain, offer, hire, provide, receive or adopt a child to engage in armed activities in the Philippines or abroad;\n\"(j) To recruit, transport, transfer, harbor, obtain, maintain, offer, hire, provide or receive a person by means defined in Section 3 of this Act for purposes of forced labor, slavery, debt bondage and involuntary servitude, including a scheme, plan, or pattern intended to cause the person either:\n\"(1) To believe that if the person did not perform such labor or services, he or she or another person would suffer serious harm or physical restraint; or \"(2) To abuse or threaten the use of law or the legal processes; and \"(k) To recruit, transport, harbor, obtain, transfer, maintain, hire, offer, provide, adopt or receive a child for purposes of exploitation or trading them, including but not limited to, the act of baring and/or selling a child for any consideration or for barter for purposes of exploitation. Trafficking for purposes of exploitation of children shall include:\n\"(1) All forms of slavery or practices similar to slavery, involuntary servitude, debt bondage and forced labor, including recruitment of children for use in armed conflict;\n\"(2) The use, procuring or offering of a child for prostitution, for the production of pornography, or for pornographic performances;\n\"(3) The use, procuring or offering of a child for the production and trafficking of drugs; and \"(4) The use, procuring or offering of a child for illegal activities or work which, by its nature or the circumstances in which it is carried out, is likely to harm their health, safety or morals; and \"(l) To organize or direct other persons to commit the offenses defined as acts of trafficking under this Act.\""}},{"id":"PH-H8816-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A new Section 4-A is hereby inserted in Republic Act No. 9208, to read as follows:\n\"SEC. 4-A. Attempted Trafficking in Persons. – Where there are acts to initiate the commission of a trafficking offense but the offender failed to or did not execute all the elements of the crime, by accident or by reason of some cause other than voluntary desistance, such overt acts shall be deemed as an attempt to commit an act of trafficking in persons. As such, an attempt to commit any of the offenses enumerated in Section 4 of this Act shall constitute attempted trafficking in persons.\n\"In cases where the victim is a child, any of the following acts shall also be deemed as attempted trafficking in persons:\n\"(a) Facilitating the travel of a child who travels alone to a foreign country or territory without valid reason therefor and without the required clearance or permit from the Department of Social Welfare and Development, or a written permit or justification from the child’s parent or legal guardian;\n\"(b) Executing, for a consideration, an affidavit of consent or a written consent for adoption;\n\"(c) Recruiting a woman to bear a child for the purpose of selling the child;\n\"(d) Simulating a birth for the purpose of selling the child; and \"(e) Soliciting a child and acquiring the custody thereof through any means from among hospitals, clinics, nurseries, daycare centers, refugee or evacuation centers, and low-income families, for the purpose of selling the child.\""}},{"id":"PH-H8816-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A new Section 4-B is hereby inserted in Republic Act No. 9208, to read as follows:\n\"SEC. 4-B. Accomplice Liability. – Whoever knowingly aids, abets, cooperates in the execution of the offense by previous or simultaneous acts defined in this Act shall be punished in accordance with the provisions of Section 10(c) of this Act.\""}},{"id":"PH-H8816-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A new Section 4-C is hereby inserted in Republic Act No. 9208, to read as follows:\n\"SEC. 4-C. Accessories. – Whoever has the knowledge of the commission of the crime, and without having participated therein, either as principal or as accomplices, take part in its commission in any of the following manners:\n\"(a) By profiting themselves or assisting the offender to profit by the effects of the crime;\n\"(b) By concealing or destroying the body of the crime or effects or instruments thereof, in order to prevent its discovery;\n\"(c) By harboring, concealing or assisting in the escape of the principal of the crime, provided the accessory acts with abuse of his or her public functions or is known to be habitually guilty of some other crime.\n\"Acts defined in this provision shall be punished in accordance with the provision of Section 10(d) as stated thereto.\""}},{"id":"PH-H8816-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 5 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 5. Acts that Promote Trafficking in Persons. – The following acts which promote or facilitate trafficking in persons, shall be unlawful:\n\"(a) xxx \"(b) To produce, print and issue or distribute unissued, tampered or fake counseling certificates, registration stickers, overseas employment certificates or other certificates of any government agency which issues these certificates, decals and such other markers as proof of compliance with government regulatory and pre-departure requirements for the purpose of promoting trafficking in persons;\n\"(c) xxx \"(d) xxx \"(e) xxx \"(f) xxx \"(g) xxx \"(h) To tamper with, destroy, or cause the destruction of evidence, or to influence or attempt to influence witnesses, in an investigation or prosecution of a case under this Act;\n\"(i) To destroy, conceal, remove, confiscate or possess, or attempt to destroy, conceal, remove, confiscate or possess, any actual or purported passport or other travel, immigration or working permit or document, or any other actual or purported government identification, of any person in order to prevent or restrict, or attempt to prevent or restrict, without lawful authority, the person’s liberty to move or travel in order to maintain the labor or services of that person; or \"(j) To utilize his or her office to impede the investigation, prosecution or execution of lawful orders in a case under this Act.\""}},{"id":"PH-H8816-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 6 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 6. Qualified Trafficking in Persons. – Violations of Section 4 of this Act shall be considered as qualified trafficking:\n\"x x x \"(d) When the offender is a spouse, an ascendant, parent, sibling, guardian or a person who exercises authority over the trafficked person or when the offense is committed by a public officer or employee;\n\"x x x \"(f) When the offender is a member of the military or law enforcement agencies;\n\"(g) When by reason or on occasion of the act of trafficking in persons, the offended party dies, becomes insane, suffers mutilation or is afflicted with Human Immunodeficiency Virus (HIV) or the Acquired Immune Deficiency Syndrome (AIDS);\n\"(h) When the offender commits one or more violations of Section 4 over a period of sixty (60) or more days, whether those days are continuous or not; and \"(i) When the offender directs or through another manages the trafficking victim in carrying out the exploitative purpose of trafficking.\""}},{"id":"PH-H8816-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 7 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 7. Confidentiality. – At any stage of the investigation, rescue, prosecution and trial of an offense under this Act, law enforcement officers, prosecutors, judges, court personnel, social workers and medical practitioners, as well as parties to the case, shall protect the right to privacy of the trafficked person. Towards this end, law enforcement officers, prosecutors and judges to whom the complaint has been referred may, whenever necessary to ensure a fair and impartial proceeding, and after considering all circumstances for the best interest of the parties, order a closed-door investigation, prosecution or trial. The name and personal circumstances of the trafficked person or any other information tending to establish the identity of the trafficked person and his or her family shall not be disclosed to the public.\n\"It shall be unlawful for any editor, publisher, and reporter or columnist in case of printed materials, announcer or producer in case of television and radio, producer and director of a film in case of the movie industry, or any person utilizing tri-media facilities or electronic information technology to cause publicity of the name, personal circumstances, or any information tending to establish the identity of the trafficked person except when the trafficked person in a written statement duly notarized knowingly, voluntarily and willingly waives said confidentiality.\n\"Law enforcement officers, prosecutors, judges, court personnel, social workers and medical practitioners shall be trained on the importance of maintaining confidentiality as a means to protect the right to privacy of victims and to encourage victims to file complaints.\""}},{"id":"PH-H8816-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 8 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 8. Initiation and Prosecution of Cases. – \"(a) Initiation of Investigation. – Law enforcement agencies are mandated to immediately initiate investigation and counter-trafficking-intelligence gathering upon receipt of statements or affidavit from victims of trafficking, migrant workers, or their families who are in possession of knowledge or information about trafficking in persons cases.\n\"(b) Prosecution of Cases. – Any person who has personal knowledge of the commission of any offense under this Act, such as the trafficked person, the parents, spouse, siblings, children or legal guardian may file a complaint for trafficking.\n\"(c) Affidavit of Desistance. – Cases involving trafficking in persons should not be dismissed based on the affidavit of desistance executed by the victims or their parents or legal guardians. Public and private prosecutors are directed to oppose and manifest objections to motions for dismissal.\n\"Any act involving the means provided in this Act or any attempt thereof for the purpose of securing an Affidavit of Desistance from the complainant shall be punishable under this Act.\""}},{"id":"PH-H8816-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 10 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 10. Penalties and Sanctions. – The following penalties and sanctions are hereby established for the offenses enumerated in this Act:\n\"(a) Any person found guilty of committing any of the acts enumerated in Section 4 shall suffer the penalty of imprisonment of twenty (20) years and a fine of not less than One million pesos (P1,000,000.00) but not more than Two million pesos (P2,000,000.00);\n\"(b) Any person found guilty of committing any of the acts enumerated in Section 4-A of this Act shall suffer the penalty of imprisonment of fifteen (15) years and a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00);\n\"(c) Any person found guilty of Section 4-B of this Act shall suffer the penalty of imprisonment of fifteen (15) years and a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00);\n\"In every case, conviction shall cause and carry the automatic revocation of the license or registration of the recruitment agency involved in trafficking. The license of a recruitment agency which trafficked a child shall be automatically revoked.\n\"(d) Any person found, guilty of committing any of the acts enumerated in Section 5 shall suffer the penalty of imprisonment of fifteen (15) years and a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00);\n\"(e) Any person found guilty of qualified trafficking under Section 6 shall suffer the penalty of life imprisonment and a fine of not less than Two million pesos (P2,000,000.00) but not more than Five million pesos (P5,000,000.00);\n\"(f) Any person who violates Section 7 hereof shall suffer the penalty of imprisonment of six (6) years and a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00);\n\"(g) If the offender is a corporation, partnership, association, club, establishment or any juridical person, the penalty shall be imposed upon the owner, president, partner, manager, and/or any responsible officer who participated in the commission of the crime or who shall have knowingly permitted or failed to prevent its commission;\n\"(h) The registration with the Securities and Exchange Commission (SEC) and license to operate of the erring agency, corporation, association, religious group, tour or travel agent, club or establishment, or any place of entertainment shall be cancelled and revoked permanently. The owner, president, partner or manager thereof shall not be allowed to operate similar establishments in a different name;\n\"(i) If the offender is a foreigner, he or she shall be immediately deported after serving his or her sentence and be barred permanently from entering the country;\n\"(j) Any employee or official of government agencies who shall issue or approve the issuance of travel exit clearances, passports, registration certificates, counseling certificates, marriage license, and other similar documents to persons, whether juridical or natural, recruitment agencies, establishments or other individuals or groups, who fail to observe the prescribed procedures and the requirement as provided for by laws, rules and regulations, shall be held administratively liable, without prejudice to criminal liability under this Act. The concerned government official or employee shall, upon conviction, be dismissed from the service and be barred permanently to hold public office. His or her retirement and other benefits shall likewise be forfeited; and \"(k) Conviction, by final judgment of the adopter for any offense under this Act shall result in the immediate rescission of the decree of adoption.\""}},{"id":"PH-H8816-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 11 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 11. Use of Trafficked Persons. – Any person who buys or engages the services of a trafficked person for prostitution shall be penalized with the following: Provided, That the Probation Law (Presidential Decree No. 968) shall not apply:\n\"(a) Prision Correccional in its maximum period to prision mayor or six (6) years to twelve (12) years imprisonment and a fine of not less than Fifty thousand pesos (P50,000.00) but not more than One hundred thousand pesos (P100,000.00): Provided, however, That the following acts shall be exempted thereto:\n\"(1) If an offense under paragraph (a) involves sexual intercourse or lascivious conduct with a child, the penalty shall be reclusion temporal in its medium period to reclusion perpetua or seventeen (17) years to forty (40) years imprisonment and a fine of not less than Five hundred thousand pesos (P500,000.00) but not more than One million pesos (P1,000,000.00);\n\"(2) If an offense under paragraph (a) involves carnal knowledge of, or sexual intercourse with, a male or female trafficking victim and also involves the use of force or intimidation, to a victim deprived of reason or to an unconscious victim, or a victim under twelve (12) years of age, instead of the penalty prescribed in the subparagraph above the penalty shall be a fine of not less than One million pesos (P1,000,000.00) but not more than Five million pesos (P5,000,000.00) and imprisonment of reclusion perpetua or forty (40) years imprisonment with no possibility of parole; except that if a person violating paragraph (a) of this section knows the person that provided prostitution services is in fact a victim of trafficking, the offender shall not be likewise penalized under this section but under Section 10 as a person violating Section 4; and if in committing such an offense, the offender also knows a qualifying circumstance for trafficking, the offender shall be penalized under Section 10 for qualified trafficking. If in violating this section the offender also violates Section 4, the offender shall be penalized under Section 10 and, if applicable, for qualified trafficking instead of under this section;\n\"(b) Deportation. – If a foreigner commits any offense described by paragraph (1) or (2) of this section or violates any pertinent provision of this Act as an accomplice or accessory to, or by attempting any such offense, he or she shall be immediately deported after serving his or her sentence and be barred permanently from entering the country; and \"(c) Public Official. – If the offender is a public official, he or she shall be dismissed from service and shall suffer perpetual absolute disqualification to hold public, office, in addition to any imprisonment or fine received pursuant to any other provision of this Act.\""}},{"id":"PH-H8816-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section 12 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 12. Prescriptive Period. – Trafficking cases under this Act shall prescribe in ten (10) years: Provided, however, That trafficking cases committed by a syndicate or in a large scale as defined under Section 6, or against a child, shall prescribe in twenty (20) years.\n\"The prescriptive period shall commence to run from the day on which the trafficked person is delivered or released from the conditions of bondage, or in the case of a child victim, from the day the child reaches the age of majority, and shall be interrupted by the filing of the complaint or information and shall commence to run again when the proceedings terminate without the accused being convicted or acquitted or are unjustifiably stopped for any reason not imputable to the accused.\""}},{"id":"PH-H8816-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 16 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 16. Programs that Address Trafficking in Persons. – The government shall establish and implement preventive, protective and rehabilitative programs for trafficked persons. For this purpose, the following agencies are hereby mandated to implement the following programs:\n\"(a) Department of Foreign Affairs (DFA) – shall make available its resources and facilities overseas for trafficked persons regardless of their manner of entry to the receiving country, and explore means to further enhance its assistance in eliminating trafficking activities through closer networking with government agencies in the country and overseas, particularly in the formulation of policies and implementation of relevant programs. It shall provide Filipino victims of trafficking overseas with free legal assistance and counsel to pursue legal action against his or her traffickers, represent his or her interests in any criminal investigation or prosecution, and assist in the application for social benefits and/or regular immigration status as may be allowed or provided for by the host country. The DFA shall repatriate trafficked Filipinos with the consent of the victims.\n\"The DFA shall take necessary measures for the efficient implementation of the Electronic Passporting System to protect the integrity of Philippine passports, visas and other travel documents to reduce the incidence of trafficking through the use of fraudulent identification documents.\n\"In coordination with the Department of Labor and Employment, it shall provide free temporary shelters and other services to Filipino victims of trafficking overseas through the migrant workers and other overseas Filipinos resource centers established overseas under Republic Act No. 8042, as amended.\n\"(b) Department of Social Welfare and Development (DSWD) – shall implement rehabilitative and protective programs for trafficked persons. It shall provide counseling and temporary shelter to trafficked persons and develop a system for accreditation among NGOs for purposes of establishing centers and programs for intervention in various levels of the community. It shall establish free temporary shelters, for the protection and housing of trafficked persons to provide the following basic services to trafficked persons:\n\"(1) Temporary housing and food facilities;\n\"(2) Psychological support and counseling;\n\"(3) 24-hour call center for crisis calls and technology-based counseling and referral system;\n\"(4) Coordination with local law enforcement entities; and \"(5) Coordination with the Department of Justice, among others.\n\"The DSWD must conduct information campaigns in communities and schools teaching parents and families that receiving consideration in exchange for adoption is punishable under the law. Furthermore, information campaigns must be conducted with the police that they must not induce poor women to give their children up for adoption in exchange for consideration.\n\"(c) Department of Labor and Employment (DOLE) – shall ensure the strict implementation and compliance with the rules and guidelines relative to the employment of persons locally and overseas. It shall likewise monitor, document and report cases of trafficking in persons involving employers and labor recruiters.\n\"(d) Department of Justice (DOJ) – shall ensure the prosecution of persons accused of trafficking and designate and train special prosecutors who shall handle and prosecute cases of trafficking. It shall also establish a mechanism for free legal assistance for trafficked persons, in coordination with the DSWD, Integrated Bar of the Philippines (IBP) and other NGOs and volunteer groups.\n\"(e) Philippine Commission on Women (PCW) – shall actively participate and coordinate in the formulation and monitoring of policies addressing the issue of trafficking in persons in coordination with relevant government agencies. It shall likewise advocate for the inclusion of the issue of trafficking in persons in both its local and international advocacy for women’s issues.\n\"(f) Bureau of Immigration (BI) – shall strictly administer and enforce immigration and alien administration laws. It shall adopt measures for the apprehension of suspected traffickers both at the place of arrival and departure and shall ensure compliance by the Filipino fiancés/fiancées and spouses of foreign nationals with the guidance and counseling requirement as provided for in this Act.\n\"(g) Philippine National Police (PNP) and National Bureau of Investigation (NBI) – shall be the primary law enforcement agencies to undertake surveillance, investigation and arrest of individuals or persons suspected to be engaged in trafficking. They shall closely coordinate with each other and with other law enforcement agencies to secure concerted efforts for effective investigation and apprehension of suspected traffickers. They shall also establish a system to receive complaints and calls to assist trafficked persons and conduct rescue operations.\n\"(h) Philippine Overseas Employment Administration (POEA) and Overseas Workers and Welfare Administration (OWWA) – POEA shall implement Pre-Employment Orientation Seminars (PEOS) while Pre-Departure Orientation Seminars (PDOS) shall be conducted by the OWWA. It shall likewise formulate a system of providing free legal assistance to trafficked persons, in coordination with the DFA.\n\"The POEA shall create a blacklist of recruitment agencies, illegal recruiters and persons facing administrative, civil and criminal complaints for trafficking filed in the receiving country and/or in the Philippines and those agencies, illegal recruiters and persons involved in cases of trafficking who have been rescued by the DFA and DOLE in the receiving country or in the Philippines even if no formal administrative, civil or criminal complaints have been filed: Provided, That the rescued victims shall execute an affidavit attesting to the acts violative of the anti-trafficking law. This blacklist shall be posted in conspicuous places in concerned government agencies and shall be updated bi-monthly.\n\"The blacklist shall likewise be posted by the POEA in the shared government information system, which is mandated to be established under Republic Act No. 8042, as amended.\n\"The POEA and OWWA shall accredit NGOs and other service providers to conduct PEOS and PDOS, respectively. The PEOS and PDOS should include the discussion and distribution of the blacklist.\n\"The license or registration of a recruitment agency that has been blacklisted may be suspended by the POEA upon a review of the complaints filed against said agency.\n\"(i) Department of the Interior and Local Government (DILG) – shall institute a systematic information and prevention campaign in coordination with pertinent agencies of government as provided for in this Act. It shall provide training programs to local government units, in coordination with the Council, in ensuring wide understanding and application of this Act at the local level.\n\"(j) Commission on Filipinos Overseas – shall conduct pre-departure counseling services for Filipinos in intermarriages. It shall develop a system for accreditation of NGOs that may be mobilized for purposes of conducting pre-departure counseling services for Filipinos in intermarriages. As such, it shall ensure that the counselors contemplated under this Act shall have the minimum qualifications and training of guidance counselors as provided for by law.\n\"It shall likewise assist in the conduct of information campaigns against trafficking in coordination with local government units, the Philippine Information Agency, and NGOs.\n\"(k) Local government units (LGUs) – shall monitor and document cases of trafficking in persons in their areas of jurisdiction, effect the cancellation of licenses of establishments which violate the provisions of this Act and ensure effective prosecution of such cases. They shall also undertake an information campaign against trafficking in persons through the establishment of the Migrants Advisory and Information Network (MAIN) desks in municipalities or provinces in coordination with the DILG, Philippine Information Agency (PIA), Commission on Filipinos Overseas (CFO), NGOs and other concerned agencies. They shall encourage and support community-based initiatives which address the trafficking in persons.\n\"In implementing this Act, the agencies concerned may seek and enlist the assistance of NGOs, people’s organizations (POs), civic organizations and other volunteer groups.\""}},{"id":"PH-H8816-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"A new Section 16-A is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 16-A. Anti-Trafficking in Persons Database. – An anti-trafficking in persons central database shall be established by the Inter-Agency Council Against Trafficking created under Section 20 of this Act. The Council shall submit a report to the President of the Philippines and to Congress, on or before January 15 of every year, with respect to the preceding year’s programs and data on trafficking-related cases.\n\"All government agencies tasked under the law to undertake programs and render assistance to address trafficking in persons shall develop their respective monitoring and data collection systems, and databases, for purposes of ensuring efficient collection and storage of data on cases of trafficking in persons handled by their respective offices. Such data shall be submitted to the Council for integration in a central database system.\n\"For this purpose, the Council is hereby tasked to ensure the harmonization and standardization of databases, including minimum data requirements, definitions, reporting formats, data collection systems, and data verification systems. Such databases shall have, at the minimum, the following information:\n\"(a) The number of cases of trafficking in persons, sorted according to status of cases, including the number of cases being investigated, submitted for prosecution, dropped, and filed and/or pending before the courts and the number of convictions and acquittals;\n\"(b) The profile/information on each case;\n\"(c) The number of victims of trafficking in persons referred to the agency by destination countries/areas and by area of origin; and \"(d) Disaggregated data on trafficking victims and the accused/defendants.\""}},{"id":"PH-H8816-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section 17 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 17. Legal Protection to Trafficked Persons. – Trafficked persons shall be recognized as victims of the act or acts of trafficking and as such, shall not be penalized for unlawful acts committed as a direct result of, or as an incident or in relation to, being trafficked based on the acts of trafficking enumerated in this Act or in obedience to the order made by the trafficker in relation thereto. In this regard, the consent of a trafficked person to the intended exploitation set forth in this Act shall be irrelevant.\n\"Victims of trafficking for purposes of prostitution as defined under Section 4 of this Act are not covered by Article 202 of the Revised Penal Code and as such, shall not be prosecuted, fined, or otherwise penalized under the said law.\""}},{"id":"PH-H8816-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"A new Section 17-A is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 17-A. Temporary Custody of Trafficked Victims. – The rescue of victims should be done as much as possible with the assistance of the DSWD or an accredited NGO that services trafficked victims. A law enforcement officer, on a reasonable suspicion that a person is a victim of any offense defined under this Act including attempted trafficking, shall immediately place that person in the temporary custody of the local social welfare and development office, or any accredited or licensed shelter institution devoted to protecting trafficked persons after the rescue.\""}},{"id":"PH-H8816-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"A new Section 17-B is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 17-B. Irrelevance of Past Sexual Behavior, Opinion Thereof or Reputation of Victims and of Consent of Victims in Cases of Deception, Coercion and Other Prohibited Means. – The past sexual behavior or the sexual predisposition of a trafficked person shall be considered inadmissible in evidence for the purpose of proving consent of the victim to engage in sexual behavior, or to prove the predisposition, sexual or otherwise, of a trafficked person. Furthermore, the consent of a victim of trafficking to the intended exploitation shall be irrelevant where any of the means set forth in Section 3(a) of this Act has been used.\""}},{"id":"PH-H8816-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"A new Section 17-C is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 17-C. Immunity from Suit, Prohibited Acts and Injunctive Remedies. – No action or suit shall be brought, instituted or maintained in any court or tribunal or before any other authority against any: (a) law enforcement officer; (b) social worker; or (c) person acting in compliance with a lawful order from any of the above, for lawful acts done or statements made during an authorized rescue operation, recovery or rehabilitation/intervention, or an investigation or prosecution of an anti-trafficking case: Provided, That such acts shall have been made in good faith.\n\"The prosecution of retaliatory suits against victims of trafficking shall be held in abeyance pending final resolution and decision of criminal complaint for trafficking.\n\"It shall be prohibited for the DFA, the DOLE, and the POEA officials, law enforcement officers, prosecutors and judges to urge complainants to abandon their criminal, civil and administrative complaints for trafficking.\n\"The remedies of injunction and attachment of properties of the traffickers, illegal recruiters and persons involved in trafficking may be issued motu proprio by judges.\""}},{"id":"PH-H8816-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Section 20 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 20. Inter-Agency Council Against Trafficking. – There is hereby established an Inter-Agency Council Against Trafficking, to be composed of the Secretary of the Department of Justice as Chairperson and the Secretary of the Department of Social Welfare and Development as Co-Chairperson and shall have the following as members:\n\"(a) Secretary, Department of Foreign Affairs;\n\"(b) Secretary, Department of Labor and Employment;\n\"(c) Secretary, Department of the Interior and Local Government;\n\"(d) Administrator, Philippine Overseas Employment Administration;\n\"(e) Commissioner, Bureau of Immigration;\n\"(f) Chief, Philippine National Police;\n\"(g) Chairperson, Philippine Commission on Women;\n\"(h) Chairperson, Commission on Filipinos Overseas;\n\"(i) Executive Director, Philippine Center for Transnational Crimes; and \"(j) Three (3) representatives from NGOs, who shall include one (1) representative each from among the sectors representing women, overseas Filipinos, and children, with a proven record of involvement in the prevention and suppression of trafficking in persons. These representatives shall be nominated by the government agency representatives of the Council, for appointment by the President for a term of three (3) years.\n\"The members of the Council may designate their permanent representatives who shall have a rank not lower than an assistant secretary or its equivalent to meetings, and shall receive emoluments as may be determined by the Council in accordance with existing budget and accounting rules and regulations.\""}},{"id":"PH-H8816-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Section 22 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 22. Secretariat to the Council. – The Department of Justice shall establish the necessary Secretariat for the Council.\n\"The secretariat shall provide support for the functions and projects of the Council. The secretariat shall be headed by an executive director, who shall be appointed by the Secretary of the DOJ upon the recommendation of the Council. The executive director must have adequate knowledge on, training and experience in the phenomenon of and issues involved in trafficking in persons and in the field of law, law enforcement, social work, criminology, or psychology.\n\"The executive director shall be under the supervision of the Inter-Agency Council Against Trafficking through its Chairperson and Co-Chairperson, and shall perform the following functions:\n\"(a) Act as secretary of the Council and administrative officer of its secretariat;\n\"(b) Advise and assist the Chairperson in formulating and implementing the objectives, policies, plans and programs of the Council, including those involving mobilization of government offices represented in the Council as well as other relevant government offices, task forces, and mechanisms;\n\"(c) Serve as principal assistant to the Chairperson in the overall supervision of council administrative business;\n\"(d) Oversee all council operational activities;\n\"(e) Ensure an effective and efficient performance of council functions and prompt implementation of council objectives, policies, plans and programs;\n\"(f) Propose effective allocations of resources for implementing council objectives, policies, plans and programs;\n\"(g) Submit periodic reports to the Council on the progress of council objectives, policies, plans and programs;\n\"(h) Prepare annual reports of all council activities; and \"(i) Perform other duties as the Council may assign.\""}},{"id":"PH-H8816-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"A new Section 26-A is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 26-A. Extra-Territorial Jurisdiction. – The State shall exercise jurisdiction over any act defined and penalized under this Act, even if committed outside the Philippines and whether or not such act or acts constitute an offense at the place of commission, the crime being a continuing offense, having been commenced in the Philippines and other elements having been committed in another country, if the suspect or accused:\n\"(a) Is a Filipino citizen; or \"(b) Is a permanent resident of the Philippines; or \"(c) Has committed the act against a citizen of the Philippines.\n\"No prosecution may be commenced against a person under this section if a foreign government, in accordance with jurisdiction recognized by the Philippines, has prosecuted or is prosecuting such person for the conduct constituting such offense, except upon the approval of the Secretary of Justice.\n\"The government may surrender or extradite persons accused of trafficking in the Philippines to the appropriate international court if any, or to another State pursuant to the applicable extradition laws and treaties.\""}},{"id":"PH-H8816-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Section 28 of Republic Act No. 9208 is hereby amended, to read as follows:\n\"SEC. 28. Funding. – The amount necessary to implement the provisions of this Act shall be charged against the current year’s appropriations of the Inter-Agency Council Against Trafficking under the budget of the DOJ and the appropriations of the other concerned departments. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act.\""}},{"id":"PH-H8816-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"A new Section 28-A is hereby inserted into Republic Act No. 9208, to read as follows:\n\"SEC. 28-A. Additional Funds for the Council. – The amount collected from every penalty, fine or asset derived from any violation of this Act shall be earmarked as additional funds for the use of the Council. The fund may be augmented by grants, donations and endowment from various sources, domestic or foreign, for purposes related to their functions, subject to the existing accepted rules and regulations of the Commission on Audit.\""}},{"id":"PH-H8816-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Section 32 of Republic Act No. 9208 of the Repealing Clause is hereby amended to read as follows:\n\"SEC. 32. Repealing Clause. – Article 202 of the Revised Penal Code, as amended, and all laws, acts, presidential decrees, executive orders, administrative orders, rules and regulations inconsistent with or contrary to the provisions of this Act are deemed amended, modified or repealed accordingly: Provided, That this Act shall not in any way amend or repeal the provisions of Republic Act No. 7610, otherwise known as the ‘Special Protection of Child Against Child Abuse, Exploitation and Discrimination Act.’\""}},{"id":"PH-H8816-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Section 33 of Republic Act No. 9208 is hereby amended to read as follows:\n\"SEC. 33. Effectivity. – This Act shall take effect fifteen (15) days following its complete publication in at least two (2) newspapers of general circulation.\""}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expanding Republic Act No. 9208, Entitled \"An Act to Institute Policies to Eliminate Trafficking in Persons Especially Women and Children, Establishing the Necessary Institutional Mechanisms for the Protection and Support of Trafficked Persons, Providing Penalties for its Violations and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8817"] = {"id":"PH-H8817","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10365_2013.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"2001 年反洗钱法","en":"Anti-Money Laundering Act of 2001","orig":"An Act Further Strengthening the Anti-Money Laundering Law, Amending for the Purpose Republic Act No. 9160, Otherwise Known as the \"Anti-Money Laundering Act of 2001\", as Amended","vi":"Đạo luật Chống Rửa tiền năm 2001","th":"พระราชบัญญัติป้องกันและปราบปรามการฟอกเงิน ค.ศ. 2001","id":"Undang-Undang Pencegahan dan Pemberantasan Tindak Pidana Pencucian Uang Tahun 2001","ms":"Akta Pencegahan Pengubahan Wang Haram 2001"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 10365","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-15","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10365_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8817-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 3(a) of Republic Act No. 9160, as amended, is hereby amended to read as follows:\n\"(a) ‘Covered persons’, natural or juridical, refer to:\n\"(1) banks, non-banks, quasi-banks, trust entities, foreign exchange dealers, pawnshops, money changers, remittance and transfer companies and other similar entities and all other persons and their subsidiaries and affiliates supervised or regulated by the Bangko Sentral ng Pilipinas (BSP);\n\"(2) insurance companies, pre-need companies and all other persons supervised or regulated by the Insurance Commission (IC);\n\"(3) (i) securities dealers, brokers, salesmen, investment houses and other similar persons managing securities or rendering services as investment agent, advisor, or consultant, (ii) mutual funds, close-end investment companies, common trust funds, and other similar persons, and (iii) other entities administering or otherwise dealing in currency, commodities or financial derivatives based thereon, valuable objects, cash substitutes and other similar monetary instruments or property supervised or regulated by the Securities and Exchange Commission (SEC);\n\"(4) jewelry dealers in precious metals, who, as a business, trade in precious metals, for transactions in excess of One million pesos (P1,000,000.00);\n\"(5) jewelry dealers in precious stones, who, as a business, trade in precious stones, for transactions in excess of One million pesos (P1,000,000.00);\n\"(6) company service providers which, as a business, provide any of the following services to third parties: (i) acting as a formation agent of juridical persons; (ii) acting as (or arranging for another person to act as) a director or corporate secretary of a company, a partner of a partnership, or a similar position in relation to other juridical persons; (iii) providing a registered office, business address or accommodation, correspondence or administrative address for a company, a partnership or any other legal person or arrangement; and (iv) acting as (or arranging for another person to act as) a nominee shareholder for another person; and \"(7) persons who provide any of the following services:\n(i) managing of client money, securities or other assets;\n(ii) management of bank, savings or securities accounts;\n(iii) organization of contributions for the creation, operation or management of companies; and\n(iv) creation, operation or management of juridical persons or arrangements, and buying and selling business entities.\n\"Notwithstanding the foregoing, the term ‘covered persons’ shall exclude lawyers and accountants acting as independent legal professionals in relation to information concerning their clients or where disclosure of information would compromise client confidences or the attorney-client relationship: Provided, That these lawyers and accountants are authorized to practice in the Philippines and shall continue to be subject to the provisions of their respective codes of conduct and/or professional responsibility or any of its amendments.\""}},{"id":"PH-H8817-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 3(i) of the same Act is hereby amended to read as follows:\n\"(i) ‘Unlawful activity’ refers to any act or omission or series or combination thereof involving or having direct relation to the following:\n\"(1) Kidnapping for ransom under Article 267 of Act No. 3815, otherwise known as the Revised Penal Code, as amended;\n\"(2) Sections 4, 5, 6, 8, 9, 10, 11, 12, 13, 14, 15 and 16 of Republic Act No. 9165, otherwise known as the Comprehensive Dangerous Drugs Act of 2002;\n\"(3) Section 3 paragraphs B, C, E, G, H and I of Republic Act No. 3019, as amended, otherwise known as the Anti-Graft and Corrupt Practices Act;\n\"(4) Plunder under Republic Act No. 7080, as amended;\n\"(5) Robbery and extortion under Articles 294, 295, 296, 299, 300, 301 and 302 of the Revised Penal Code, as amended;\n\"(6) Jueteng and Masiao punished as illegal gambling under Presidential Decree No. 1602;\n\"(7) Piracy on the high seas under the Revised Penal Code, as amended and Presidential Decree No. 532;\n\"(8) Qualified theft under Article 310 of the Revised Penal Code, as amended;\n\"(9) Swindling under Article 315 and Other Forms of Swindling under Article 316 of the Revised Penal Code, as amended;\n\"(10) Smuggling under Republic Act Nos. 455 and 1937;\n\"(11) Violations of Republic Act No. 8792, otherwise known as the Electronic Commerce Act of 2000;\n\"(12) Hijacking and other violations under Republic Act No. 6235; destructive arson and murder, as defined under the Revised Penal Code, as amended;\n\"(13) Terrorism and conspiracy to commit terrorism as defined and penalized under Sections 3 and 4 of Republic Act No. 9372;\n\"(14) Financing of terrorism under Section 4 and offenses punishable under Sections 5, 6, 7 and 8 of Republic Act No. 10168, otherwise known as the Terrorism Financing Prevention and Suppression Act of 2012:\n\"(15) Bribery under Articles 210, 211 and 211-A of the Revised Penal Code, as amended, and Corruption of Public Officers under Article 212 of the Revised Penal Code, as amended;\n\"(16) Frauds and Illegal Exactions and Transactions under Articles 213, 214, 215 and 216 of the Revised Penal Code, as amended;\n\"(17) Malversation of Public Funds and Property under Articles 217 and 222 of the Revised Penal Code, as amended;\n\"(18) Forgeries and Counterfeiting under Articles 163, 166, 167, 168, 169 and 176 of the Revised Penal Code, as amended;\n\"(19) Violations of Sections 4 to 6 of Republic Act No. 9208, otherwise known as the Anti-Trafficking in Persons Act of 2003;\n\"(20) Violations of Sections 78 to 79 of Chapter IV, of Presidential Decree No. 705, otherwise known as the Revised Forestry Code of the Philippines, as amended;\n\"(21) Violations of Sections 86 to 106 of Chapter VI, of Republic Act No. 8550, otherwise known as the Philippine Fisheries Code of 1998;\n\"(22) Violations of Sections 101 to 107, and 110 of Republic Act No. 7942, otherwise known as the Philippine Mining Act of 1995;\n\"(23) Violations of Section 27(c), (e), (f), (g) and (i), of Republic Act No. 9147, otherwise known as the Wildlife Resources Conservation and Protection Act;\n\"(24) Violation of Section 7(b) of Republic Act No. 9072, otherwise known as the National Caves and Cave Resources Management Protection Act;\n\"(25) Violation of Republic Act No. 6539, otherwise known as the Anti-Carnapping Act of 2002, as amended;\n\"(26) Violations of Sections 1, 3 and 5 of Presidential Decree No. 1866, as amended, otherwise known as the decree Codifying the Laws on Illegal/Unlawful Possession, Manufacture, Dealing In, Acquisition or Disposition of Firearms, Ammunition or Explosives;\n\"(27) Violation of Presidential Decree No. 1612, otherwise known as the Anti-Fencing Law;\n\"(28) Violation of Section 6 of Republic Act No. 8042, otherwise known as the Migrant Workers and Overseas Filipinos Act of 1995, as amended by Republic Act No. 10022;\n\"(29) Violation of Republic Act No. 8293, otherwise known as the Intellectual Property Code of the Philippines;\n\"(30) Violation of Section 4 of Republic Act No. 9995, otherwise known as the Anti-Photo and Video Voyeurism Act of 2009;\n\"(31) Violation of Section 4 of Republic Act No. 9775, otherwise known as the Anti-Child Pornography Act of 2009;\n\"(32) Violations of Sections 5, 7, 8, 9, 10(c), (d) and (e), 11, 12 and 14 of Republic Act No. 7610, otherwise known as the Special Protection of Children Against Abuse, Exploitation and Discrimination;\n\"(33) Fraudulent practices and other violations under Republic Act No. 8799, otherwise known as the Securities Regulation Code of 2000; and \"(34) Felonies or offenses of a similar nature that are punishable under the penal laws of other countries.\""}},{"id":"PH-H8817-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 3 of the same Act shall have new paragraphs (j) and (k).\n\"(j) Precious metals’ shall mean gold, silver, platinum, palladium, rhodium, ruthenium, iridium and osmium. These include alloys of precious metals, solders and plating chemicals such as rhodium and palladium plating solutions and potassium gold cyanide and potassium silver cyanide and silver cyanide in salt solution.\n\"(k) ‘Precious stones’ shall mean diamond, ruby, emerald, sapphire, opal, amethyst, beryl, topaz, and garnet that are used in jewelry making, including those formerly classified as semi-precious stones.\""}},{"id":"PH-H8817-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 4 of the same Act is hereby amended to read as follows:\n\"SEC. 4. Money Laundering Offense. – Money laundering is committed by any person who, knowing that any monetary instrument or property represents, involves, or relates to the proceeds of any unlawful activity:\n\"(a) transacts said monetary instrument or property;\n\"(b) converts, transfers, disposes of, moves, acquires, possesses or uses said monetary instrument or property;\n\"(c) conceals or disguises the true nature, source, location, disposition, movement or ownership of or rights with respect to said monetary instrument or property;\n\"(d) attempts or conspires to commit money laundering offenses referred to in paragraphs (a), (b) or (c);\n\"(e) aids, abets, assists in or counsels the commission of the money laundering offenses referred to in paragraphs (a), (b) or (c) above; and \"(f) performs or fails to perform any act as a result of which he facilitates the offense of money laundering referred to in paragraphs (a), (b) or (c) above.\n\"Money laundering is also committed by any covered person who, knowing that a covered or suspicious transaction is required under this Act to be reported to the Anti-Money Laundering Council (AMLC), fails to do so.\""}},{"id":"PH-H8817-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 6(a) of the same Act is hereby amended to read as follows:\n\"SEC. 6. Prosecution of Money Laundering. – \"(a) Any person may be charged with and convicted of both the offense of money laundering and the unlawful activity as herein defined.\n\"(b) The prosecution of any offense or violation under this Act shall proceed independently of any proceeding relating to the unlawful activity.\""}},{"id":"PH-H8817-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 7 of the same Act is hereby amended to read as follows:\n\"SEC. 7. Creation of Anti-Money Laundering Council (AMLC). – The Anti-Money Laundering Council is hereby created and shall be composed of the Governor of the Bangko Sentral ng Pilipinas as Chairman, the Commissioner of the Insurance Commission and the Chairman of the Securities and Exchange Commission, as members. The AMLC shall act unanimously in the discharge of its functions as defined hereunder:\n\"x x x \"(6) to apply before the Court of Appeals, ex parte, for the freezing of any monetary instrument or property alleged to be laundered, proceeds from, or instrumentalities used in or intended for use in any unlawful activity as defined in Section 3(i) hereof;\n\"x x x \"(12) to require the Land Registration Authority and all its Registries of Deeds to submit to the AMLC, reports on all real estate transactions involving an amount in excess of Five hundred thousand pesos (P500,000.00) within fifteen (15) days from the date of registration of the transaction, in a form to be prescribed by the AMLC. The AMLC may also require the Land Registration Authority and all its Registries of Deeds to submit copies of relevant documents of all real estate transactions.\""}},{"id":"PH-H8817-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 9(c), paragraphs 1 and 4 of the same Act are hereby amended to read as follows:\n\"SEC. 9. Prevention of Money Laundering; Customer Identification Requirements and Record Keeping. – \"(a) x x x \"(b) x x x \"(c) Reporting of Covered and Suspicious Transactions. – Covered persons shall report to the AMLC all covered transactions and suspicious transactions within five (5) working days from occurrence thereof, unless the AMLC prescribes a different period not exceeding fifteen (15) working days.\n\"Lawyers and accountants acting as independent legal professionals are not required to report covered and suspicious transactions if the relevant information was obtained in circumstances where they are subject to professional secrecy or legal professional privilege.\n\"x x x \"x x x \"When reporting covered or suspicious transactions to the AMLC, covered persons and their officers and employees are prohibited from communicating, directly or indirectly, in any manner or by any means, to any person or entity, the media, the fact that a covered or suspicious transaction has been reported or is about to be reported, the contents of the report, or any other information in relation thereto. Neither may such reporting be published or aired in any manner or form by the mass media\", electronic mail, or other similar devices. In case of violation thereof, the concerned officer and employee of the covered person and media shall be held criminally liable.\""}},{"id":"PH-H8817-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 10 of the same Act, as amended by Republic Act No. 10167, is hereby amended to read as follows:\n\"SEC. 10. Freezing of Monetary Instrument or Property. – Upon a verified ex parte petition by the AMLC and after determination that probable cause exists that any monetary instrument or property is in any way related to an unlawful activity as defined in Section 3(i) hereof, the Court of Appeals may issue a freeze order which shall be effective immediately, and which shall not exceed six (6) months depending upon the circumstances of the case: Provided, That if there is no case filed against a person whose account has been frozen within the period determined by the court, the freeze order shall be deemed ipso facto lifted: Provided, further, That this new rule shall not apply to pending cases in the courts. In any case, the court should act on the petition to freeze within twenty-four (24) hours from filing of the petition. If the application is filed a day before a nonworking day, the computation of the twenty-four (24)-hour period shall exclude the nonworking days.\n\"A person whose account has been frozen may file a motion to lift the freeze order and the court must resolve this motion before the expiration of the freeze order.\n\"No court shall issue a temporary restraining order or a writ of injunction against any freeze order, except the Supreme Court.\""}},{"id":"PH-H8817-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 12 of the same Act is hereby amended to read as follows:\n\"(a) Civil Forfeiture. – Upon determination by the AMLC that probable cause exists that any monetary instrument or property is in any way related to an unlawful activity as defined in Section 3(i) or a money laundering offense under Section 4 hereof, the AMLC shall file with the appropriate court through the Office of the Solicitor General, a verified ex parte petition for forfeiture, and the Rules of Court on Civil Forfeiture shall apply.\n\"The forfeiture shall include those other monetary instrument or property having an equivalent value to that of the monetary instrument or property found to be related in any way to an unlawful activity or a money laundering offense, when with due diligence, the former cannot be located, or it has been substantially altered, destroyed, diminished in value or otherwise rendered worthless by any act or omission, or it has been concealed, removed, converted, or otherwise transferred, or it is located outside the Philippines or has been placed or brought outside the jurisdiction of the court, or it has been commingled with other monetary instrument or property belonging to either the offender himself or a third person or entity, thereby rendering the same difficult to identify or be segregated for purposes of forfeiture.\n\"(b) Claim on Forfeited Assets. – Where the court has issued an order of forfeiture of the monetary instrument or property in a criminal prosecution for any money laundering offense defined under Section 4 of this Act, the offender or any other person claiming an interest therein may apply, by verified petition, for a declaration that the same legitimately belongs to him and for segregation or exclusion of the monetary instrument or property corresponding thereto. The verified petition shall be filed with the court which rendered the judgment of forfeiture, within fifteen (15) days from the date of the finality of the order of forfeiture, in default of which the said order shall become final and executor. This provision shall apply in both civil and criminal forfeiture.\n\"(c) Payment in Lieu of Forfeiture. – Where the court has issued an order of forfeiture of the monetary instrument or property subject of a money laundering offense defined under Section 4, and said order cannot be enforced because any particular monetary instrument or property cannot, with due diligence, be located, or it has been substantially altered, destroyed, diminished in value or otherwise rendered worthless by any act or omission, directly or indirectly, attributable to the offender, or it has been concealed, removed, converted, or otherwise transferred to prevent the same from being found or to avoid forfeiture thereof, or it is located outside the Philippines or has been placed or brought outside the jurisdiction of the court, or it has been commingled with other monetary instruments or property belonging to either the offender himself or a third person or entity, thereby rendering the same difficult to identify or be segregated for purposes of forfeiture, the court may, instead of enforcing the order of forfeiture of the monetary instrument or property or part thereof or interest therein, accordingly order the convicted offender to pay an amount equal to the value of said monetary instrument or property. This provision shall apply in both civil and criminal forfeiture.\""}},{"id":"PH-H8817-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 14 of the same Act, as amended, is hereby further amended to read as follows:\n\"SEC. 14. Penal Provisions. – (a) Penalties for the Crime of Money Laundering. The penalty of imprisonment ranging from seven (7) to fourteen (14) years and a fine of not less than Three million Philippine pesos (Php3,000,000.00) but not more than twice the value of the monetary instrument or property involved in the offense, shall be imposed upon a person convicted under Section 4(a), (b), (c) and (d) of this Act.\n\"The penalty of imprisonment from four (4) to seven (7) years and a fine of not less than One million five hundred thousand Philippine pesos (Php1,500,000.00) but not more than Three million Philippine pesos (Php3,000,000.00), shall be imposed upon a person convicted under Section 4(e) and (f) of this Act.\n\"The penalty of imprisonment from six (6) months to four (4) years or a fine of not less than One hundred thousand Philippine pesos (Php100,000.00) but not more than Five hundred thousand Philippine pesos (Php500,000.00), or both, shall be imposed on a person convicted under the last paragraph of Section 4 of this Act.\n\"(b) x x x \"(c) x x x \"(d) x x x \"(e) The penalty of imprisonment ranging from four (4) to seven (7) years and a fine corresponding to not more than two hundred percent (200%) of the value of the monetary instrument or property laundered shall be imposed upon the covered person, its directors, officers or pesonnel who knowingly participated in the commission of the crime of money laundering.\n\"(f) Imposition of Administrative Sanctions. The imposition of the administrative sanctions shall be without prejudice to the filing of criminal charges against the persons responsible for the violation.\n\"After due notice and hearing, the AMLC shall, at its discretion, impose sanctions, including monetary penalties, warning or reprimand, upon any covered person, its directors, officers, employees or any other person for the violation of this Act, its implementing rules and regulations, or for failure or refusal to comply with AMLC orders, resolutions and other issuances. Such monetary penalties shall be in amounts as may be determined by the AMLC to be appropriate, which shall not be more than Five hundred thousand Philippine pesos (P500,000.00) per violation.\n\"The AMLC may promulgate rules on fines and penalties taking into consideration the attendant circumstances, such as the nature and gravity of the violation or irregularity.\n\"(g) The provision of this law shall not be construed or implemented in a manner that will discriminate against certain customer types, such as politically-exposed persons, as well as their relatives, or against a certain religion, race or ethnic origin, or such other attributes or profiles when used as the only basis to deny these persons access to the services provided by the covered persons. Whenever a bank, or quasi-bank, financial institution or whenever any person or entity commits said discriminatory act, the person or persons responsible for such violation shall be subject to sanctions as may be deemed appropriate by their respective regulators.\""}},{"id":"PH-H8817-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"New sections are hereby inserted after Section 19 of the same Act, as amended, to read as follows:\n\"SEC. 20. Non-intervention in the Bureau of Internal Revenue (BIR) Operations. – Nothing contained in this Act nor in related antecedent laws or existing agreements shall be construed to allow the AMLC to participate in any manner in the operations of the BIR.\"\n\"SEC. 21. The authority to inquire into or examine the main account and the related accounts shall comply with the requirements of Article III, Sections 2 and 3 of the 1987 Constitution, which are hereby incorporated by reference. Likewise, the constitutional injunction against ex post facto laws and bills of attainder shall be respected in the implementation of this Act.\""}},{"id":"PH-H8817-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The succeeding sections are hereby renumbered accordingly."}},{"id":"PH-H8817-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. – If any provision of this Act is declared unconstitutional, the same shall not affect the validity and effectivity of the other provisions hereof."}},{"id":"PH-H8817-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. – All laws, decrees, orders, and issuances or portions thereof, which are inconsistent with the provisions of this Act, are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8817-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days following its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Anti-Money Laundering Act of 2001","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8818"] = {"id":"PH-H8818","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10366_2013.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"授权选举委员会设立专供残疾人与老年人使用的无障碍投票所投票区的法案","en":"An Act Authorizing the Commission on Elections to Establish Precincts Assigned to Accessible Polling Places Exclusively for Persons With Disabilities and Senior Citizens","orig":"An Act Authorizing the Commission on Elections to Establish Precincts Assigned to Accessible Polling Places Exclusively for Persons With Disabilities and Senior Citizens"},"level":"law","status":"active","topics":["civil","administrative"],"docNumber":"Republic Act No. 10366","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-15","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10366_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8818-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section Declaration of Policy. – The State shall ensure that persons with disabilities and senior citizens are able to exercise their right to political participation without discrimination or restrictions. Towards this end, the State shall design systems and procedures that will enable persons with disabilities and senior citizens to register and vote by themselves."}},{"id":"PH-H8818-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section Definition of Terms. – As used in this Act, the term:\n(a) Commission refers to the Commission on Elections.\n(b) Persons with Disabilities refer to qualified voters who have long-term physical, mental, intellectual or sensory impairments which in interaction with various barriers may hinder their full and effective participation in the electoral processes on an equal basis with others.\n(c) Senior Citizens refer to qualified voters who are sixty (60) years or older.\n(d) Electoral Processes refer to election-related activities and proceedings including registration, candidacy, campaign, voter education and casting of vote.\n(e) Assistance refers to any support or aid that may be extended to persons with disabilities and senior citizens for them to meaningfully and effectively participate in the electoral processes.\n(f) Discrimination on the basis of disability means any distinction, exclusion or restriction on the basis of disability which has the effect of impairing or nullifying the recognition, enjoyment, or exercise, on an equal basis with others, of all human rights and fundamental freedoms, including denial of reasonable accommodation.\n(g) Universal design means the design of products, environments, programs and services, to be usable by all people, to the greatest extent possible, without the need for adaptation or specialized design but shall not exclude assistive devices for particular groups of persons with disabilities where this is needed.\n(h) Satellite registration refers to registration conducted by an Election Officer in established satellite offices located in a public place within his or her area of jurisdiction. It accepts application for registration, transfer or transfer with reactivation, reactivation of registration records, change or correction of entries and validation of registration from all registrants or voters residing within the Election Officer’s territorial jurisdiction.\n(i) Special registration refers to registration conducted in established satellite offices by a special registration team designated by the Commission. It exclusively caters to first time person with disability and senior citizen registrants residing outside the area of jurisdiction of the regular Election Officer conducting the satellite registration.\n(j) Accessible polling place refers to the venue where the Board of Election Inspectors (BEIs) conducts election-related proceedings and where the voters cast their votes. The accessible polling place shall he located at the ground floor, preferably near the entrance of the building, and is free of any physical barriers and provided with necessary services, including assistive devices."}},{"id":"PH-H8818-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section Right to Participation in Electoral Processes. – The State shall guarantee the political rights of persons with disabilities and senior citizens, in line with the concept of universal design, by:\n(a) Ensuring that voting procedures, facilities and materials are appropriate, accessible, and easy to understand and use;\n(b) Protecting the right of persons with disabilities and senior citizens to vote by secret ballot in elections without intimidation, facilitating the use of assistive and new technologies where appropriate; and\n(c) Guaranteeing the free expression, in the exercise of the right of suffrage, of persons with disabilities and senior citizens, allowing assistance in voting by a person of their own choice."}},{"id":"PH-H8818-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section Duty of the Commission to Render Assistance to Persons with Disabilities and Senior Citizens. – It shall be the duty of the Commission to render appropriate assistance to persons with disabilities and senior citizens in coordination with government agencies and civil society organizations."}},{"id":"PH-H8818-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section Record of Persons with Disabilities and Senior Citizens. – The Commission shall keep an updated record of persons with disabilities and senior citizens who are registered as voters, which indicates the types of disability and the assistance they need, to assist it in determining policy directions for more inclusive and accessible electoral processes. The record shall be made accessible to concerned government offices, accredited citizens’ arms, civil society monitoring groups and other organizations which promote the rights of the persons with disabilities and senior citizens, subject to specific guidelines the Commission may promulgate to protect the privacy of the individuals concerned."}},{"id":"PH-H8818-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section Registration and Updating of Records. – In designing the forms, the Commission must ensure that persons with disabilities and senior citizens applying for registration, reactivation, transfer, or correction of entry indicate the type(s) of disability, as well as the form(s) of assistance needed.\nPersons with disabilities and senior citizens who have previously registered but have not indicated the type of disability, or who may have developed or manifested such disability after having been registered, shall be allowed, during the periods to file applications for registration, to update their registration records, and to indicate the type of disability as well as the form of assistance they need during election day. The Commission may design registration forms specifically for persons with disabilities and senior citizens, or issue supplemental forms for the said purpose, and provide for procedures to be followed by those who need to update their registration records."}},{"id":"PH-H8818-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section Assistance in the Accomplishment of Application Form. – A person with disability or senior citizen who cannot by himself or herself accomplish an application for registration, by reason of illiteracy or physical disability, shall be assisted by the Election Officer in the preparation of his or her application form, or by any member of an accredited citizens’ arm, or by a relative by consanguinity or affinity within the fourth civil degree, or if he or she has none present, by any person of his or her confidence who belongs to the same household."}},{"id":"PH-H8818-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section Satellite and Special Registration. – The Commission, in coordination with national government agencies and local government units, person with disability and senior citizen organizations, and other cause-oriented groups, shall conduct satellite and/or special registration for persons with disabilities and senior citizens in accessible places."}},{"id":"PH-H8818-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section Creation of Precincts for Persons with Disabilities and Senior Citizens. – The Commission is hereby authorized to establish precincts of a nonterritorial nature, exclusively for persons with disabilities and senior citizens who in their registration records manifest their intent to avail of their right to a separate precinct under this section. Pursuant hereto, the Commission shall establish at least one (1) such precinct, assigned to accessible polling places, for every voting center. Such precincts shall be provided with assistive devices as well as the services of experts in assisting persons with disabilities."}},{"id":"PH-H8818-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section Ballot Design. – In designing the ballot, the Commission shall ensure reasonable accommodation to persons with disabilities and senior citizens to enable them to accomplish the ballots by themselves."}},{"id":"PH-H8818-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section Assistance in the Accomplishment of the Ballot. – A person with disability or senior citizen who is illiterate or physically unable to prepare the ballot by himself or herself may be assisted in the preparation of his or her ballot by a relative by consanguinity or affinity within the fourth civil degree, or if he or she has none, by any person of his or her confidence who belongs to the same household, or by any member of the BEls. For this purpose, the person who usually assists the person with disability or senior citizen, such as a personal assistant, a caregiver or a nurse shall be considered a member of his or her household: Provided, That no voter shall be allowed to have an assistor on the basis of illiteracy or physical disability unless it is so indicated in his or her registration record. Nevertheless, if the physical inability to prepare the ballot is manifest, obvious, or visible, said voter shall be allowed to be assisted in accomplishing the ballot by a qualified assistor, even if not stated or indicated in the registration record: Provided, further, That the assistor must be of voting age.\nThe assistor shall hind himself or herself in a formal document under oath to fill out the ballot strictly in accordance with the instructions of the voter and not to reveal the contents of the ballot prepared by him or her, and shall prepare the ballot for the voter inside the voting booth. Except for the members of the BEIs, no assistor can assist for more than three (3) times. Any violation of this provision shall constitute an election offense punishable under Section 262 of the Omnibus Election Code."}},{"id":"PH-H8818-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section Sensitivity Training Program. – The Commission, in coordination with the National Council on Disability Affairs (NCDA), the Commission on Human Rights (CHR), and person with disability and senior citizen organizations, shall organize, design, and implement sensitivity trainings to persons performing electoral duties, including the Commission field officers, members of the BEIs, and accredited citizens’ arms to familiarize them with the needs of the persons with disabilities and senior citizens."}},{"id":"PH-H8818-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section Information Materials. – The Commission shall ensure that information materials relating to the electoral processes are appropriate and accessible to persons with disabilities and senior citizens."}},{"id":"PH-H8818-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section Appropriations. – The initial funding of this Act shall be charged against, the current year’s appropriations or from any available savings of the Commission. Thereafter, such amount as may be necessary for the continued implementation of this Act shall he included in the annual General Appropriations Act."}},{"id":"PH-H8818-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section Implementing Rules and Regulations. – Within sixty (60) days from the effectivity of this Act, the Commission shall promulgate the implementing rules and regulations."}},{"id":"PH-H8818-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section Separability Clause. – Should any provision of this Act he declared invalid or unconstitutional, the validity or constitutionality of the other provisions shall not be affected thereby."}},{"id":"PH-H8818-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section Repealing Clause. – All laws, presidential decrees, executive orders, resolutions, rules and regulations or parts thereof which are inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8818-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Section Effectivity Clause. – This Act shall take effect on July 1, 2013, after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Commission on Elections to Establish Precincts Assigned to Accessible Polling Places Exclusively for Persons With Disabilities and Senior Citizens","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8819"] = {"id":"PH-H8819","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10367_2013.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"规定强制性生物识别选民登记的法案","en":"An Act Providing for Mandatory Biometrics Voter Registration","orig":"An Act Providing for Mandatory Biometrics Voter Registration"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10367","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-15","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10367_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8819-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. – It is the policy of the State to establish a clean, complete, permanent and updated list of voters through the adoption of biometric technology."}},{"id":"PH-H8819-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. – As used in this Act:\n(a) Commission refers to the Commission on Elections (COMELEC).\n(b) Biometrics refers to the quantitative analysis that provides a positive identification of an individual such as voice, photograph, fingerprint, signature, iris and/or such other identifiable features.\n(c) Data Capture Machine (DCM) is the device which captures the biometrics of an individual.\n(d) Validation is the process of taking the biometrics of registered voters whose biometrics have not yet been captured.\n(e) Deactivation refers to the removal of the registration record of the registered voter from the corresponding precinct book of voters for failure to comply with the validation process as required by this Act.\n(f) Reactivation refers to the reinstatement of a deactivated voter."}},{"id":"PH-H8819-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Who Shall Submit for Validation. – Registered voters whose biometrics have not been captured shall submit themselves for validation."}},{"id":"PH-H8819-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Who Shall Conduct the Validation. – The City or Municipal Election Officer shall conduct the validation."}},{"id":"PH-H8819-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Commencement of Validation. – The Commission shall conduct validation beginning July 1, 2013, consistent with the continuing registration under Republic Act No. 8189."}},{"id":"PH-H8819-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Publication and Notice Requirement. – The Commission shall cause the publication of the commencement of the validation in two (2) newspapers of general circulation. The City or Municipal Election Officer shall serve individual written notices by registered mail with return card to the voters concerned at their latest address in the voter’s registration record and post the list of the voters concerned in the city or municipal bulletin board and in the local COMELEC office."}},{"id":"PH-H8819-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Deactivation. – Voters who fail to submit for validation on or before the last day of filing of application for registration for purposes of the May 2016 elections shall be deactivated pursuant to this Act."}},{"id":"PH-H8819-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Reactivation. – Those deactivated under the preceding section may apply for reactivation after the May 2016 elections following the procedure provided in Section 28 of Republic Act No. 8189."}},{"id":"PH-H8819-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Database Security. – The database generated by biometric registration shall be secured by the Commission and shall not be used, under any circumstance, for any purpose other than for electoral exercises."}},{"id":"PH-H8819-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Mandatory Biometrics Registration. – The Commission shall implement a mandatory biometrics registration system for new voters."}},{"id":"PH-H8819-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Prohibited Acts. – The following shall be election offenses punishable under Sections 263 and 264 of Batas Pambansa Bilang 881, as amended, otherwise known as the \"Omnibus Election Code\":\n(a) Any person who shall prohibit, impede, obstruct or prevent a registered voter or a new voter from submitting his or her biometrics for capture through the use of force, intimidation or monetary consideration; and\n(b) Any public official or person who, under the guise of implementing this Act, shall unjustifiably and without due process, cause the deactivation or reactivation of any registered voter."}},{"id":"PH-H8819-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Rules and Regulations. – The Commission shall, within sixty (60) days after the effectivity of this Act, promulgate the implementing rules and regulations."}},{"id":"PH-H8819-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. – If any part of this Act is held invalid or unconstitutional, the other parts or provisions hereof shall remain valid and effective."}},{"id":"PH-H8819-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8819-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Mandatory Biometrics Voter Registration","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8820"] = {"id":"PH-H8820","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10368_2013.html","fetchedAt":"2026-10-06","articleCount":31,"structureMode":"ARTICLE","title":{"zh":"规定对 Marcos 政权期间人权侵犯受害者的赔偿与承认，记录上述侵犯行为，为此拨款并为其他目的法案","en":"An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật quy định việc bồi thường và công nhận đối với nạn nhân vi phạm nhân quyền dưới chế độ Marcos, ghi nhận các vi phạm đó","th":"พระราชบัญญัติกำหนดการชดเชยและการยอมรับต่อผู้เสียหายจากการละเมิดสิทธิมนุษยชนในยุค Marcos และบันทึกการละเมิดดังกล่าว","id":"Undang-Undang mengatur kompensasi dan pengakuan bagi korban pelanggaran HAM pada masa rezim Marcos, mencatat pelanggaran tersebut","ms":"Akta mengatur pampasan dan pengiktirafan bagi mangsa pelanggaran hak asasi manusia pada era rejim Marcos, merekodkan pelanggaran tersebut"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10368","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-25","completenessNote":"全文，共 31 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10368_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 32 条，缺 24）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8820-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. — This Act shall be known as the \"Human Rights Victims Reparation and Recognition Act of 2013″."}},{"id":"PH-H8820-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. — Section 11 of Article II of the 1987 Constitution of the Republic of the Philippines declares that the State values the dignity of every human, person and guarantees full respect for human rights. Pursuant to this declared policy, Section 12 of Article III of the Constitution prohibits the use of torture, force, violence, threat, intimidation, or any other means which vitiate the free will and mandates the compensation and rehabilitation of victims of torture or similar practices and their families.\nBy virtue of Section 2 of Article II of the Constitution adopting generally accepted principles of international law as part of the law of the land, the Philippines adheres to international human rights laws and conventions, the Universal Declaration of Human Rights, including the International Covenant on Civil and Political Rights (ICCPR) and the Convention Against Torture (CAT) and Other Cruel, Inhuman or Degrading Treatment or Punishment which imposes on each State party the obligation to enact domestic legislation to give effect to the rights recognized therein and to ensure that any person whose rights or freedoms have been violated shall have an effective remedy, even if the violation is committed by persons acting in an official capacity. In fact, the right to a remedy is itself guaranteed under existing human rights treaties and/or customary international law, being peremptory in character ( jus cogens) and as such has been recognized as non-derogable.\nConsistent with the foregoing, it is hereby declared the policy of the State to recognize the heroism and sacrifices of all Filipinos who were victims of summary execution, torture, enforced or involuntary disappearance and other gross human rights violations committed during the regime of former President Ferdinand E. Marcos covering the period from September 21, 1972 to February 25, 1986 and restore the victims’ honor and dignity. The State hereby acknowledges its moral and legal obligation to recognize and/or provide reparation to said victims and/or their families for the deaths, injuries, sufferings, deprivations and damages they suffered under the Marcos regime.\nSimilarly, it is the obligation of the State to acknowledge the sufferings and damages inflicted upon persons whose properties or businesses were forcibly taken over, sequestered or used, or those whose professions were damaged and/or impaired, or those whose freedom of movement was restricted, and/or such other victims of the violations of the Bill of Rights."}},{"id":"PH-H8820-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. — The following terms as used in this Act shall mean:\n(a) Detention refers to the act of taking a person into custody against his will by persons acting in an official capacity and/or agents of the State.\n(b) Human rights violation refers to any act or omission committed during the period from September 21, 1972 to February 25, 1986 by persons acting in an official capacity and/or agents of the State, but shall not be limited to the following:\n(1) Any search, arrest and/or detention without a valid search warrant or warrant of arrest issued by a civilian court of law, including any warrantless arrest or detention carried out pursuant to the declaration of Martial Law by former President Ferdinand E. Marcos as well as any arrest., detention or deprivation of liberty carried out during the covered period on the basis of an \"Arrest, Search and Seizure Order (ASSO)\", a \"Presidential Commitment Order (PCO)\" or a \"Preventive Detention Action (PDA)\" and such other similar executive issuances as defined by decrees of former President Ferdinand E. Marcos, or in any manner that the arrest, detention or deprivation, of liberty was effected;\n(2) The infliction by a person acting in an official capacity and/or an agent of the State of physical injury, torture, killing, or violation of other human rights, of any person exercising civil or political rights, including but not limited to the freedom of speech, assembly or organization; and/or the right to petition the government for redress of grievances, even if such violation took place during or in the course of what the authorities at the time deemed an illegal assembly or demonstration: Provided , That torture in any form or under any circumstance shall be considered a human rights violation;\n(3) Any enforced or involuntary disappearance caused upon a person who was arrested, detained or abducted against one’s will or otherwise deprived of one’s liberty, as defined in Republic Act No. 10350 1, otherwise known as the \"Anti-Enforced or Involuntary Disappearance Act of 2012″;\n(4) Any force or intimidation causing the involuntary exile of a person from the Philippines;\n(5) Any act of force, intimidation or deceit causing unjust or illegal takeover of a business, confiscation of property, detention of owner/s and or their families, deprivation of livelihood of a person by agents of the State, including those caused by Ferdinand E. Marcos, his spouse Imelda R. Marcos, their immediate relatives by consanguinity or affinity, as well as those persons considered as among their close relatives, associates, cronies and subordinates under Executive Order No. 1, issued on February 28, 1986 by then President Corazon C. Aquino in the exercise of her legislative powers under the Freedom Constitution;\n(6) Any act or series of acts causing, committing and/or conducting the following:\n(i) Kidnapping or otherwise exploiting children of persons suspected of committing acts against the Marcos regime;\n(ii) Committing sexual offenses against human rights victims who are detained and/or in the course of conducting military and/or police operations; and\n(iii) Other violations and/or abuses similar or analogous to the above, including those recognized by international law.\n(c) Human Rights Violations Victim (HRVV) refers to a person whose human rights were violated by persons acting in an official capacity and/or agents of the State as defined herein. In order to qualify for reparation under this Act, the human rights violation must have been committed during the period from September 21, 1972 to February 25, 1986: Provided, however, That victims of human rights violations that were committed one (1) month before September 21, 1972 and one (1) month after February 25, 1986 shall be entitled to reparation, under this Act if they can establish that the violation was committed:\n(1) By agents of the State and/or persons acting in an official capacity as defined hereunder;\n(2) For the purpose of preserving, maintaining, supporting or promoting the said regime; or\n(3) To conceal abuses during the Marcos regime and/or the effects of Martial Law.\n(d) Persons Acting in an Official Capacity and/or Agents of the State.— The following persons shall be deemed persons acting in an official capacity and/or agents of the State under this Act:\n(1) Any member of the former Philippine Constabulary (PC), the former Integrated National Police (INP), the Armed Forces of the Philippines (AFP) and the Civilian Home Defense Force (CHDF) from September 21, 1972 to February 25, 1986 as well as any civilian agent attached thereto; and any member of a paramilitary group even if one is not organically part of the PC, the INP, the AFP or the CHDF so long as it is shown that the group was organized, funded, supplied with equipment, facilities and/or resources, and/or indoctrinated, controlled and/or supervised by any person acting in an official capacity and/or agent of the State as herein defined;\n(2) Any member of the civil service, including persons who held elective or appointive public office at any time from September 21, 1972 to February 25, 1986;\n(3) Persons referred to in Section 2(a) of Executive Order No. 1, creating the Presidential Commission on Good Government (PCGG), issued on February 28, 1986 and related laws by then President Corazon C. Aquino in the exercise of her legislative powers under the Freedom Constitution, including former President Ferdinand E. Marcos, spouse Imelda R. Marcos, their immediate relatives by consanguinity or affinity, as well as their close relatives, associates, cronies and subordinates; and\n(4) Any person or group/s of persons acting with the authorization, support or acquiescence of the State during the Marcos regime.\n(e) Torture refers to any act by which severe pain or suffering, whether physical or mental, is intentionally inflicted on any person under the custody of persons acting in an official capacity and/or agents of the State, as defined by law, jurisprudence, international conventions and Republic Act No. 9745, otherwise known as the \"Anti-Torture Act of 2009″."}},{"id":"PH-H8820-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Entitlement to Monetary Reparation. — Any HRVV qualified under this Act shall receive reparation from the State, free of tax, as herein prescribed: Provided, That for a deceased or involuntary disappeared HRVV, the legal heirs as provided for in the Civil Code of the Philippines, or such other person named by the executor or administrator of the deceased or involuntary disappeared HRVV’s estate in that order, shall be entitled to receive such reparation: Provided, further, That no special power of attorney shall be recognized in the actual disbursement of the award, and only the victim or the aforestated successor(s)-in-interest shall be entitled to personally receive said reparation form the Board, unless the victim involved is shown to be incapacitated to the satisfaction of the Board: Provided, furthermore, That the reparation received under this Act shall be without prejudice to the receipt of any other sum by the HRVV from any other person or entity in any case involving violations of human rights as defined in this Act."}},{"id":"PH-H8820-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Nonmonetary Reparation. — The Department of Health (DOH), the Department of Social Welfare and Development (DSWD), the Department of Education (DepED), the Commission on Higher Education (CHED), the Technical Education and Skills Development Authority (TESDA), and such other government agencies shall render the necessary services as nonmonetary reparation for HRVVs and/or their families, as may be determined by the Board pursuant to the provisions of this Act. The amount necessary for this purpose shall be sourced from the budget of the agency concerned in the annual General Appropriations Act (GAA)."}},{"id":"PH-H8820-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Amount of Reparation. — The amount of reparation under this Act shall be in proportion to the gravity of the human rights violation committed on the HRVV and in accordance with the number of points assigned to the individual under Section 19 hereof."}},{"id":"PH-H8820-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Source of Reparation. — The amount of Ten billion pesos (P10,000,000,000.00) plus accrued interest which form part of the funds transferred to the government of the Republic of the Philippines by virtue of the December 10, 1997 Order of the Swiss Federal Supreme Court, adjudged by the Supreme Court of the Philippines as final and executory in Republic vs. Sandiganbayan on July 15, 2003 (G.R. No. 152154) as Marcos ill-gotten wealth and forfeited in favor of the Republic of the Philippines, shall be the principal source funds for the implementation of this Act.\nTHE HUMAN RIGHTS VICTIMS’ CLAIMS BOARD"}},{"id":"PH-H8820-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Creation and Composition of the Human Rights Victims’ Claims Board. — There is hereby created an independent and quasi-judicial body to be known as the Human Rights Victims’ Claims Board, hereinafter referred to as the Board. It shall be composed of nine (9) members, who shall possess the following qualifications:\n(a) Must be of known probity, competence and integrity;\n(b) Must have a deep and thorough understanding and knowledge of human rights and involvement in efforts against human rights violations committed during the regime of former President Ferdinand E. Marcos;\n(c) At least three (3) of them must be members of the Philippine Bar who have been engaged in the practice of law for at least ten (10) years; and\n(d) Must have a clear and adequate understanding and commitment to human rights protection, promotion and advocacy.\nThe Human Rights Victims’ Claims Board shall be attached to but shall not be under the Commission on Human Rights (CHR).\nThe Board shall organize itself within thirty (30) days from the completion of appointment of all nine (9) members and shall thereafter organize its Secretariat."}},{"id":"PH-H8820-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Appointment to the Board. — The President shall appoint the Chairperson and the other eight (8) members of the Board: Provided, That human rights organizations such as, but not limited to, the Task Force Detainees of the Philippines (TFDP), the Free Legal Assistance Group (FLAG), the Movement of Attorneys for Brotherhood, Integrity and Nationalism (MABINI), the Families of Victims of Involuntary Disappearance (FIND) and the Samahan ng mga Ex-Detainees Laban sa Detensyon at Aresto (SELDA) may submit nominations to the President."}},{"id":"PH-H8820-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Powers and Functions of the Board. — The Board shall have the following powers and functions:\n(a) Receive, evaluate, process and investigate applications for claims under this Act;\n(b) Issue subpoena/s ad testificandum and subpoena/s duces tecum;\n(c) Conduct independent administrative proceedings and resolve disputes over claims;\n(d) Approve with finality all eligible claims under this Act;\n(e) Deputize appropriate government agencies to assist it in order to effectively perform its functions;\n(f) Promulgate such rules as may be necessary to carry out the purposes of this Act, including rules of procedure in the conduct of its proceedings, with the Revised Rules of Court of the Philippines having suppletory application;\n(g) Exercise administrative control and supervision over its Secretariat;\n(h) The Board, at its discretion, may consult the human rights organizations mentioned in Section 9 herein; and\n(i) Perform such other duties, functions and responsibilities as may be necessary to effectively attain the objectives of this Act."}},{"id":"PH-H8820-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Resolution, of Claims. — The Board shall be composed of three (3) divisions which shall function simultaneously and independently of each other in the resolution of claims for reparation. Each division shall be composed of one (1) Chairperson, who shall be a member of the Philippine Bar and two (2) members to be appointed by the Board en banc."}},{"id":"PH-H8820-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Emoluments. — The Chairperson and members of the Board shall have the rank, salary, emoluments and allowances equivalent to s Presiding Justice and Associate Justice of the Court of Appeals, respectively."}},{"id":"PH-H8820-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Secretariat of the Board. — The Board shall be assisted by a Secretariat which may come from the existing personnel of the CHR, without prejudice to the hiring of additional personnel as determined by the Board to accommodate the volume of required work. The following shall be the functions of the Secretariat:\n(a) Receive, evaluate, process and investigate applications for claims under this Act;\n(b) Recommend to the Board the approval of applications for claims;\n(c) Assist the Board in technical functions; and\n(d) Perform other duties that may be assigned by the Board.\nThe Chairperson of the Board shall appoint a Board Secretary who shall head the Secretariat for the duration of the existence of the Board. There shall be a Technical Staff Head assisted by five (5) Legal Officers and three (3) Paralegal Officers; and an Administrative Staff Head assisted by three (3) Administrative Support Staff.\nWhen necessary, the Board may hire additional contractual employees or contract a service provider to provide services of counselors, psychologists, social workers and public education specialists, among others, to augment the services of the Secretariat: Provided, That the maximum contract amount per year shall not exceed more than fifteen percent (15%) of the total annual operating budget of the Board."}},{"id":"PH-H8820-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Operating Budget of the Board.— The operating budget of the Board shall be funded from the Ten billion peso (P10,000,000,000.00) fund, with Ten million pesos (P10,000,000.00) as its initial operating budget: Provided, That it shall not exceed Fifty million pesos (P50,000,000.00) a year"}},{"id":"PH-H8820-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Proper Disposition of Funds. — The Board shall ensure that funds appropriated or those which may become available as reparation for HRVVs are properly disbursed in accordance with the policies stated by Congress and relevant government rules, regulations and accounting procedures.\nCLAIMANTS, REPARATION AND RECOGNITION"}},{"id":"PH-H8820-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Claimants. — Any person who is an HRVV may file a claim with the Board for reparation and/or recognition in accordance with the provisions of this Act."}},{"id":"PH-H8820-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Conclusive Presumption That One is an HRVV Under This Act. — The claimants in the class suit and direct action plaintiffs in the Human Rights Litigation Against the Estate of Ferdinand E. Marcos (MDL No. 840, CA No. 88-0390) in the US Federal District Court of Honolulu, Hawaii wherein a favorable judgment has been rendered, shall be extended the conclusive presumption that they are HRVVs: Provided, That the HRVVs recognized by the Bantayog Ng Mga Bayani Foundation shall also be accorded the same conclusive presumption: Provided, further, That nothing herein shall be construed to deprive the Board of its original jurisdiction and its inherent power to determine the extent of the human rights violations and the corresponding reparation and/or recognition that may be granted."}},{"id":"PH-H8820-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Motu Proprio Recognition. — The Board may take judicial notice motu proprio of individual persons who suffered human rights violations as defined herein and grant such persons recognition as HRVVs and included in the Roll of Victims as provided for in Section 26 hereof."}},{"id":"PH-H8820-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Determination of Award. — (a) The Board shall follow the point system in the determination of the award. The range shall be one (1) to ten (10) points, as follows:\n(1) Victims who died or who disappeared and are still missing shall be given ten (10) points;\n(2) Victims who were tortured and/or raped or sexually abused shall he given six (6) to nine (9) points:\n(3) Victims who were detained shall be given three (3) to five (5) points; and\n(4) Victims whose rights were violated under Section 3, paragraph (b), nos. (4), (5) and (6) under this Act shall be given one (1) to two (2) points.\nThe Board shall exercise its powers with due discretion in the determination of points for each victim, which shall be based on the type of violation committed against the HRVV, frequently and duration of the violation. In each category, HRVVs who had suffered more would receive more points. In instances where a victim is classified in more than one category, one shall be awarded the points in the higher category: Provided, That in cases where there are several eligible claims filed for reparation by or on behalf of a particular HRVV, the Board shall award only one (1) valid claim which corresponds to the category obtaining the highest number of points for each eligible claimant.\n(b) The Board shall proceed to determine the award for each claimant classified under Sections 16, 17 and 18 of this Act.\n(c) The Board shall then compute the final monetary value of one’s award that is equivalent to the numerical value of one point multiplied by the number of points that a claimant is entitled to, as previously determined by the Board.\n(d) Within thirty (30) days after the Board has approved with finality each eligible claim pending before it and after due publication of such legitimate claim, the award of monetary compensation shall take effect: Provided., That any pending appeal filed by an aggrieved claimant or opposite before the Board en banc must resolved by it sixty (60) days before the Board becomes functus officio.\nGENERAL- PROVISIONS"}},{"id":"PH-H8820-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Transfer of Funds. — Pursuant to the judgment mentioned in Section 7 hereof, the amount of Ten billion pesos (P10,000,000,000.00) plus the accrued interest are hereby set aside and appropriated to fund the purposes of this Act."}},{"id":"PH-H8820-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Documentation of Human — Rights Violations Committed by the Marcos Regime. — In the implementation of this Act and without prejudice to any other documentary or other evidence that may be required for the award of any reparation, any HRVV seeking reparation shall execute a detailed sworn statement narrating the circumstances of the pertinent human rights violation/s committed."}},{"id":"PH-H8820-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Publication. — Consistent with Section 23 herein, the Board, after having been duly convened, shall set the period for the commencement and termination of applications by HRVVs and cause the publication of the same: Provided, That such period shall only become operative fifteen (15) days after its last publication, which shall be once a week for three (3) consecutive weeks in at least two (2) national newspapers of general circulation."}},{"id":"PH-H8820-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Period for Filing of Claims; Waiver. — An HRVV shall file an application for reparation with the Board within six (6) months from the effectivity of the implementing rules and regulations (IRR) of this Act: Provided, That failure to file an application within said period is deemed a waiver of the right to file the same: Provided, further, That for HRVVs who are deceased, incapacitated, or missing due to enforced disappearance, their legal heir/s or representatives, shall be entitled to file an application for reparation on their behalf.\nAny opposition to the new application/s pursuant to Section 16 hereof shall only be entertained if such is filed within fifteen (15) days from the date of the last publication of the official list of eligible claimants as may be determined by the Board. The Board shall cause the publication of the official list of eligible claimants once a week for three (3) consecutive weeks in at least two (2) national newspapers of general circulation.\nSection 24 Appeal. — Any aggrieved claimant or oppositor may file an appeal within ten (10) calendar days from the receipt of the Resolution of the Division, to the Board en banc, whose decision shall then become final and executory."}},{"id":"PH-H8820-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Penalties; Applicability of the Revised Penal Code. — Any claimant who is found by the Board, after due hearing, to have filed a fraudulent claim, shall be referred to the appropriate office for prosecution. If convicted, he shall suffer the imprisonment of eight (8) to ten (10) years, shall be disqualified from public office and employment and shall be deprived of the right to vote and be voted for in any national or local election, even after the service of sentence unless granted absolute pardon.\nAny member of the Board and its Secretariat, public officer, employee of an agency or any private individual mandated to implement this Act, who shall misuse, embezzle or misappropriate the funds for the reparation of HRVVs or who shall commit fraud in the processing of documents and claims of HRVVs, or shall conspire with any individual to commit the same, shall also be prosecuted, Any member of the Board and its Secretariat, public officer, employee of an agency or any private individual mandated to implement this Act, who may have been found guilty of committing any or all of the prohibited acts stated in the preceding paragraph, or those acts punishable under the Revised Penal Code, shall be penalized under the pertinent provisions in the Code and relevant special penal laws."}},{"id":"PH-H8820-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Roll of Victims. — Persons who are HRVVs, regardless of whether they opt to seek reparation or not, shall be given recognition by enshrining their names in a Roll of Human Rights Victims to be prepared by the Board.\nA Memorial/Museum/Library shall be established in honor and in memory of the victims of human rights violations whose names shall be inscribed in the Roll. A compendium of their sacrifices shall be prepared and may be readily viewed and accessed in the internet. The Memorial/Museum/Library/Compendium shall have an appropriation of at least Five hundred million pesos (P500,000,000.00) from the accrued interest of the Ten billion peso (P10,000,000,000.00) fund.\nThe Roll may also be displayed in government agencies as maybe designated by the HRVV Memorial Commission as created hereunder."}},{"id":"PH-H8820-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Human, Rights Violations Victims’ Memorial Commission.. — There is hereby created a Commission to be known as the Human Rights Violations Victims’ Memorial Commission, hereinafter referred to as the Commission, primarily for the establishment, restoration, preservation and conservation of the Memorial/Museum/Library/Compendium in honor of the HRVVs during the Marcos regime.\nThe powers and functions of the Commission shall be assumed by the Board of Trustees which shall be composed of the following; Chairperson of the CHR as Chairperson; Chairperson of the National Historical Commission as Co-Chairperson; and Chairpersons of the CHED, the National Commission on Culture and the Arts (NCCA), the Secretary of the Department of Education and the Head of the University of the Philippines Diliman Main Library, as members.\nThe Board of Trustees shall have the authority to hire and appoint its officials and employees, receive donations and grants for and on its behalf, and generate revenues for the benefit of the Commission.\nThe Commission shall be attached to the CHR solely for budgetary and administrative purposes. The operating budget of the Commission shall be appropriated from the General Appropriations Act.\nThe Commission shall also coordinate and collaborate with the DepED and the CHED to ensure that the teaching of Martial Law atrocities, the lives and sacrifices of HRVVs in our history are included in the basic, secondary and tertiary education curricula.\nFINAL PROVISIONS"}},{"id":"PH-H8820-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Guidelines for the Implementing Rules and Regulations (1RR). — In implementing this Act and in formulating the corresponding rules and regulations, and to ensure that all applications are properly screened for fraudulent claims, the Board must provide for:\n(a) Transparency in the processing of the claims;\n(b) A procedure that allows any concerned party to oppose an application or claim on the ground that it is fraudulent, fictitious or spurious and gives that party the opportunity to question the same and to present evidence in support thereof; and\n(c) A procedure that is speedy and expeditious without sacrificing any of the parties’ fundamental rights.\nWithin fifteen (15) days from the date of its organization, the Board shall promulgate the necessary IRR and procedures for the effective implementation of this Act. The IRR shall be effective fifteen (15) days after its publication in two (2) national newspapers of general circulation."}},{"id":"PH-H8820-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Work Period; Sunset Clause. — The Board shall complete its work within two (2) years from the effectivity of the IRR promulgated by it. After such period, it shall become functus officio."}},{"id":"PH-H8820-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Separability Clause. — If, for any reason, any section or provision of this Act is declared unconstitutional or invalid, such other sections or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H8820-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Repealing Clause. — All laws, decrees, executive orders, rules and regulations or parts thereof inconsistent with any of the provisions of this Act, including Section 63(b) of Republic Act No. 6657, as amended, otherwise known as the Comprehensive Agrarian Reform Law of 1988 and Section 40(a) of Republic Act No. 7160, otherwise known as the Local Government Code of 1991, are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8820-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8821"] = {"id":"PH-H8821","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10369_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将卡林加省卡林加工程区办公室重组为两个正式区工程办公室并为此拨款的法案","en":"An Act Reconstituting the Kalinga Engineering District Office in the Province of Kalinga tnto Two (2) Regular District Engineering Offices and Appropriating Funds Therefor","orig":"An Act Reconstituting the Kalinga Engineering District Office in the Province of Kalinga tnto Two (2) Regular District Engineering Offices and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10369","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10369_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8821-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The district engineering office in the Province of Kalinga, under the supervision of the Department of Public Works and Highways, shall be reconstituted into two (2) separate district engineering offices to be respectively named as the Upper Kalinga District Engineering Office and the Lower Kalinga District Engineering Office."}},{"id":"PH-H8821-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Upper Kalinga District Engineering Office to be located in the Municipality of Pasil shall comprise the municipalities of Pasil, Lubuagan, Balbalan and Tinglayan. The existing district engineering office located in the Municipality of Tabuk shall be known as the Lower Kalinga District Engineering Office and shall comprise the municipalities of Tabuk, Rizal, Tanudan and Pinukpuk."}},{"id":"PH-H8821-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the operationalization of these two (2) engineering districts, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8821-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reconstituting the Kalinga Engineering District Office in the Province of Kalinga tnto Two (2) Regular District Engineering Offices and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8822"] = {"id":"PH-H8822","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10370_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在吉马拉斯省设立由Buenavista与San Lorenzo市镇组成的独立市镇巡回审判法院并为此拨款的法案","en":"An Act Establishing a Separate Municipal Circuit Trial Court Comprising the Municipalities of Buenavista and San Lorenzo in the Province of Guimaras and Appropriating Funds Therefor","orig":"An Act Establishing a Separate Municipal Circuit Trial Court Comprising the Municipalities of Buenavista and San Lorenzo in the Province of Guimaras and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10370","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10370_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8822-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The municipalities of Buenavista and San Lorenzo are hereby separated from the territorial jurisdiction of the First Municipal Circuit Trial Court of Jordan – Buenavista – Nueva Valencia – Sibunag – San Lorenzo in the Province of Guimaras and a separate Municipal Circuit Trial Court for the municipalities of Buenavista and San Lorenzo, designated as the Second Municipal Circuit Trial Court shall be established therein."}},{"id":"PH-H8822-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of Justice, shall immediately include in the Court’s program the operationalization of the additional municipal circuit trial court for the Province of Guimaras, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court herein created shall be appropriated and released only upon the actual organization of the Court and the appointment of its personnel."}},{"id":"PH-H8822-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All pending cases falling within the jurisdiction of the municipalities of Buenavista and San Lorenzo shall be transferred to the created Second Municipal Circuit Trial Court and shall be tried and decided therein."}},{"id":"PH-H8822-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Separate Municipal Circuit Trial Court Comprising the Municipalities of Buenavista and San Lorenzo in the Province of Guimaras and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8823"] = {"id":"PH-H8823","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10371_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sipalay市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating an Additional Regional Trial Court Branch to be Stationed in the City of Sipalay, Province of Negros Occidental, Amending for the Purpose Section 14, Paragraph (G) of Batas Pambansa Blg. 129, as Amended, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", and Providing Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10371","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-28","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10371_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8823-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"One (1) additional Regional Trial Court branch is hereby created in the Sixth Judicial Region with seat at Sipalay City, Province of Negros Occidental.\nThe Supreme Court shall assign the branch number of the newly-created branch of the Regional Trial Court in the Sixth Judicial Region."}},{"id":"PH-H8823-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"the Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of one (1) additional branch of the Regional Trial Court to be stationed in the City of Sipalay, Province of Negros Occidental, the funding of which shall be included in the annual General Appropriations Act. the funds necessary for the operation of the Court herein created shall be appropriated and released only upon the actual organization of the Court and the appointment of its personnel."}},{"id":"PH-H8823-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(g) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8823-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8824"] = {"id":"PH-H8824","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10372_2013.html","fetchedAt":"2026-10-06","articleCount":32,"structureMode":"ARTICLE","title":{"zh":"对《知识产权法典》的修改","en":"Intellectual Property Code of the Philippines","orig":"An Act Amending Certain Provisions of Republic Act No. 8293, Otherwise Known as the \"Intellectual Property Code of the Philippines\", and for Other Purposes","vi":"Đạo luật sửa đổi Bộ luật Sở hữu Trí tuệ","th":"พระราชบัญญัติแก้ไขประมวลกฎหมายทรัพย์สินทางปัญญา","id":"Undang-Undang Perubahan atas Kitab Undang-Undang Kekayaan Intelektual","ms":"Akta Pindaan kepada Kanun Undang-Undang Harta Intelek"},"level":"law","status":"active","topics":["ip"],"docNumber":"Republic Act No. 10372","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-02-28","completenessNote":"全文，共 32 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10372_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8824-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 6 of Republic Act No. 8293, otherwise known as the \"Intellectual Property Code of the Philippines\", is hereby amended to read as follows:\n\"SEC. 6. The Organizational Structure of the IPO. – x x x \"6.2. the Office shall be divided into seven (7) Bureaus, each of which shall be headed by a Director and assisted by an Assistant Director. These Bureaus are:\n\"x x x \"(f) the Administrative, Financial and Personnel Services Bureau; and \"(g) the Bureau of Copyright and Other Related Rights.\""}},{"id":"PH-H8824-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 7 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 7. The Director General and Deputies Director General. – \"x x x \"(b) Exercise exclusive appellate jurisdiction over all decisions rendered by the Director of Legal Affairs, the Director of Patents, the Director of Trademarks, the Director of Copyright and Other Related Rights, and the Director of the Documentation, Information and Technology Transfer Bureau. the decisions of the Director General in the exercise of his appellate jurisdiction in respect of the decisions of the Director of Patents, the Director of Trademarks and the Director of Copyright and Other Related Rights shall be appealable to the Court of Appeals in accordance with the Rules of Court; and those in respect of the decisions of the Director of the Documentation, Information and Technology Transfer Bureau shall be appealable to the Secretary of Trade and Industry;\n\"(c) Undertake enforcement functions supported by concerned agencies such as the Philippine National Police, the National Bureau of Investigation, the Bureau of Customs, the Optical Media Board, and the local government units, among others;\n\"(d) Conduct visits during reasonable hours to establishments and businesses engaging in activities violating intellectual property rights and provisions of this Act based on report, information or complaint received by the office; and \"(e) Such other functions in furtherance of protecting IP rights and objectives of this Act.\""}},{"id":"PH-H8824-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A new Section 9A is hereby inserted after Section 9 of Republic Act No. 8293, to read as follows:\n\"SEC. 9A. The Bureau of Copyright and Other Related Rights. – the Bureau of Copyright and Other Related Rights shall have the following functions:\n\"9A.1. Exercise original jurisdiction to resolve disputes relating to the terms of a license involving the author’s right to public performance or other communication of his work;\n\"9A.2. Accept, review and decide on applications for the accreditation of collective management organizations or similar entities;\n\"9A.3. Conduct studies and researches in the field of copyright and related rights; and \"9A.4. Provide other copyright and related rights service and charge reasonable fees therefor.\""}},{"id":"PH-H8824-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 171.3. of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 171. Definitions. – x x x \"171.3. ‘Communication to the public’ or ‘communicate to the public’ means any communication to the public, including broadcasting, rebroadcasting, retransmitting by cable, broadcasting and retransmitting by satellite, and includes the making of a work available to the public by wire or wireless means in such a way that members of the public may access these works from a place and time individually chosen by them;\""}},{"id":"PH-H8824-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 171.9. of Republic Act No. 8293 is hereby amended to read as follows:\n\"171.9. ‘Reproduction’ is the making of one (1) or more copies, temporary or permanent, in whole or in part, of a work or a sound recording in any manner or form without prejudice to the provisions of Section 185 of this Act (Sec. 41[E], P.D. No. 49a);\""}},{"id":"PH-H8824-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"There shall be two new subsections to be added at the end of Section 171.11. to be known as 171.12. and 171.13., both to read as follows:\n\"171.12. ‘Technological measure’ means any technology, device or component that, in the normal course of its operation, restricts acts in respect of a work, performance or sound recording, which are not authorized by the authors, performers or producers of sound recordings concerned or permitted by law;\n\"171.13. ‘Rights management information’ means information which identifies the work, sound recording or performance; the author of the work, producer of the sound recording or performer of the performance; the owner of any right in the work, sound recording or performance; or information about the terms and conditions of the use of the work, sound recording or performance; and any number or code that represent such information, when any of these items is attached to a copy of the work, sound recording or fixation of performance or appears in conjunction with the communication to the public of a work, sound recording or performance.\""}},{"id":"PH-H8824-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"the Chapter Title of Chapter VII, Part IV, the Law on Copyright, is hereby amended to read as follows:\n\"CHAPTER VII TRANSFER, ASSIGNMENT AND LICENSING OF COPYRIGHT\""}},{"id":"PH-H8824-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 180 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 180. Rights of Assignee or Licensee. – 180.1. the copyright may be assigned or licensed in whole or in part. Within the scope of the assignment or license, the assignee or licensee is entitled to all the rights and remedies which the assignor or licensor had with respect to the copyright.\n\"180.2. the copyright is not deemed assigned or licensed inter vivos, in whole or in part, unless there is a written indication of such intention.\n\"x x x \"180.4. Any exclusivity in the economic rights in a work may be exclusively licensed. Within the scope of the exclusive license, the licensee is entitled to all the rights and remedies which the licensor had with respect to the copyright.\n\"180.5. the copyright owner has the right to regular statements of accounts from the assignee or the licensee with regard to assigned or licensed work.\""}},{"id":"PH-H8824-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 181 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 181. Copyright and Material Object. – the copyright is distinct from the property in the material object subject to it. Consequently, the transfer, assignment or licensing of the copyright shall not itself constitute a transfer of the material object. Nor shall a transfer or assignment of the sole copy or of one or several copies of the work imply transfer, assignment or licensing of the copyright. (Sec. 16, P.D. No. 49)\""}},{"id":"PH-H8824-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 183 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 183. Designation of Society. – the owners of copyright and related rights or their heirs may designate a society of artists, writers, composers and other right-holders to collectively manage their economic or moral rights on their behalf. For the said societies to enforce the rights of their members, they shall first secure the necessary accreditation from the Intellectual Property Office. (Sec. 32, P.D. No. 49a)\""}},{"id":"PH-H8824-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 184.1. of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 184. Limitations on Copyright. – x x x \"(1) the reproduction or distribution of published articles or materials in a specialized format exclusively for the use of the blind, visually- and reading-impaired persons: Provided, That such copies and distribution shall be made on a nonprofit basis and shall indicate the copyright owner and the date of the original publication.\""}},{"id":"PH-H8824-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 185.1. of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 185. Fair Use of a Copyrighted Work. – 185.1. the fair use of a copyrighted work for criticism, comment, news reporting, teaching including limited number of copies for classroom use, scholarship, research, and similar purposes is not an infringement of copyright. Decompilation, which is understood here to be the reproduction of the code and translation of the forms of a computer program to achieve the interoperability of an independently created computer program with other programs may also constitute fair use under the criteria established by this section, to the extent that such decompilation is done for the purpose of obtaining the information necessary to achieve such interoperability.\n\"x x x.\""}},{"id":"PH-H8824-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 188.1. of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 188. Reprographic Reproduction by Libraries. – 188.1. Notwithstanding the provisions of Subsection 177.1., any library or archive whose activities are not for profit may, without the authorization of the author or copyright owner, make a limited number of copies of the work, as may be necessary for such institutions to fulfill their mandate, by reprographic reproduction:\n\"x x x \"(c) Where the making of such limited copies is in order to preserve and, if necessary in the event that it is lost, destroyed or rendered unusable, replace a copy, or to replace, in the permanent collection of another similar library or archive, a copy which has been lost, destroyed or rendered unusable and copies are not available with the publisher.\""}},{"id":"PH-H8824-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sections 190.1. and 190.2. of Republic Act No. 8293 are deleted in their entirety."}},{"id":"PH-H8824-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 190.3. of Republic Act No. 8293 is hereby renumbered and amended as the sole provision under Section 190 to read as follows:\n\"SEC 190. Importation and Exportation of Infringing Materials. – Subject to the approval of the Secretary of Finance, the Commissioner of Customs is hereby empowered to make rules and regulations for preventing the importation or exportation of infringing articles prohibited under Part IV of this Act and under relevant treaties and conventions to which the Philippines may be a party and for seizing and condemning and disposing of the same in case they are discovered after they have been imported or before they are exported. (Sec. 30, P.D. No. 49)\""}},{"id":"PH-H8824-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 191 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC 191. Deposit and Notice of Deposit with the National Library and the Supreme Court Library. – At any time during the subsistence of the copyright, the owner of the copyright or of any exclusive right in the work may, for the purpose of completing the records of the National Library and the Supreme Court Library, register and deposit with them, by personal delivery or by registered mail, two (2) complete copies or reproductions of the work in such form as the Directors of the said libraries may prescribe in accordance with regulations: Provided, That only works in the field of law shall be deposited with the Supreme Court Library. Such registration and deposit is not a condition of copyright protection.\""}},{"id":"PH-H8824-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Section 198 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 198. Term of Moral Rights. – 198.1. the right of an author under Section 193.1. shall last during the lifetime of the author and in perpetuity after his death while the rights under Sections 193.2. 193.3. and 193.4. shall be coterminous with the economic rights, the moral rights shall not be assignable or subject to license. the person or persons to be charged with the posthumous enforcement of these rights shall be named in a written instrument which shall be filed with the National Library. In default of such person or persons, such enforcement shall devolve upon either the author’s heirs, and in default of the heirs, the Director of the National Library.\""}},{"id":"PH-H8824-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Section 203 of Republic Act No. 8293 is hereby amended to read as follows;\n\"x x x \"203.2. the right of authorizing the direct or indirect reproduction of their performances fixed in sound recordings or audiovisual works or fixations in any manner or form;\n\"203.3. Subject to the provisions of Section 206, the right of authorizing the first public distribution of the original and copies of their performance fixed in sound recordings or audiovisual works or fixations through sale or rental of other forms of transfer of ownership;\n\"203.4. the right of authorizing the commercial rental to the public of the original and copies of their performances fixed in sound recordings or audiovisual works or fixations, even after distribution of them by, or pursuant to the authorization by the performer; and \"203.5. the right of authorizing the making available to the public of their performances fixed in sound recordings or audiovisual works or fixations, by wire or wireless means, in such a way that members of the public may access them from a place and time individually chosen by them. (Sec. 42, P.D. No. 49A).\""}},{"id":"PH-H8824-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Section 204.1. of Republic Act No. 8293 is hereby amended to read as follows;\n\"204.1. Independently of a performer’s economic rights, the performer shall, as regards his live aural performances or performances fixed in sound recordings or in audiovisual works or fixations, have the right to claim to be identified as the performer of his performances, except where the omission is dictated by the manner of the use of the performance, and to object to any distortion, mutilation or other modification of his performances that would be prejudicial to his reputation.\""}},{"id":"PH-H8824-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Section 208 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 208. Scope of Right. – x x x \"208.4. the right to authorize the making available to the public of their sound recordings in such a way that members of the public may access the sound recording from a place and at a time individually chosen or selected by them, as well as other transmissions of a sound recording with like effect.\""}},{"id":"PH-H8824-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Section 212 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 212. Limitations on Rights. – the provisions of Chapter VIII shall apply mutatis mutandis to the rights of performers, producers of sound recordings and broadcasting organizations.\""}},{"id":"PH-H8824-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Section 216 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 216. Infringement. – A person infringes a right protected under this Act when one:\n\"(a) Directly commits an infringement;\n\"(b) Benefits from the infringing activity of another person who commits an infringement if the person benefiting has been given notice of the infringing activity and has the right and ability to control the activities of the other person;\n\"(c) With knowledge of infringing activity, induces, causes or materially contributes to the infringing conduct of another.\n\"216.1. Remedies for Infringement. – Any person infringing a right protected under this law shall be liable:\n\"x x x \"(b) To pay to the copyright proprietor or his assigns or heirs such actual damages, including legal costs and other expenses, as he may have incurred due to the infringement as well as the profits the infringer may have made due to such infringement, and in proving profits the plaintiff shall be required to prove sales only and the defendant shall be required to prove every element of cost which he claims, or, in lieu of actual damages and profits, such damages which to the court shall appear to be just and shall not be regarded as penalty: Provided, That the amount of damages to be awarded shall be doubled against any person who:\n\"(i) Circumvents effective technological measures; or \"(ii) Having reasonable grounds to know that it will induce, enable, facilitate or conceal the infringement, remove or alter any electronic rights management information from a copy of a work, sound recording, or fixation of a performance, or distribute, import for distribution, broadcast, or communicate to the public works or copies of works without authority, knowing that electronic rights management information has been removed or altered without authority.\n\"x x x \"The copyright owner may elect, at any time before final judgment is rendered, to recover instead of actual damages and profits, an award of statutory damages for all infringements involved in an action in a sum equivalent to the filing fee of the infringement action but not less than Fifty thousand pesos (Php50,000.00). In awarding statutory damages, the court may consider the following factors:\n\"(1) the nature and purpose of the infringing act;\n\"(2) the flagrancy of the infringement;\n\"(3) Whether the defendant acted in bad faith;\n\"(4) the need for deterrence;\n\"(5) Any loss that the plaintiff has suffered or is likely to suffer by reason of the infringement; and \"(6) Any benefit shown to have accrued to the defendant by reason of the infringement.\n\"In case the infringer was not aware and had no reason to believe that his acts constitute an infringement of copyright, the court in its discretion may reduce the award of statutory damages to a sum of not more than Ten thousand pesos (Php10,000.00): Provided, That the amount of damages to be awarded shall be doubled against any person who:\n\"(i) Circumvents effective technological measures; or \"(ii) Having reasonable grounds to know that it will induce, enable, facilitate or conceal the infringement, remove or alter any electronic rights management information from a copy of a work, sound recording, or fixation of a performance, or distribute, import for distribution, broadcast, or communicate to the public works or copies of works without authority, knowing that electronic rights management information has been removed or altered without authority.\n\"x x x \"216.2. In an infringement action, the court shall also have the power to order the seizure and impounding of any article which may serve as evidence in the court proceedings, in accordance with the rules on search and seizure involving violations of intellectual property rights issued by the Supreme Court. (Sec. 28, P.D. No. 49a) \"The foregoing shall not preclude an independent suit for relief by the injured party by way of damages, injunction, accounts or otherwise.\""}},{"id":"PH-H8824-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Section 217.2. of Republic Act No. 8293 hereby amended to read as follows:\n\"217.2. In determining the number of years of imprisonment and the amount of fine, the court shall consider the value of the infringing materials that the defendant has produced or manufactured and the damage that the copyright owner has suffered by reason of the infringement: Provided, That the respective maximum penalty stated in Section 217.1. (a), (b) and (c) herein for the first, second, third and subsequent offense, shall be imposed when the infringement is committed by:\n\"(a) the circumvention of effective technological measures;\n\"(b) the removal or alteration of any electronic rights management information from a copy of a work, sound recording, or fixation of a performance, by a person, knowingly and without authority; or \"(c) the distribution, importation for distribution, broadcast, or communication to the public of works or copies of works, by a person without authority, knowing that electronic rights management information has been removed or altered without authority.\""}},{"id":"PH-H8824-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Section 218.1. of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 218. Affidavit Evidence. – x x x \"(c) the copy of the work or other subject matter annexed thereto is a true copy thereof.\n\"The affidavit shall be admitted in evidence in any proceedings under this Chapter and shall be prima facie proof of the matters therein stated until the contrary is proved, and the court before which such affidavit is produced shall assume that the affidavit was made by or on behalf of the owner of the copyright.\""}},{"id":"PH-H8824-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"A new Section 220A shall be inserted after Section 220.2. of Republic Act No. 8293 to read as follows:\n\"SEC. 220A. Disclosure of Information. – Where any article or its packaging or an implement for making it is seized or detained under a valid search and seizure under this Act is, or is reasonably suspected to be, by an authorized enforcement officer, in violation of this Act, the said officer, shall, wherever reasonably practicable, notify the owner of the copyright in question or his authorized agent of the seizure or detention, as the case may be.\""}},{"id":"PH-H8824-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Section 226 of Republic Act No. 8293 is hereby amended to read as follows:\n\"SEC. 226. Damages. – No damages may be recovered under this Act after the lapse of four (4) years from the time the cause of action arose. (Sec. 58, P.D. No. 49).\""}},{"id":"PH-H8824-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Chapter XX of Republic Act No. 8293 is hereby amended by adding a new section at the end thereof to be denominated as Section 230, to read as follows:\n\"SEC. 230. Adoption of Intellectual Property (IP) Policies. – Schools and universities shall adopt intellectual property policies that would govern the use and creation of intellectual property with the purpose of safeguarding the intellectual creations of the learning institution and its employees, and adopting locally-established industry practice fair use guidelines. These policies may be developed in relation to licensing agreements entered into by the learning institution with a collective licensing organization.\""}},{"id":"PH-H8824-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Section 230 of Republic Act No. 8293 is hereby renumbered as Section 231, and all succeeding sections of the same Act are hereby renumbered accordingly."}},{"id":"PH-H8824-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Implementing Rules and Regulations. – Within one hundred eighty (180) days from the effectivity of this Act, the Intellectual Property Office, in consultation with the National Book Development Board, the National Library, the Supreme Court Library and other relevant agencies, shall promulgate the rules and regulations necessary to effectively implement the provisions of this Act."}},{"id":"PH-H8824-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, issuances or regulations inconsistent with the provisions of this Act are hereby revised or amended accordingly."}},{"id":"PH-H8824-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Separability Clause. – If any part of this Act is declared unconstitutional or invalid, such parts or provisions thereof not so declared shall remain valid and subsisting."}},{"id":"PH-H8824-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125"};
  FT["PH-H8825"] = {"id":"PH-H8825","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10373_2013.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"授予 Olongapo 配电公司在 Olongapo 市及其郊区建设、运营和维护配电系统的特许经营权法案","en":"An Act Granting the Olongapo Electricity Distribution Company, Inc. a Franchise to Construct, Install, Establish, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Olongapo and its Suburbs","orig":"An Act Granting the Olongapo Electricity Distribution Company, Inc. a Franchise to Construct, Install, Establish, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Olongapo and its Suburbs","vi":"Đạo luật cấp quyền khai thác cho Olongapo Electricity Distribution Company, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phân phối điện tại Thành phố Olongapo","th":"พระราชบัญญัติให้สัมปทานแก่ Olongapo Electricity Distribution Company, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบจำหน่ายไฟฟ้าในเมือง Olongapo","id":"Undang-Undang memberikan waralaba kepada Olongapo Electricity Distribution Company, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem distribusi tenaga listrik di Kota Olongapo","ms":"Akta memberikan francais kepada Olongapo Electricity Distribution Company, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem pengagihan tenaga elektrik di Bandaraya Olongapo"},"level":"law","status":"active","topics":["investment","energy"],"docNumber":"Republic Act No. 10373","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-01","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10373_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8825-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Olongapo Electricity Distribution Company, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, a distribution system for the conveyance of electric power to the end-users in the City of Olongapo and its suburbs."}},{"id":"PH-H8825-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Facilities. – All electric distribution facilities, lines and systems for electric services owned, maintained, operated or managed by the grantee, its successors or assigns, shall be operated and maintained at all times in a superior manner, and it shall be the duty of the grantee, its successors or assigns, whenever required to do so by the Energy Regulatory Commission, hereinafter referred to as the ERC, or its legal successor, or the Department of Energy, hereinafter referred to as the DOE, or its legal successor, or any other government agency concerned, to modify, improve and change such facilities or systems in such a manner and to such extent as the progress in science and improvements in the electric power services may render reasonable and proper.\nWhenever practicable and for purposes of maintaining order, safety and aesthetics along highways, roads, streets, alleys or right-of-way, the grantee may allow the use of free spaces in its poles, facilities or right-of-way by interested parties upon reasonable compensation to the grantee considering cost incurred to accommodate and administer the use of the grantee’s facilities by such parties. the ERC shall decide in case of dispute or disagreement between parties."}},{"id":"PH-H8825-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the Energy Regulatory Commission (ERC). – the grantee shall secure from the ERC, or any other government agency which has jurisdiction over the operation of the herein grantee, the necessary certificate of public convenience and necessity and other appropriate permits and licenses for the construction and operation of its electric distribution system."}},{"id":"PH-H8825-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Ingress and Egress. – For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit (LGU) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks or bridges of said province, cities and/or municipalities: Provided, however, That a public place, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said grantee, its successors or assigns, in accordance with the standards set by the DPWH or the LGU concerned. Should the grantee, its successors or assigns, after the ten (10)-day notice from the said authority, fail, refuse or neglect to repair or replace any part of public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed or disturbed by the said grantee, its successors or assigns, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition at double expense to be charged against the grantee, its successors or assigns."}},{"id":"PH-H8825-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. – the grantee shall supply electricity to its captive market in the least costly manner. In the interest of the public good and as far as feasible and whenever required by the ERC, the grantee shall modify, improve or change its facilities, poles, lines, systems and equipment for the purpose of providing efficient and reliable service and reduced electricity costs. the grantee shall charge reasonable and just power rates for its services to all types of consumers within its franchised areas in order that business and industries shall be able to compete.\nThe grantee shall have the obligation to provide open and nondiscriminatory access to its distribution system and services for any end-user within its franchise area consistent with Republic Act No. 9136, otherwise known as the \"Electric Power Industry Reform Act of 2001″. the grantee shall not engage in any activity that will constitute an abuse of market power such as, but not limited to, unfair trade practices, monopolistic schemes and any other activities that will hinder competitiveness of business and industries."}},{"id":"PH-H8825-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. – the retail rates to its captive market and charges for the distribution of electric power by the grantee to its end-user shall be regulated by and subject to the approval of the ERC or its legal successor.\nThe grantee shall identify and segregate in its electricity bill to the end-users the components of the retail rate pursuant to Republic Act No. 9136, unless otherwise amended. Such rates charged by the grantee to the end-users shall be made public and transparent. the grantee shall implement lifeline rate to marginalized end-users as mandated under Republic Act No. 9136."}},{"id":"PH-H8825-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Promotion of Consumer Interests. – the herein grantee shall establish a consumer desk that will handle consumer complaints and ensure adequate promotion of consumer interests. the grantee shall act with dispatch on all complaints brought before it."}},{"id":"PH-H8825-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. – A special right is hereby-reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations or facilities of the grantee, to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated."}},{"id":"PH-H8825-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of Eminent Domain. – Subject to the limitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as it may be reasonably necessary for the efficient maintenance and operation of services. the grantee is authorized to install and maintain its poles, wires and other facilities over and across public property, including streets, highways, forest reserves and other similar property of the Government of the Philippines, its branches or any of its instrumentalities. the grantee may acquire such private property as is actually necessary for the realization of the purposes for which this franchise is granted: Provided, That proper condemnation proceedings shall have been instituted and just compensation paid."}},{"id":"PH-H8825-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – the grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction, installation, operation and maintenance of the distribution system of the grantee."}},{"id":"PH-H8825-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Liability to Damages. – the grantee shall be liable for any injury and damage arising from or caused by accident to persons and property by reason of any defective construction under this franchise or of any neglect or omission to keep its poles and wires in safe condition."}},{"id":"PH-H8825-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – the grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, grant of usufruct, sale or assignment of franchise or the rights or privileges acquired within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H8825-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Equality Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or may hereafter be granted shall, upon prior review and approval of Congress, become part of previously granted power distribution franchises and shall be accorded immediately and unconditionally to the grantees of such franchises: Provided, however, That the foregoing shall neither apply to nor affect provisions concerning territory covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to the sale, lease, transfer, grant of usufruct or assignment of legislative franchises with prior congressional approval."}},{"id":"PH-H8825-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act. This franchise shall be deemed ipso facto revoked in the event that the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H8825-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Applicability Clause. – the grantee shall comply with and be subject to the provisions of Commonwealth Act No. 146, as amended, otherwise known as the \"Public Service Act\" and Republic Act No. 9136, otherwise known as the \"Electric Power Industry Reform Act of 2001″."}},{"id":"PH-H8825-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. – the grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of the succeeding year."}},{"id":"PH-H8825-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Penalty Clause. – Any grantee who fails to submit the annual report to Congress will be fined Five hundred pesos (P500.00) per working day of noncompliance. the fine will be collected by the ERC from the said delinquent franchise grantee separate from the reportorial penalties imposed by the ERC. the collected funds shall accrue to the monitoring fund of the ERC in line with its supervisory and regulatory functions. the reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the ERC."}},{"id":"PH-H8825-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. – If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H8825-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repeatability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H8825-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Publication. – This Act shall be published, through the initiative of the grantee, fifteen (15) days after this Act is signed by the President of the Philippines or has lapsed into law."}},{"id":"PH-H8825-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Olongapo Electricity Distribution Company, Inc. a Franchise to Construct, Install, Establish, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Olongapo and its Suburbs","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8826"] = {"id":"PH-H8826","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10374_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"农业土地改革法典","en":"Agricultural Land Reform Code","orig":"An Act Extending the Life of the Land Bank of the Philippines, Further Amending Republic Act No. 3844. Otherwise Known as the \"Agricultural Land Reform Code\". as Amended","vi":"Bộ luật Cải cách Ruộng đất Nông nghiệp","th":"ประมวลกฎหมายปฏิรูปที่ดินเพื่อเกษตรกรรม","id":"Kitab Undang-Undang Reformasi Agraria","ms":"Kanun Pembaharuan Tanah Pertanian"},"level":"law","status":"active","topics":["tax","environment"],"docNumber":"Republic Act No. 10374","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10374_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8826-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 74 of Republic Act No. 3844 is amended to read as follows:\n\"SEC. 74. Creation. – To finance the acquisition by the Government of landed estates for division and resale to small landholders, as well as the purchase of the landholding by the agricultural lessee from the landowner, there is hereby established a body corporate to be known as the \"Land Bank of the Philippines\", hereinafter called the \"Bank\", which shall have its principal place of business in Manila. The legal existence of the Bank is extended for a period of fifty (50) years from the expiration of its original term on 08 August 2013, renewable for another fifty (50) years. The Bank shall be subject to such rules and regulations as the Central Bank may from time to time promulgate.\""}},{"id":"PH-H8826-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Separability Clause. – If, for any reason, any provision of this Act is declared invalid or unconstitutional, the remaining provisions not affected thereby shall continue to be in force and effect."}},{"id":"PH-H8826-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, proclamations, rules and regulations, and other issuances, or parts thereof, which are inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8826-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) newspapers of general circulation, whichever is earlier."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Agricultural Land Reform Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8827"] = {"id":"PH-H8827","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10375_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将山区省-伊莎贝拉公路改设为国道并为此拨款的法案","en":"An Act Converting the Mountain Province - Isabela Road to a National Road and Appropriating Funds Therefor","orig":"An Act Converting the Mountain Province - Isabela Road to a National Road and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Đường Mountain Province - Isabela thành Đường Quốc gia, và phân bổ kinh phí","th":"พระราชบัญญัติเปลี่ยนสถานะถนน Mountain Province - Isabela เป็นถนนแห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang mengubah status Jalan Mountain Province - Isabela menjadi Jalan Nasional, dan mengalokasikan dana","ms":"Akta menukar status Jalan Mountain Province - Isabela kepada Jalan Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10375","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10375_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8827-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mountain Province – Isabela Road with a net length of 25.863 kilometers is hereby converted and declared a national road."}},{"id":"PH-H8827-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8827-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Mountain Province - Isabela Road to a National Road and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8828"] = {"id":"PH-H8828","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10376_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"免除北三宝颜电力合作社（ZANECO）应付国家电力公司（NPC）燃料补偿费/增量成本费（FCC/ICC）已付本金账户的利息","en":"An Act Condoning the Interest on the Paid Principal Account of Fuel Compensating Charge/incremental Cost Charge (FCC/ICC) of the Zamboanga Del Norte Electric Cooperative. Inc. (ZANECO) Payable and Due to the National Power Corporation (NPC)","orig":"An Act Condoning the Interest on the Paid Principal Account of Fuel Compensating Charge/incremental Cost Charge (FCC/ICC) of the Zamboanga Del Norte Electric Cooperative. Inc. (ZANECO) Payable and Due to the National Power Corporation (NPC)"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 10376","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10376_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8828-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Condonation of Interest Only. – The interest earned on the paid principal account of Thirty million five hundred fifty-seven thousand six hundred twenty-two pesos and thirty-five centavos (P30,557,622.35) for Fuel Compensating Charge/Incremental Cost Charge (FCC/ICC) of the Zamboanga del Norte Electric Cooperative, Inc. (ZANECO) payable and due to the National Power Corporation (NPC), subsequently transferred to the Power Sector Assets and Liabilities Management (PSALM) Corporation, incurred within the period of May 1991 to December 1993, which has accumulated, accrued and remains to be unpaid up to the present, in whatever accumulated amount or sum of interest as there may be, having been incurred without ZANECO’s fault, is hereby condoned, thereby perpetually relieving ZANECO from the payment thereof."}},{"id":"PH-H8828-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Principal Excluded from the Condonation. – The principal account of FCC/ICC in the sum of Thirty million five hundred fifty-seven thousand six hundred twenty-two pesos and thirty-five centavos (P30,557,622.35), having been paid already by the ZANECO to the NPC, and any account other than the unpaid interest on the already paid FCC/ICC amount are hereby excluded from this condonation."}},{"id":"PH-H8828-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Condoning the Interest on the Paid Principal Account of Fuel Compensating Charge/incremental Cost Charge (FCC/ICC) of the Zamboanga Del Norte Electric Cooperative. Inc. (ZANECO) Payable and Due to the National Power Corporation (NPC)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8829"] = {"id":"PH-H8829","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10377_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将拉乌尼翁第二区工程办公室由拉乌尼翁Naguilian迁至拉乌尼翁Agoo，为此修订第9033号共和国法","en":"An Act Transferring the Location of the La Union Second District Engineering Office From Naguilian, La Union to Agoo, La Union, Amending for This Purpose Republic Act No. 9033","orig":"An Act Transferring the Location of the La Union Second District Engineering Office From Naguilian, La Union to Agoo, La Union, Amending for This Purpose Republic Act No. 9033"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 10377","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10377_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8829-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1 of Republic Act No. 9033 is hereby amended to read as follows:\n\"SECTION 1. The Sub-District Engineering-Office located in Naguilian. La Union, under the supervision of the Department of Public Works and Highways, shall be converted into a regular engineering district to be known as the La Union Second Engineering District and is hereby relocated to Agoo, La Union.\""}},{"id":"PH-H8829-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Repealing Clause. – All laws or parts of any law, orders, rules and regulations or parts thereof inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H8829-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Location of the La Union Second District Engineering Office From Naguilian, La Union to Agoo, La Union, Amending for This Purpose Republic Act No. 9033","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8830"] = {"id":"PH-H8830","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10378_2013.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"承认互惠原则为给予国际承运人所得税豁免的基础，通过修订《国家国内税收法典》第 28、109、118 与 236 条理顺对其征收的其他税种，并为其他目的法案","en":"An Act Recognizing the Principle of Reciprocity as Basis for the Grant of Income Tax Exemptions to International Carriers and Rationalizing other Taxes Imposed thereon by Amending Sections 28(A)(3)(A), 109, 118 and 236 of the National Internal Revenue Code (NIRC), as Amended, and for Other Purposes","orig":"An Act Recognizing the Principle of Reciprocity as Basis for the Grant of Income Tax Exemptions to International Carriers and Rationalizing other Taxes Imposed thereon by Amending Sections 28(A)(3)(A), 109, 118 and 236 of the National Internal Revenue Code (NIRC), as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 10378","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-07","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10378_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8830-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 28(A)(3)(a) of Republic Act No. 8424, otherwise known as the National Internal Revenue Code of 1997, as amended, is hereby further amended to read as follows:\n\"SEC. 28. Rates of Income Tax on Foreign Corporations. — \"(A) Tax on Resident Foreign Corporations. — \"(1) xxx \"(2) xxx \"(3). International – Carrier. — An international carrier doing business in the Philippines shall pay a tax of two and one-half percent (21/2 %) on its ‘Gross Philippine Billings’ as defined hereunder:\n\"(a) International Air Carrier. — ‘Gross Philippine Billings’ refers to the amount of gross revenue derived from carriage of persons, excess baggage, cargo, and mail originating from the Philippines in a continuous and uninterrupted flight, irrespective of the place of sale or issue and the place of payment of the ticket or passage document: Provided, That tickets revalidated, exchanged and/or indorsed to another international airline form part of the Gross Philippine Billings if the passenger boards a plane in a port or point in the Philippines: Provided, further, That for a flight which originates from the Philippines, but transshipment of passenger takes place at any part outside the Philippines on another airline, only the aliquot portion of the cost of the ticket corresponding to the leg flown from the Philippines to the point of transshipment shall form part of Gross Philippine Billings.\n\"(b) International Shipping. — ‘Gross . Philippine Billings’ means gross revenue whether for passenger, cargo or mail originating from the Philippines up to final destination, regardless of the place of sale or payments of the passage or freight documents.\n\"Provided, That international carriers doing business in the Philippines may avail of a preferential rate or exemption from the tax herein imposed on their gross revenue derived from the carriage of persons and their excess baggage on the basis of an applicable tax treaty or international agreement to which the Philippines is a signatory or on the basis of reciprocity such that an international carrier, whose home country grants income tax exemption to Philippine carriers, shall likewise be exempt from the tax imposed under this provision.\n\"x x x.\""}},{"id":"PH-H8830-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 109 of the National Internal Revenue Code of 1997, as amended, is hereby further amended to read as follows:\n\"SEC. 109. Exempt Transactions. - The following shall be exempt from the value-added tax:\n\"(A) xxx;\n\"xxx \"(S) Transport of passengers by international carriers;\n\"(T) Sale, importation or lease of passenger or cargo vessels and aircraft, including engine, equipment and spare parts thereof for domestic or international transport operations;\n\"(U) Importation of fuel, goods and supplies by persons engaged in international shipping or air transport operations;\n\"(V) Services of bank, non-bank financial intermediaries performing quasi-banking functions, and other non-bank financial intermediaries; and \"(W) Sale or lease of goods or properties or the performance of services other than the transactions mentioned in the preceding paragraphs, the gross annual sales and/or receipts do not exceed the amount of One million five hundred thousand pesos (P1,500,000): Provided, That not later than January 31, 2009 and every three (3) years thereafter, the amount herein stated shall be adjusted to its present value using the Consumer Price Index, as published by. the National Statistics-Office (NSO);\n\"x x x.\""}},{"id":"PH-H8830-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 118 of the National Internal Revenue Code of 1997, as amended, is hereby further amended to read as follows:\n\"SEC. 118. Percentage Tax on International Carriers. — \"(A) International air carriers doing; business in the Philippines on their gross receipts derived from transport of cargo from the Philippines to another country shall pay a tax of three percent (3%) of their quarterly gross receipts.\n\"(B) International shipping carriers doing business in the Philippines on their gross receipts derived from transport of cargo from the Philippines to another country shall pay a tax equivalent to three percent (3%) of their quarterly gross receipts.\""}},{"id":"PH-H8830-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 236 of the National Internal Revenue Code of 1997, as amended, is hereby further amended to read as follows:\n\"SEC. 236. Registration Requirements. — \"(A) Requirements. — x x x \"xxx \"(G) Persons Required to Register for Value-Added Tax. — \"(1) Any person who, in the course of trade or business, sells, barters or exchanges goods or properties, or engages in the sale or exchange of services, shall be liable to register for value-added tax if:\n\"(a) His gross sales or receipts for the past twelve (12) months, other than those that are exempt under Section 109(A) to (V), have exceeded One million five hundred thousand pesos (P1,500,000); or \"(b) There are reasonable grounds to believe that his gross sales or receipts for the next twelve (12) months, other than those that are exempt under Section 109(A) to (V), will exceed One million five hundred thousand pesos (P1,500,000).\n\"x x x.\""}},{"id":"PH-H8830-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Implementing Rules and Regulations. — The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate not later than thirty (30) days upon the effectivity of this Act the necessary rules and regulations for its effective implementation. The Department of Finance (DOF), in coordination with the Department of Foreign Affairs (DFA), shall oversee the exchange of notes between the Philippines and concerned countries for purposes of facilitating the availment of reciprocal exemptions intended under this Act."}},{"id":"PH-H8830-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Separability Clause. — If any provision of this Act is subsequently declared invalid or unconstitutional, other provisions hereof which are not affected thereby shall remain in full force and effect."}},{"id":"PH-H8830-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Repealing Clause. — All laws, acts, presidential decrees, executive orders, issuances, presidential proclamations, rules and regulations or parts thereof which are contrary to and inconsistent with any provision of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H8830-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Effectivily. — This Act shall take effect fifteen (15) days after its complete publication either in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Recognizing the Principle of Reciprocity as Basis for the Grant of Income Tax Exemptions to International Carriers and Rationalizing other Taxes Imposed thereon by Amending Sections 28(A)(3)(A), 109, 118 and 236 of the National Internal Revenue Code (NIRC), as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8831"] = {"id":"PH-H8831","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10379_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在高山省设立高山省第二区工程办公室并为此拨款的法案","en":"An Act Establishing the Mountain Province Second District Engineering Office in the Mountain Province and Appropriating Funds Therefor","orig":"An Act Establishing the Mountain Province Second District Engineering Office in the Mountain Province and Appropriating Funds Therefor","vi":"Đạo luật thành lập Văn phòng Kỹ thuật Mountain Province Second District tại Tỉnh Mountain Province, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสำนักงานวิศวกรรมศาสตร์ Mountain Province Second District ในจังหวัด Mountain Province และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Kantor Teknik Mountain Province Second District di Provinsi Mountain Province, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Pejabat Kejuruteraan Mountain Province Second District di Wilayah Mountain Province, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10379","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10379_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8831-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Public Works and Highways, a second district engineering office in the Mountain Province comprising the municipalities of Barlig, Natonin and Paracelis located in the Municipality of Natonin to be known as the Mountain Province Second District Engineering Office."}},{"id":"PH-H8831-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall include in the Department’s program the operationalization of the Mountain Province Second District Engineering Office, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8831-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect immediately upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing the Mountain Province Second District Engineering Office in the Mountain Province and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8832"] = {"id":"PH-H8832","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10380_2013.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"规定媒体从业人员地方缺席投票的法案","en":"An Act Providing for Local Absentee Voting for Media","orig":"An Act Providing for Local Absentee Voting for Media"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10380","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-14","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10380_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8832-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. – The State shall ensure the free exercise of the right of suffrage by all citizens of the Philippines not otherwise disqualified by law."}},{"id":"PH-H8832-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Local Absentee Voting for Members of Media. – The Commission on Elections shall extend the right to vote under the local absentee voting system provided under existing laws and executive orders to members of media, media practitioners, including the technical and support staff, who are duly registered voters and who, on election day, may not be able to vote due to the performance of their functions in covering and reporting on the elections: Provided, That they shall be allowed to vote only for the positions of President, Vice President, Senators and Party-List Representative."}},{"id":"PH-H8832-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementing Rules and Regulations. – The Commission on Elections shall, within thirty (30) days from the effectivity of this Act, promulgate the implementing rules and regulations which shall include a system of accreditation and verification of the members of media, media practitioners, the technical and support staff, who are qualified to avail of local absentee voting."}},{"id":"PH-H8832-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appropriations. – The initial funding of this Act shall be charged against the current year’s appropriations or from any available savings of the Commission on Elections. Thereafter, such amount as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H8832-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Separability Clause. – If any part or provision of this Act shall be declared unconstitutional or invalid, other provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H8832-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Repealing Clause. – All laws, presidential decrees, executive orders, resolutions, rules and regulations, other issuances, and parts thereof, which are inconsistent with the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H8832-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days following its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Local Absentee Voting for Media","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8833"] = {"id":"PH-H8833","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10381_2013.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"1980年司法重组法","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Three (3) Additional Branches of the Metropolitan Trial Courts of the National Capital Region to be Stationed at Taguig City, Metro Manila, Amending for the Purpose Section 27 of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor","vi":"Đạo luật Tái tổ chức Ngành Tư pháp năm 1980","th":"พระราชบัญญัติการปรับโครงสร้างองค์กรตุลาการ ค.ศ. 1980","id":"Undang-Undang Reorganisasi Kehakiman Tahun 1980","ms":"Akta Penyusunan Semula Kehakiman 1980"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10381","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10381_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8833-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Three (3) additional branches of the Metropolitan Trial Courts of the National Capital Region are hereby created with seats at Taguig City, Metro Manila.\nThe Supreme Court shall assign the branch number of the newly-created branches of the Metropolitan Trial Courts of the National Capital Region."}},{"id":"PH-H8833-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of three (3) additional branches of the Metropolitan Trial Courts of the National Capital Region to be stationed at Taguig City, Metro Manila, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8833-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 27 of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8833-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Judiciary Reorganization Act of 1980","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8834"] = {"id":"PH-H8834","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10382_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将打拉市至San Jose（经Tibag - Burgos）公路改设为国道并为此提供资金的法案","en":"An Act Converting the Tarlac City - San Jose Via Tibag - Burgos Road in the City of Tarlac and the Municipality of San Jose, Province of Tarlac into a National Road and Providing Funds Therefor","orig":"An Act Converting the Tarlac City - San Jose Via Tibag - Burgos Road in the City of Tarlac and the Municipality of San Jose, Province of Tarlac into a National Road and Providing Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10382","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-03-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10382_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8834-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The 19.550-kilometer Tarlac City – San Jose via Tibag – Burgos Road in the City of Tarlac and the Municipality of San Jose, Province of Tarlac is hereby converted into a national road under the jurisdiction and supervision of the Department of Public Works and Highways."}},{"id":"PH-H8834-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the improvement, repair and maintenance of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8834-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p125","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Tarlac City - San Jose Via Tibag - Burgos Road in the City of Tarlac and the Municipality of San Jose, Province of Tarlac into a National Road and Providing Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
